  -- Only referential-action triggers may null a removed user's live FK.
  IF pg_trigger_depth()>1 AND
    (to_jsonb(NEW)-'actorUserId'-'targetUserId')=(to_jsonb(OLD)-'actorUserId'-'targetUserId') AND
    (NEW."actorUserId" IS NOT DISTINCT FROM OLD."actorUserId" OR (NEW."actorUserId" IS NULL AND NOT EXISTS(SELECT 1 FROM "User" WHERE id=OLD."actorUserId"))) AND
    (NEW."targetUserId" IS NOT DISTINCT FROM OLD."targetUserId" OR (NEW."targetUserId" IS NULL AND NOT EXISTS(SELECT 1 FROM "User" WHERE id=OLD."targetUserId")))
  THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'ADMIN_AUDIT_IMMUTABLE';
 ELSIF TG_OP IN ('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'ADMIN_AUDIT_IMMUTABLE';
 END IF;
 IF NEW."requestHash" IS NULL OR NEW."requestHash" !~ '^[0-9a-f]{64}$' OR
    NEW."requestId" !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR NEW."actorIdSnapshot" !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR
    (NEW."targetIdSnapshot" IS NOT NULL AND NEW."targetIdSnapshot" !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') OR
    NEW.reason NOT IN ('SUPPORT','ABUSE','SECURITY','OPERATIONS','RECOVERY') OR
    admin_audit_diff_valid(NEW.action,NEW.before) IS NOT TRUE OR admin_audit_diff_valid(NEW.action,NEW.after) IS NOT TRUE
 THEN RAISE EXCEPTION 'ADMIN_AUDIT_INVALID'; END IF;
 RETURN NEW;
END $$;
