CREATE TRIGGER admin_audit_truncate BEFORE TRUNCATE ON "AdminAuditLog" FOR EACH STATEMENT EXECUTE FUNCTION admin_audit_guard();
-- A definer view is intentional: the operator has no access to the base audit table.
-- Legacy JSON and reasons are discarded, not returned or recursively scrubbed.
CREATE VIEW "AdminAuditSafe" AS SELECT
 CASE WHEN id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN id
 ELSE substr(md5(id),1,8)||'-'||substr(md5(id),9,4)||'-4'||substr(md5(id),14,3)||'-8'||substr(md5(id),18,3)||'-'||substr(md5(id),21,12) END AS id, "createdAt",
 CASE WHEN "actorIdSnapshot" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN "actorIdSnapshot" END AS "actorIdSnapshot",
 CASE WHEN "targetIdSnapshot" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN "targetIdSnapshot" END AS "targetIdSnapshot",
 CASE WHEN "requestId" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN "requestId" END AS "requestId",
 CASE WHEN "requestHash" ~ '^[0-9a-f]{64}$' THEN "requestHash" END AS "requestHash",
 CASE WHEN "requestHash" IS NOT NULL AND admin_audit_diff_valid(action,before) AND admin_audit_diff_valid(action,after) THEN action ELSE 'LEGACY' END AS action,
 CASE WHEN reason IN ('SUPPORT','ABUSE','SECURITY','OPERATIONS','RECOVERY') THEN reason ELSE 'LEGACY' END AS reason,
 CASE WHEN "requestHash" IS NOT NULL AND admin_audit_diff_valid(action,before) THEN
  CASE action WHEN 'PLAN_OVERRIDE' THEN jsonb_build_object('planOverride',before->'planOverride','startsAt',before->'startsAt','expiresAt',before->'expiresAt') WHEN 'SUSPENSION' THEN jsonb_build_object('isSuspended',before->'isSuspended') WHEN 'SENDING_CONTROL' THEN jsonb_build_object('sendingEnabled',before->'sendingEnabled') ELSE jsonb_build_object('isAdmin',before->'isAdmin') END ELSE '{}'::jsonb END AS before,
 CASE WHEN "requestHash" IS NOT NULL AND admin_audit_diff_valid(action,after) THEN
  CASE action WHEN 'PLAN_OVERRIDE' THEN jsonb_build_object('planOverride',after->'planOverride','startsAt',after->'startsAt','expiresAt',after->'expiresAt') WHEN 'SUSPENSION' THEN jsonb_build_object('isSuspended',after->'isSuspended') WHEN 'SENDING_CONTROL' THEN jsonb_build_object('sendingEnabled',after->'sendingEnabled') ELSE jsonb_build_object('isAdmin',after->'isAdmin') END ELSE '{}'::jsonb END AS after
FROM "AdminAuditLog";
