import { z } from "zod";
import { issueSignedToken } from "@vercel/blob";
import {
  handleUpload,
  handleUploadPresigned,
  type HandleUploadBody,
  type HandleUploadPresignedBody,
} from "@vercel/blob/client";
import { db } from "@/lib/db";
import { DELETION_DRAIN_MS } from "@/lib/account";
import { auth } from "@/auth";
import { validStoragePath, discardUnactivatedResume } from "@/lib/storage";
import { MAX_PDF_BYTES } from "@/lib/validation";
export async function POST(request: Request) {
  let cleanupFailed = false;
  try {
    const body = (await request.json()) as
      HandleUploadBody | HandleUploadPresignedBody;
    const authorize = async (pathname: string) => {
      const session = await auth();
      if (
        !session?.user.id ||
        request.headers.get("origin") !== new URL(request.url).origin ||
        !validStoragePath(session.user.id, pathname)
      )
        throw new Error("Unauthorized upload.");
      const user = await db.$transaction(async (tx) => {
        await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${session.user.id} FOR UPDATE`;
        return tx.user.findFirst({
          where: {
            id: session.user.id,
            deletionRequestedAt: null,
            isSuspended: false,
          },
          select: { id: true },
        });
      });
      if (!user) throw new Error("Account unavailable.");
      return user.id;
    };
    const onUploadCompleted = async ({
      blob,
      tokenPayload,
    }: {
      blob: { pathname: string };
      tokenPayload?: string | null;
    }) => {
      const { userId } = z
        .object({ userId: z.uuid() })
        .parse(JSON.parse(tokenPayload ?? "{}"));
      if (!validStoragePath(userId, blob.pathname))
        throw new Error("Invalid upload location.");
      try {
        await discardUnactivatedResume(
          userId,
          blob.pathname,
          new Date(Date.now() - DELETION_DRAIN_MS),
        );
      } catch {
        cleanupFailed = true;
        throw new Error("Upload cleanup requires retry.");
      }
    };
    const response =
      process.env.BLOB_STORE_ID && !process.env.BLOB_READ_WRITE_TOKEN
        ? await handleUploadPresigned({
            body: body as HandleUploadPresignedBody,
            request,
            getSignedToken: async (pathname) => {
              const userId = await authorize(pathname);
              const validUntil = Date.now() + 10 * 60000;
              return {
                token: await issueSignedToken({
                  pathname,
                  operations: ["put"],
                  validUntil,
                  allowedContentTypes: ["application/pdf"],
                  maximumSizeInBytes: MAX_PDF_BYTES,
                }),
                urlOptions: {
                  validUntil,
                  allowedContentTypes: ["application/pdf"],
                  maximumSizeInBytes: MAX_PDF_BYTES,
                  addRandomSuffix: false,
                  allowOverwrite: false,
                  tokenPayload: JSON.stringify({ userId }),
                },
              };
            },
            onUploadCompleted,
          })
        : await handleUpload({
            body: body as HandleUploadBody,
            request,
            onBeforeGenerateToken: async (pathname) => {
              const userId = await authorize(pathname);
              return {
                allowedContentTypes: ["application/pdf"],
                maximumSizeInBytes: MAX_PDF_BYTES,
                addRandomSuffix: false,
                allowOverwrite: false,
                tokenPayload: JSON.stringify({ userId }),
                validUntil: Date.now() + 10 * 60000,
              };
            },
            onUploadCompleted,
          });
    return Response.json(response);
  } catch {
    return Response.json(
      { error: "Secure upload failed. Sign in and try again." },
      { status: cleanupFailed ? 503 : 400 },
    );
  }
}

import { auth } from "@/auth";
import { db } from "@/lib/db";
import { readAttachment } from "@/lib/storage";
export async function GET() {
  const session = await auth();
  if (!session?.user.id) return new Response("Sign in first.", { status: 401 });
  const user = await db.user.findUnique({
    where: { id: session.user.id },
    select: { currentAttachmentId: true, deletionRequestedAt: true },
  });
  if (!user || user.deletionRequestedAt)
    return new Response("Account unavailable.", { status: 403 });
  const file = user?.currentAttachmentId
    ? await db.attachment.findFirst({
        where: { id: user.currentAttachmentId, userId: session.user.id },
      })
    : null;
  if (!file) return new Response("No PDF uploaded.", { status: 404 });
  try {
    const bytes = await readAttachment(session.user.id, file.storagePath);
    return new Response(new Uint8Array(bytes), {
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `attachment; filename*=UTF-8''${encodeURIComponent(file.fileName)}`,
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new Response("PDF unavailable. Upload it again.", {
      status: 404,
    });
  }
}

import { auth } from "@/auth";
import { storeLocalResume } from "@/lib/storage";
import { MAX_PDF_BYTES } from "@/lib/validation";
export async function POST(request: Request) {
  const session = await auth();
  if (!session?.user.id)
    return Response.json({ error: "Sign in first." }, { status: 401 });
  if (request.headers.get("origin") !== new URL(request.url).origin)
    return Response.json({ error: "Invalid origin." }, { status: 403 });
  if (Number(request.headers.get("content-length")) > MAX_PDF_BYTES + 65536)
    return Response.json(
      { error: "Choose a PDF up to 5 MB." },
      { status: 413 },
    );
  try {
    const reader = request.body?.getReader();
    if (!reader)
      return Response.json({ error: "Choose a PDF." }, { status: 400 });
    const abortSignal = AbortSignal.timeout(30000);
    abortSignal.addEventListener(
      "abort",
      () => {
        void reader.cancel().catch(() => {});
      },
      { once: true },
    );
    const chunks: Uint8Array[] = [];
    let size = 0;
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        size += value.length;
        if (size > MAX_PDF_BYTES + 65536) {
          await reader.cancel();
          return Response.json(
            { error: "Choose a PDF up to 5 MB." },
            { status: 413 },
          );
        }
        abortSignal.throwIfAborted();
        chunks.push(value);
      }
    } finally {
      reader.releaseLock();
    }
    abortSignal.throwIfAborted();
    const boundedRequest = new Request(request.url, {
      method: "POST",
      headers: { "content-type": request.headers.get("content-type") ?? "" },
      body: new Uint8Array(Buffer.concat(chunks)),
    });
    const form = await boundedRequest.formData();
    const file = form.get("file");
    if (!(file instanceof File))
      return Response.json({ error: "Choose a PDF." }, { status: 400 });
    await storeLocalResume(session.user.id, file);
    return Response.json({ ok: true });
  } catch {
    return Response.json(
      { error: "Could not upload. Choose a valid PDF up to 5 MB." },
      { status: 400 },
    );
  }
}

import { consumeBudgets, rateLimitHttpError } from "@/lib/rate-limit";
import { auth } from "@/auth";
import { db } from "@/lib/db";
import { z } from "zod";

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const headers = { "Cache-Control": "private, no-store" };
  const session = await auth();
  if (!session?.user?.id)
    return new Response("Unauthorized", { status: 401, headers });
  try {
    await consumeBudgets(session.user.id, ["export"]);
  } catch (error) {
    return (
      rateLimitHttpError(error) ??
      new Response("Unavailable", { status: 503, headers })
    );
  }
  const id = z.uuid().safeParse((await params).id);
  if (!id.success) return new Response("Not found", { status: 404, headers });
  const template = await db.template.findFirst({
    where: {
      id: id.data,
      userId: session.user.id,
      user: { deletionRequestedAt: null },
    },
    select: { id: true, name: true, subject: true, body: true },
  });
  if (!template) return new Response("Not found", { status: 404, headers });
  return new Response(JSON.stringify(template, null, 2), {
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Content-Disposition": `attachment; filename="template-${template.id}.json"`,
      "Cache-Control": "private, no-store",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

import { after } from "next/server";
import { billingConfig, BillingError } from "@/lib/billing/config";
import { Webhook } from "standardwebhooks";
import { storeBillingEvent } from "@/lib/billing/webhooks";
import { processBillingEvent } from "@/lib/billing/lifecycle";

export const runtime = "nodejs";
export const maxDuration = 300;
const MAX_BODY_BYTES = 256 * 1024;

export async function POST(request: Request) {
  try {
    billingConfig();
  } catch {
    return Response.json(
      { error: "Webhook configuration unavailable." },
      { status: 503 },
    );
  }
  const headers = Object.fromEntries(
    ["webhook-id", "webhook-signature", "webhook-timestamp"].map((key) => [
      key,
      request.headers.get(key) ?? "",
    ]),
  );
  if (
    Object.values(headers).some((value) => !value) ||
    headers["webhook-id"].length > 200
  )
    return Response.json({ error: "Invalid signature." }, { status: 401 });
  let raw: string;
  try {
    const reader = request.body?.getReader();
    const chunks: Uint8Array[] = [];
    let size = 0;
    if (reader)
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > MAX_BODY_BYTES) {
          await reader.cancel();
          return new Response(null, { status: 413 });
        }
        chunks.push(value);
      }
    raw = new TextDecoder("utf-8", { fatal: true }).decode(
      Buffer.concat(chunks),
    );
  } catch {
    return new Response(null, { status: 400 });
  }
  let verified: unknown;
  try {
    // The pinned verifier checks Standard Webhooks against
    // the exact raw body, including timestamp tolerance. No session is involved.
    verified = new Webhook(billingConfig().webhookKey).verify(raw, headers);
  } catch {
    return Response.json({ error: "Invalid signature." }, { status: 401 });
  }
  try {
    const event = await storeBillingEvent(raw, verified, headers["webhook-id"]);
    if (
      event &&
      !event.processedAt &&
      ["RECEIVED", "RETRY"].includes(event.state)
    )
      after(async () => {
        await processBillingEvent(event.id).catch(() => {
          /* Committed inbox and nextAttemptAt are retried by scheduled recovery. */
        });
      });
    return Response.json({ received: true });
  } catch (error) {
    if (error instanceof BillingError)
      return Response.json({ error: error.message }, { status: error.status });
    if (error instanceof Error && error.name === "ZodError")
      return Response.json(
        { error: "Invalid webhook payload." },
        { status: 400 },
      );
    return Response.json(
      { error: "Webhook storage unavailable." },
      { status: 503 },
    );
  }
}

/* Preserve the existing motion cascade above shared native button rules. */
html .appearance-control .appearance-menu .appearance-grid button {
  transform: none;
  filter: none;
  transition:
    background-color 180ms ease,
    border-color 180ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}
.appearance-preview {
  --preview-bg: var(--color-appearance-control-preview-bg-2);
  --preview-ink: var(--color-appearance-control-preview-ink-3);
  --preview-accent: var(--color-appearance-control-preview-accent-4);
}
.appearance-preview-purple-dark {
  --preview-bg: var(--color-appearance-control-preview-bg-6);
  --preview-ink: var(--color-appearance-control-preview-ink-7);
  --preview-accent: var(--color-appearance-control-preview-accent-8);
}
