  outline: 2px solid var(--accent);
  outline-offset: -2px;
}
@container (max-width: 600px) {
  .workspace-nav-label {
    display: grid;
    grid-template-columns: 1fr;
    opacity: 1;
    transition:
      grid-template-columns 0.32s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.2s;
  }
  .workspace-nav-label > span {
    overflow: hidden;
    min-width: 0;
  }
  .workspace-nav a:not([aria-current="page"]) .workspace-nav-label {
    grid-template-columns: 0fr;
    opacity: 0;
  }
  .workspace-nav a:not([aria-current="page"]) {
    gap: 0;
  }
  .workspace-nav a {
    padding-inline: 0.85em;
  }
}
@container (max-width: 600px) {
  .workspace-nav-placeholder:not(:first-child) {
    width: 2.85em;
  }
}
@media (forced-colors: active) {
  .workspace-nav a[aria-current="page"] {
    outline: 1px solid LinkText;
    outline-offset: -1px;
  }
}
.compose-grid > *,
.template-grid > *,
main section {
  min-width: 0;
}
.placeholder-chip {
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease;
}
.placeholder-chip:hover:not(:disabled) {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--accent-soft));
}
/* Only message content scrolls; recipient, subject, and feedback stay outside. */
.mail-preview-body ul,
.mail-preview-body ol {
  margin: 0;
  padding-left: 24px;
  white-space: normal;
}
.mail-preview-body ul {
  list-style: disc;
}
.mail-preview-body ol {
  list-style: decimal;
}
.mail-preview-body li {
  white-space: pre-wrap;
}
.mail-preview mark {
  background: var(--placeholder-background);
  color: var(--placeholder-foreground);
  padding: 0 4px;
  border-radius: 5px;
}
.mail-preview mark.invalid {
  background: color-mix(in srgb, var(--error) 15%, transparent);
  color: var(--status-error-text);
  outline: 1px dashed var(--error);
}
[data-theme="dark"] .status-sent {
  color: var(--color-globals-color-50);
  background: color-mix(
    in srgb,
    var(--color-globals-background-49) 12%,
    transparent
  );
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-globals-background-49) 24%, transparent);
}
[data-theme="dark"] .status-replied {
  color: var(--color-globals-replied-38);
  background: color-mix(
    in srgb,
    var(--color-globals-background-52) 12%,
    transparent
  );
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-globals-background-52) 24%, transparent);
}
.live-dot,
.status-queued .status-dot {
  animation: status-pulse 1.4s ease-in-out infinite;
}
@keyframes status-pulse {
  50% {
    opacity: 0.45;
  }
}
.progress-ring circle {
  transition:
    stroke-dasharray 600ms ease,
    stroke-dashoffset 600ms ease,
    opacity 300ms ease;
}
.progress-ring .countdown-arc {
  transition: none;
}
.completion-check {
  animation: completion-check-enter 450ms ease-out both;
}
.completion-check-path {
  animation: completion-check-draw 450ms ease-out both;
}
@keyframes completion-check-enter {
  from {
    opacity: 0;
    transform: scale(0.85);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes completion-check-draw {
  from {
    stroke-dashoffset: 1;
  }
  to {
    stroke-dashoffset: 0;
  }
}
.queue-meter {
  transition: width 600ms ease;
}
.progress-ring svg {
  overflow: visible;
}
.progress-arc {
  filter: drop-shadow(
      0 0 4px color-mix(in srgb, var(--accent) 35%, transparent)
    )
    drop-shadow(0 0 3px color-mix(in srgb, var(--accent2) 25%, transparent));
}
/* One field indicator across shared controls, page styles, and appearances.
   Keep native non-text controls on their existing focus styles. */
html
  :is(
    input:not(
      [type="checkbox"],
      [type="radio"],
      [type="file"],
      [type="range"],
      [type="color"],
      [type="hidden"],
      [type="button"],
      [type="submit"],
      [type="reset"],
      [type="image"]
    ),
    select,
    textarea
  ):focus-visible:not(:disabled) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  box-shadow: none;
}
/* Search fields share their visible boundary with an icon and padding. */
html .field-focus-wrapper:has(input:focus-visible) {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  box-shadow: none;
}
html .field-focus-wrapper input:focus-visible:not(:disabled) {
  outline: none;
  box-shadow: none;
}
button:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 4px;
}
th {
  font:
    600 11px ui-monospace,
    monospace;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
th,
td {
  padding: 14px 16px;
}
table {
  min-width: 560px;
}
textarea {
  font-family: var(--font-sans);
  resize: vertical;
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
  .skeleton::after {
    display: none;
  }
}
.success-confirmation p,
.success-toast p {
  min-width: 0;
  overflow-wrap: anywhere;
}
.recipient-header input {
  flex-shrink: 0;
}
.recipient-card-emailed {
  --recipients-label: var(--recipients-pill-text);
  --recipients-text-muted: var(--recipients-pill-text);
}
.recipient-details dt {
  color: var(--recipients-label);
  font-weight: 500;
}
.recipient-details dd {
  min-width: 0;
  overflow-wrap: anywhere;
}

/* Paid templates: compact rows with one expanded message at a time. */
@keyframes template-backdrop-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes template-backdrop-out {
  from {
    opacity: var(--template-backdrop-from, 1);
  }
  to {
    opacity: 0;
  }
}

/* Free templates: one active message with an open plan sidebar. */
.free-retained-card {
  min-width: 0;
  border: 1px solid var(--template-rule);
  border-radius: 16px;
  background: var(--card);
}
#active-free-template-title:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 4px;
}
#active-free-template-title {
  scroll-margin-top: 24px;
}
.free-retained-export {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-top: 1px dotted var(--separator);
}
.free-template-plan {
  min-width: 0;
  padding: 12px 0 12px 24px;
  border-left: 1px dotted var(--separator);
}
@media (max-width: 860px) {
  .free-template-plan {
    padding: 24px 0 0;
    border-left: 0;
    border-top: 1px dotted var(--separator);
  }
}
@media (max-width: 480px) {
  .free-retained-card {
    padding: 20px;
  }
  .free-retained-controls,
  .free-retained-controls button {
    width: 100%;
  }
}

/* Shared page help. Each animation owns a separate transform layer. */
.help-launcher {
  transition:
    opacity 200ms ease-in,
    transform 200ms ease-in;
}
.help-launcher[data-state="dismissing"] {
  transform: scale(0.8);
}
body:has(.help-launcher) .success-toast {
  bottom: max(140px, calc(env(safe-area-inset-bottom) + 120px));
}
body:has(.help-launcher) footer.page-container {
  padding-bottom: 130px;
}
.help-button-pop {
  animation: help-pop 0.6s 0.2s cubic-bezier(0.34, 1.56, 0.64, 1) backwards;
}
.help-dismiss {
  --button-transform-duration: 150ms;
  transition: transform 150ms;
}
.help-dismiss svg {
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  pointer-events: none;
}
.help-dismiss:hover,
.help-dismiss:focus-visible {
  transform: scale(1.1);
}
.help-dismiss:active {
  transform: scale(0.9);
}
@media (pointer: coarse) {
  .help-dismiss::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 32px;
    height: 32px;
    transform: translate(-50%, -50%);
    border-radius: 50%;
  }
}
.help-button::after {
  content: "";
  position: absolute;
  inset: -1px;
  border: 2px solid var(--accent);
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  animation: help-pulse 3.2s 2s ease-out infinite;
}
.help-button:hover {
  animation: help-wiggle 0.5s ease;
}
.help-button:active {
  animation: none;
  transform: scale(0.96);
}
.help-cloud-visibility {
  transition:
    opacity 0.2s,
    transform 0.2s;
}
.help-cloud-entrance {
  transform-origin: 85% 100%;
  animation: help-cloud-enter 0.55s 0.7s cubic-bezier(0.34, 1.56, 0.64, 1)
    backwards;
}
.help-cloud {
  animation: help-cloud-float 3.6s 1.3s ease-in-out infinite;
}
.help-cloud::before,
.help-cloud::after {
  content: "";
  position: absolute;
  border: 1px solid var(--border);
  border-radius: 50%;
  background: var(--surface);
}
.help-cloud::before {
  width: 9px;
  height: 9px;
  right: 14px;
  bottom: -9px;
}
.help-cloud::after {
  width: 5px;
  height: 5px;
  right: 10px;
  bottom: -17px;
}
@keyframes help-pop {
  from {
    opacity: 0;
    transform: scale(0.3) rotate(-30deg);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes help-pulse {
  0% {
    opacity: 0.55;
    transform: scale(1);
  }
  60%,
  100% {
    opacity: 0;
    transform: scale(1.7);
  }
}
@keyframes help-wiggle {
  25% {
    transform: rotate(-12deg) scale(1.08);
  }
  55% {
    transform: rotate(9deg) scale(1.08);
  }
  80% {
    transform: rotate(-4deg) scale(1.06);
  }
}
@keyframes help-cloud-enter {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.6);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes help-cloud-float {
  50% {
    transform: translateY(-3px);
  }
}

/* The fullscreen native dialog provides modal focus containment and inertness. */
dialog.tutorial-dialog {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100dvh;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: max(16px, env(safe-area-inset-top))
    max(16px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom))
    max(16px, env(safe-area-inset-left));
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow-y: auto;
}
dialog.tutorial-dialog[open] {
  display: flex;
}
dialog.tutorial-dialog::backdrop {
  background: var(--color-globals-background-58);
  backdrop-filter: blur(3px);
  animation: tutorial-backdrop-in 0.22s ease-out;
}
dialog.tutorial-dialog[data-phase="closing"]::backdrop {
  animation: tutorial-backdrop-out 0.2s ease-in forwards;
}
.tutorial-card {
  animation: tutorial-card-in 0.38s cubic-bezier(0.2, 0.9, 0.25, 1.05) both;
}
.tutorial-card[data-phase="closing"] {
  animation: tutorial-card-out 0.2s ease-in forwards;
}
.tutorial-close svg {
  transition: transform 0.2s;
}
.tutorial-close:hover svg {
  transform: rotate(90deg);
}
.tutorial-progress > span {
  display: block;
  height: 100%;
  background: var(--accent);
  transform-origin: left;
  transition: transform 0.45s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.tutorial-title,
.tutorial-text,
.tutorial-visual {
  animation: tutorial-stagger 0.42s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}
.tutorial-text {
  animation-delay: 0.06s;
}
.tutorial-visual {
  animation-delay: 0.12s;
}
.step-out {
  animation: tutorial-step-out 0.15s ease-in forwards;
}
.step-in {
  animation: tutorial-step-in 0.24s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;
}
.tutorial-arrow {
  --button-transform-duration: 200ms;
  transition: transform 0.2s;
}
.tutorial-arrow:hover:not(:disabled) {
  transform: scale(1.1);
}
.tutorial-arrow:active:not(:disabled) {
  transform: scale(0.94);
}
.tutorial-dot-slot > span {
  position: relative;
  display: block;
  width: 6px;
  height: 6px;
  margin-left: 6px;
  border-radius: 50%;
  background: var(--body);
}
.tutorial-dot-slot > span::after {
  content: "";
  position: absolute;
  inset: 0 auto 0 -6px;
  width: 18px;
  height: 6px;
  border-radius: 999px;
  background: var(--accent);
  opacity: 0;
  transform: scaleX(0.333333);
  transition:
    transform 0.2s,
    opacity 0.2s;
}
.tutorial-dot-slot > span.is-active {
  background: var(--accent);
}
.tutorial-dot-slot > span.is-active::after {
  opacity: 1;
  transform: scaleX(1);
}
.tutorial-done {
  --button-transform-duration: 200ms;
  transition: transform 0.2s;
}
:root[data-theme="light"] .tutorial-done {
  color: var(--color-globals-white);
}
.tutorial-done:hover {
  transform: translateY(-1px);
}
.tutorial-done:active {
  transform: scale(0.97);
}
.help-button:focus-visible,
.help-dismiss:focus-visible,
.tutorial-card button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 20%, transparent);
}
@keyframes tutorial-backdrop-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes tutorial-backdrop-out {
  to {
    opacity: 0;
  }
}
@keyframes tutorial-card-in {
  from {
    opacity: 0;
    transform: translateY(18px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tutorial-card-out {
  to {
    opacity: 0;
    transform: translateY(10px) scale(0.97);
  }
}
@keyframes tutorial-step-out {
  to {
    opacity: 0;
    transform: translateX(calc(var(--travel) * -28px));
  }
}
@keyframes tutorial-step-in {
  from {
    opacity: 0;
    transform: translateX(calc(var(--travel) * 28px));
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes tutorial-stagger {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.tutorial-hint small {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  color: var(--body);
  font-size: 11px;
}
.tutorial-hint p {
  margin: 0;
}
.tutorial-hint mark {
  background: var(--placeholder-background);
  color: var(--placeholder-foreground);
}
.tutorial-mini-field > span {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
}
.tutorial-mini-field svg {
  flex-shrink: 0;
}
.tutorial-mini-chips > span {
  padding: 4px 7px;
  border: 1px dashed var(--border);
  border-radius: 999px;
  color: var(--link);
  background: var(--accent-soft);
}
.tutorial-mini-row > div {
  min-width: 0;
}
.tutorial-mini-ring.is-draft {
  background: var(--queued);
}
.tutorial-mini-ring > span {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 84px;
  height: 84px;
  border-radius: 50%;
  background: var(--surface);
}
.tutorial-mini-ring strong {
  font-family: var(--font-num);
  font-size: 20px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.tutorial-mini-legend > span {
  display: flex;
  justify-content: space-between;
  gap: 14px;
}
.tutorial-mini-totals strong {
  font-size: 22px;
}
@media (prefers-reduced-motion: reduce) {
  .help-launcher,
  .help-launcher *,
  .help-launcher *::after,
  .tutorial-dialog,
  .tutorial-dialog::backdrop,
  .tutorial-card,
  .tutorial-card * {
    animation: none !important;
    transition: none !important;
  }
}

/* Scoped header and Compose readiness presentation. */
@media (width < 640px) {
  .workspace-header-brand .workspace-brand-tagline,
  .workspace-footer .workspace-brand-tagline {
    font-size: 12px;
  }
}
.workspace-header-controls {
  --workspace-track: var(--color-globals-workspace-track-60);
}
[data-theme="dark"] .workspace-header-controls {
  --workspace-track: var(--color-globals-workspace-track-61);
}
.workspace-header-controls .theme-track {
  flex-shrink: 0;
}
.workspace-header-controls .theme-track button,
.workspace-header-controls .theme-thumb {
  width: 34px;
  height: 34px;
}
.workspace-header-controls .theme-track svg {
  width: 16px;
  height: 16px;
}
[data-theme="dark"] .workspace-header-controls .theme-thumb {
  transform: translateX(34px);
}
.workspace-gmail[data-connected="false"] .workspace-gmail-dot {
  background: var(--color-globals-queued-39);
  box-shadow: 0 0 0 4px var(--color-globals-box-shadow-67);
}
.workspace-account-trigger > svg {
  transition: transform 150ms;
}
.workspace-account-trigger[aria-expanded="true"] > svg {
  transform: rotate(180deg);
}
.workspace-account-menu {
  transform-origin: top right;
  animation: workspace-menu-enter 140ms ease-out;
}
.workspace-header-controls button:focus-visible,
.compose-send-button:focus-visible {
  outline: 2px solid var(--accent, var(--color-globals-outline-71));
  outline-offset: 2px;
}
@keyframes workspace-menu-enter {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
.send-checklist {
  --checklist-background: var(--color-globals-background-70);
  --checklist-ring: var(--color-globals-checklist-ring-72);
  --checklist-ok: var(--color-globals-checklist-ok-73);
}
[data-theme="dark"] .send-checklist {
  --checklist-background: var(--color-globals-checklist-background-74);
  --checklist-ring: var(--color-globals-checklist-ring-75);
  --checklist-ok: var(--color-globals-success-37);
}
.send-checklist-empty {
  transition: opacity 200ms;
  transition-delay: var(--checklist-delay);
}
.send-checklist-icon circle,
.send-checklist-icon path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  opacity: 0;
  transition:
    stroke-dashoffset 350ms ease-out,
    opacity 200ms;
  transition-delay: var(--checklist-delay);
}
.send-checklist-row[data-done="true"] .send-checklist-empty {
  opacity: 0;
}
.send-checklist-row[data-done="true"] circle,
.send-checklist-row[data-done="true"] path {
  stroke-dashoffset: 0;
  opacity: 1;
}
.send-checklist-icon[data-phase="done"] {
  animation: checklist-pop 300ms ease-out backwards;
  animation-delay: var(--checklist-delay);
}
.send-checklist-icon[data-phase="undone"] {
  animation: checklist-unpop 300ms ease-out backwards;
  animation-delay: var(--checklist-delay);
}
.send-checklist-label {
  transition:
    color 200ms,
    font-weight 200ms;
  transition-delay: var(--checklist-delay);
}
.send-checklist-hint {
  transition:
    opacity 200ms,
    max-height 200ms;
  transition-delay: var(--checklist-delay);
}
.send-checklist-glow {
  animation: checklist-ready 600ms ease-out;
}
.compose-send-button {
  transition:
    background-color 250ms,
    color 250ms,
    opacity 250ms,
    box-shadow 250ms;
}
@keyframes checklist-pop {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.18);
  }
}
@keyframes checklist-unpop {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(0.85);
  }
}
@keyframes checklist-ready {
  0%,
  100% {
    opacity: 0;
    box-shadow: 0 0 0 transparent;
  }
  45% {
    opacity: 1;
    box-shadow: 0 0 16px color-mix(in srgb, var(--accent) 30%, transparent);
  }
}
@media (prefers-reduced-motion: reduce) {
  .workspace-header-controls *,
  .send-checklist *,
  .compose-send-button {
    animation: none !important;
    transition: none !important;
  }
}

/* Successful completion shares the same proportions at both ring sizes. */
.completion-ring {
  filter: drop-shadow(0 0 6px var(--color-globals-filter-77));
}
.completion-inner {
  transform: translate(-50%, -50%);
}
[data-theme="dark"] .completion-badge {
  box-shadow: 0 6px 20px var(--color-globals-box-shadow-81);
}
.ring-completion .completion-check,
.ring-completion .completion-check-path {
  animation: none;
}
.completion-ripple {
  transform: translate(-50%, -50%);
}
.is-entering .completion-badge {
  animation: completion-badge-pop 600ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.is-entering .completion-ripple {
  animation: completion-ripple 800ms ease-out 100ms both;
}
.is-entering .completion-check-path {
  animation: completion-check-draw 400ms ease-out 200ms both;
}
.is-entering .completion-label {
  animation: completion-label-enter 400ms ease-out 350ms both;
}
.completion-countdown-exit {
  animation: completion-countdown-fade 500ms ease-out;
}
@keyframes completion-badge-pop {
  from {
    opacity: 0;
    transform: scale(0.5);
  }
