"use client";
import { useEffect, useRef, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Search } from "lucide-react";
import styles from "./history.module.css";
const statuses = [
  ["", "All"],
  ["SENT", "Sent"],
  ["REPLIED", "Replied"],
  ["QUEUED", "Queued"],
  ["FAILED", "Failed"],
  ["CANCELLED", "Cancelled"],
] as const;
export function HistoryToolbar({
  q,
  status,
  campaign,
}: {
  q: string;
  status: string;
  campaign?: string;
}) {
  // Remount only when the confirmed URL changes, not when queue polling refreshes data.
  return (
    <Toolbar
      key={`${q}:${status}:${campaign ?? ""}`}
      q={q}
      status={status}
      campaign={campaign}
    />
  );
}
function Toolbar({
  q,
  status,
  campaign,
}: {
  q: string;
  status: string;
  campaign?: string;
}) {
  const router = useRouter();
  const [value, setValue] = useState(q);
  const [pending, start] = useTransition();
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  function navigate(search: string, filter: string) {
    clearTimeout(timer.current);
    const params = new URLSearchParams();
    if (search) params.set("q", search);
    if (filter) params.set("status", filter);
    if (campaign) params.set("campaign", campaign);
    start(() =>
      router.push(`/history?${params.toString()}`, { scroll: false }),
    );
  }
  return (
    <form
      method="get"
      action="/history"
      className="flex items-center flex-wrap gap-3 mb-4"
      aria-busy={pending}
      onSubmit={(event) => {
        event.preventDefault();
        navigate(value, status);
      }}
    >
      {campaign && <input type="hidden" name="campaign" value={campaign} />}
      <input type="hidden" name="status" value={status} />
      <label
        className={`field-focus-wrapper ${styles.search} flex items-center gap-2.5 flex-1 min-w-55 h-11.5 py-0 px-4 [border:1px_solid_var(--h-border)] rounded-[var(--appearance-radius,_14px)] [background:var(--h-surface)] text-[var(--h-muted)] [@media(max-width:_859px)]:[flex-basis:100%] [@media(max-width:_859px)]:min-w-0`}
      >
        <Search size={18} aria-hidden="true" />
        <span className="sr-only">Search history</span>
        <input
          className="w-full min-w-0 h-full border-0 p-0 bg-transparent text-[var(--h-text)] shadow-[var(--appearance-shadow,none)] placeholder:text-[var(--h-muted)]"
          name="q"
          type="search"
          autoComplete="off"
          value={value}
          placeholder="Search recipients or companies…"
          onChange={(event) => {
            const next = event.target.value;
            setValue(next);
            clearTimeout(timer.current);
            timer.current = setTimeout(() => navigate(next, status), 250);
          }}
        />
      </label>
      <div
        className="flex flex-wrap gap-1.5"
        role="group"
        aria-label="Filter by status"
      >
        {statuses.map(([filter, label]) => (
          <button
            key={filter}
            type="button"
            className={`${styles.chip} py-2 px-3.5 [border:1px_solid_var(--h-border)] rounded-full text-[var(--h-muted)] text-[13px] font-semibold [background:var(--h-surface)] [&[aria-pressed='true']]:[background:var(--appearance-wash,_var(--color-history-h-border-12))] [&[aria-pressed='true']]:border-[var(--h-purple)] [&[aria-pressed='true']]:text-[var(--h-text)]`}
            aria-pressed={status === filter}
            onClick={() => navigate(value, filter)}
          >
            {label}
          </button>
        ))}
      </div>
    </form>
  );
}

"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";
import { useRef, useState, useTransition } from "react";
import { Check, Crown, LoaderCircle, Plus } from "lucide-react";
import { useRouter } from "next/navigation";
import { markReplied, undoReply } from "@/lib/recipient-actions";
import { addToShortlist } from "@/lib/actions";
import {
  useWorkspaceEntitlements,
  refreshWorkspaceAccess,
} from "@/components/workspace-quota";
import { Tooltip } from "@/components/ui/Tooltip";
import type { ActionResult } from "@/lib/errors";
import { PremiumTooltip } from "./HistoryInfoRow";
import styles from "./history.module.css";
import { cn } from "@/lib/utils";
export type ShortlistState = {
  inShortlist: boolean;
  blocked: boolean;
  active: boolean;
};
export function RowActions({
  id,
  status,
  shortlist,
}: {
  id: string;
  status: string;
  shortlist: ShortlistState;
}) {
  if (status === "CANCELLED") {
    return (
      <div className="flex justify-end">
        <Tooltip
          className="history-surface"
          content="No actions available for cancelled emails."
        >
          <span
            role="note"
            tabIndex={0}
            aria-label="No actions available for cancelled emails."
            className="inline-flex h-8.5 w-8.5 items-center justify-center rounded-full text-[var(--h-muted)]"
          >
            —
          </span>
        </Tooltip>
      </div>
    );
  }
  if (status !== "SENT" && status !== "REPLIED") return null;
  return (
    <div className={`${styles.actions} flex justify-end gap-1.5`}>
      <ReplyAction id={id} status={status} />
      <ShortlistAction id={id} shortlist={shortlist} />
    </div>
  );
}
function ReplyAction({ id, status }: { id: string; status: string }) {
  const upgrade = usePremiumUpgrade();
  const access = useWorkspaceEntitlements();
  const locked = !access.features.markReplied;
  const replied = status === "REPLIED";
  const explanation = replied ? "Replied. Click to undo" : "Mark replied";
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const busy = useRef(false);
  const router = useRouter();
  if (status !== "SENT" && !replied) return null;
  function run() {
    if (pending || busy.current) return;
    if (locked) return upgrade({ feature: "replied" });
    busy.current = true;
    setResult(undefined);
    start(async () => {
      try {
        setResult(await (replied ? undoReply(id) : markReplied(id)));
        refreshWorkspaceAccess();
        router.refresh();
      } catch {
        setResult({
          ok: false,
          message: replied
            ? "Could not undo this reply. Please try again."
            : "Could not save this change. Please try again.",
        });
      } finally {
        busy.current = false;
      }
    });
  }
  return (
    <div>
      <Tooltip
        className="history-surface"
        interactive={locked}
        content={
          locked ? (
            <PremiumTooltip actionDescription={explanation} />
          ) : (
            explanation
          )
        }
      >
        <button
          type="button"
          className={cn(
            styles.action,
            "cursor-pointer grid place-items-center w-8.5 h-8.5 p-0 border border-solid border-[var(--appearance-border,_var(--color-history-border-color-18))] rounded-[50%] relative [background:transparent] text-[var(--h-text)] css-hover:[background:var(--appearance-wash,_var(--color-history-background-22))] [&[aria-disabled='true']]:opacity-[0.5] [&[aria-disabled='true']]:cursor-default",
            locked
              ? "border-dashed"
              : replied
                ? `${styles.active} [background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))] css-hover:[background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-history-h-purple-13),_var(--color-history-h-pink-14)))] text-[var(--appearance-on-primary,_var(--color-history-color-21))] css-hover:text-[var(--appearance-on-primary,_var(--color-history-color-21))] border-[transparent] css-hover:border-[transparent]`
                : "",
          )}
          aria-label={
            pending
              ? replied
                ? "Undoing reply…"
                : "Saving…"
              : replied
                ? "Undo reply"
                : "Mark replied"
          }
          aria-disabled={
            pending ||
            (locked && access.reasons.markReplied !== "UPGRADE_REQUIRED")
          }
          aria-busy={pending}
          onClick={run}
        >
          {pending ? (
            <LoaderCircle
              size={16}
              aria-hidden="true"
              className="animate-spin motion-reduce:animate-none"
            />
          ) : (
            <Check size={16} aria-hidden="true" />
          )}
          {locked && (
            <span
              className="absolute right-[-4px] top-[-6px] text-[10px]"
              aria-hidden="true"
            >
              <Crown size={14} className="premium-icon" aria-hidden="true" />
            </span>
          )}
        </button>
      </Tooltip>
      {(pending || result) && (
        <p role="status" aria-live="polite" className="sr-only">
          {pending
            ? "Saving…"
            : result?.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
      {result?.ok === false && (
        <p role="alert" className="mt-2 text-xs text-error-deep">
          {result.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
    </div>
  );
}
function ShortlistAction({
  id,
  shortlist,
}: {
  id: string;
  shortlist: ShortlistState;
}) {
  const access = useWorkspaceEntitlements();
  const upgrade = usePremiumUpgrade();
  const locked = !access.features.historyShortlist;
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const busy = useRef(false);
  const router = useRouter();
  const disabled =
    (locked && access.reasons.historyShortlist !== "UPGRADE_REQUIRED") ||
    pending ||
    shortlist.inShortlist ||
    shortlist.blocked ||
    !shortlist.active;
  const label = shortlist.inShortlist
    ? "In shortlist"
    : pending
      ? "Adding…"
      : "Add to shortlist";
  function run() {
    if (disabled || busy.current) return;
    if (locked) return upgrade({ feature: "shortlist" });
    busy.current = true;
    start(async () => {
      try {
        setResult(await addToShortlist(id));
        router.refresh();
      } catch {
        setResult({
          ok: false,
          message: "Could not add this person. Try again.",
        });
      } finally {
        busy.current = false;
      }
    });
  }
  const explanation = shortlist.blocked
    ? "Pending delivery"
    : !shortlist.active
      ? "Contact unavailable"
      : shortlist.inShortlist
        ? "In shortlist"
        : "Add to shortlist to email this person again.";
  return (
    <div>
      <Tooltip
        className="history-surface"
        interactive={locked}
        content={
          locked ? (
            <PremiumTooltip
              actionDescription={
                shortlist.blocked || !shortlist.active || shortlist.inShortlist
                  ? explanation
                  : "Add from History with Premium. On Free, enter and save this person’s details in Contacts to email them again."
              }
            />
          ) : (
            explanation
          )
        }
      >
        <button
          type="button"
          className={cn(
            styles.action,
            "cursor-pointer grid place-items-center w-8.5 h-8.5 p-0 border border-solid border-[var(--appearance-border,_var(--color-history-border-color-18))] rounded-[50%] relative [background:transparent] text-[var(--h-text)] css-hover:[background:var(--appearance-wash,_var(--color-history-background-22))] [&[aria-disabled='true']]:opacity-[0.5] [&[aria-disabled='true']]:cursor-default",
            locked ? "border-dashed" : "",
          )}
          aria-label={label}
          aria-disabled={disabled}
          aria-busy={pending}
          onClick={run}
        >
          {shortlist.inShortlist ? (
            <Check size={16} aria-hidden="true" />
          ) : pending ? (
            <LoaderCircle
              size={16}
              aria-hidden="true"
              className="animate-spin motion-reduce:animate-none"
            />
          ) : (
            <Plus size={16} aria-hidden="true" />
          )}
          {locked && (
            <span
              className="absolute right-[-4px] top-[-6px] text-[10px]"
              aria-hidden="true"
            >
              <Crown size={14} className="premium-icon" aria-hidden="true" />
            </span>
          )}
        </button>
      </Tooltip>
      {result?.ok === false && (
        <p role="alert" className="mt-2 text-xs text-error-deep">
          {result.message.replace(/\bPaid\b/g, "Premium")}
        </p>
      )}
    </div>
  );
}

