export type PremiumPrice = { symbol: string; amount: number };
export function PremiumUpgradeDialog({
  premiumPrice = PRICE_CONFIG.DEFAULT,
  formRef,
  returnFocusRef,
  reason = "allowance",
  allowanceScope = "daily",
  feature,
  onUpgrade,
  onClose,
  children,
}: {
  premiumPrice?: PremiumPrice;
  formRef?: RefObject<HTMLFormElement | null>;
  returnFocusRef?: RefObject<HTMLElement | null>;
  reason?: "recipient-limit" | "allowance" | "feature";
  allowanceScope?: "daily" | "monthly" | "both";
  feature?: UpgradeFeature;
  onUpgrade?: () => void;
  children?: ReactNode;
  onClose: () => void;
}) {
  const [checkoutPending, setCheckoutPending] = useState(false);
  const [checkoutError, setCheckoutError] = useState("");
  const attemptKey = useRef<string | null>(null);
  const checkoutRequest = useRef<AbortController | null>(null);
  async function startCheckout() {
    if (checkoutRequest.current) return;
    const controller = new AbortController();
    checkoutRequest.current = controller;
    setCheckoutPending(true);
    setCheckoutError("");
    attemptKey.current ??= crypto.randomUUID();
    try {
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          plan: "paid_monthly",
          idempotencyKey: attemptKey.current,
        }),
        signal: controller.signal,
      });
      const result = await response.json();
      if (!response.ok) {
        if (result.code === "CHECKOUT_ATTEMPT_FINISHED")
          attemptKey.current = null;
        throw new Error(
          result.error || "Could not open checkout. Please try again.",
        );
      }
      if (typeof result.checkoutUrl !== "string" || !result.checkoutUrl)
        throw new Error("Could not open checkout. Please try again.");
      window.location.assign(result.checkoutUrl);
    } catch (error) {
      if (controller.signal.aborted) return;
      setCheckoutError(
        error instanceof Error
          ? error.message
          : "Could not open checkout. Please try again.",
      );
      setCheckoutPending(false);
      checkoutRequest.current = null;
    }
  }

  const trigger = useRef<HTMLElement | null>(null);
  useEffect(
    () => () => {
      checkoutRequest.current?.abort();
    },
    [],
  );
  const price = `${premiumPrice.symbol}${premiumPrice.amount}`;
  return (
    <Dialog
      open
      onOpenChange={(open) => {
        if (!open) onClose();
      }}
    >
      <DialogContent
        data-upgrade-reason={reason}
        className="upgrade-modal flex w-[calc(100%-32px)] max-w-205 flex-col overflow-hidden rounded-[22px] border border-upgrade-border bg-upgrade-app p-0 text-upgrade-text shadow-upgrade-modal"
        onOpenAutoFocus={() => {
          trigger.current =
            returnFocusRef?.current ??
            formRef?.current?.querySelector<HTMLButtonElement>(
              "button[type='submit']",
            ) ??
            (document.activeElement instanceof HTMLElement
              ? document.activeElement
              : null);
        }}
        onCloseAutoFocus={(event) => {
          event.preventDefault();
          if (trigger.current?.isConnected) trigger.current.focus();
        }}
      >
        <header className="flex shrink-0 items-start justify-between gap-3 px-4 pb-2.5 pt-5.5 min-[700px]:px-6">
          <div className="min-w-0">
            <DialogTitle className="text-[22px] font-bold tracking-[-0.02em]">
              Upgrade to Premium
            </DialogTitle>
            <DialogDescription className="mt-1 text-sm leading-relaxed text-upgrade-muted">
              Send 20× more and follow up without leaving Mailloop.
            </DialogDescription>
          </div>
          <DialogClose asChild>
            <Button
              variant="outline"
              size="icon"
              aria-label="Close upgrade dialog"
              className="shrink-0 rounded-[10px] border-upgrade-border bg-upgrade-surface text-upgrade-muted hover:bg-upgrade-surface2"
            >
              <X aria-hidden="true" />
            </Button>
          </DialogClose>
        </header>
        {reason === "allowance" || reason === "recipient-limit" || feature ? (
          <div
            aria-live="polite"
            className="mx-4 mt-1.5 flex shrink-0 items-center gap-2 self-start rounded-full border border-upgrade-border bg-upgrade-okbg px-3 py-1.75 text-[13px] min-[700px]:mx-6"
          >
            {reason === "allowance" ? (
              <Clock3 aria-hidden="true" className="size-4 shrink-0" />
            ) : feature ? (
              <LockKeyhole aria-hidden="true" className="size-4 shrink-0" />
            ) : null}
            <span>
              {reason === "recipient-limit"
                ? "More recipients per campaign with Premium"
                : reason === "allowance"
                  ? allowanceScope === "both"
                    ? "Sending limits reached"
                    : `${allowanceScope === "monthly" ? "Monthly" : "Daily"} sending limit reached`
                  : feature
                    ? upgradeContexts[feature]
                    : null}
            </span>
          </div>
        ) : null}
        <div
          data-plan-cards
          data-upgrade-body
          role="region"
          aria-label="Plan comparison"
          tabIndex={0}
          className="grid min-h-0 flex-1 auto-rows-max grid-cols-1 content-start focus-visible:outline-2 focus-visible:outline-offset-[-2px] focus-visible:outline-ring gap-4 overflow-auto overscroll-contain px-4 pb-2 pt-4 min-[700px]:grid-cols-[minmax(0,1fr)_minmax(0,1.15fr)] min-[700px]:px-6"
        >
          {children && (
            <div className="min-w-0 text-sm min-[700px]:col-span-2">
              {children}
            </div>
          )}
          <PlanCard price={premiumPrice} current />
          <PlanCard premium price={premiumPrice} feature={feature} />
        </div>
        <footer className="flex shrink-0 flex-col gap-2.5 border-t border-dotted border-separator bg-upgrade-app px-4 pb-4.5 pt-3.5 min-[700px]:px-6">
          <div className="flex flex-wrap items-center gap-2.5">
            <Button
              type="button"
              className="upgrade-cta upgrade-shine relative isolate h-auto min-h-12 flex-1 overflow-hidden whitespace-normal rounded-[13px] bg-upgrade-gradient px-4 py-3.5 text-[15px] font-bold text-upgrade-btn-fg"
              onClick={() => (onUpgrade ? onUpgrade() : void startCheckout())}
              disabled={checkoutPending}
              aria-busy={checkoutPending}
            >
              <span className="relative z-10">
                {checkoutPending
                  ? "Opening checkout…"
                  : `Upgrade for ${price} / month`}
              </span>
            </Button>
            <DialogClose asChild>
              <Button
                type="button"
                variant="outline"
                className="h-auto min-h-12 rounded-[13px] border-upgrade-border bg-transparent px-4 py-3 text-upgrade-muted hover:bg-upgrade-surface2"
              >
                Maybe later
              </Button>
            </DialogClose>
          </div>
          {checkoutError && (
            <p role="alert" className="text-xs leading-snug">
              {checkoutError}
            </p>
          )}
          <p className="text-xs leading-[1.45] text-upgrade-muted">
            Billed monthly. Final quote shown at checkout. Repeat sends count
            toward your allowances. Review the final amount in checkout.{" "}
            <Link
              href="/pricing"
              className="text-upgrade-text underline underline-offset-3 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              View full pricing
            </Link>
          </p>
        </footer>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useRef,
  useState,
} from "react";
import { useRouter } from "next/navigation";
import {
  PremiumUpgradeDialog,
  type PremiumPrice,
  type UpgradeFeature,
} from "./premium-upgrade-dialog";
import { useWorkspaceEntitlements } from "./workspace-quota";

type OpenUpgrade = (options?: {
  feature?: UpgradeFeature;
  trigger?: HTMLElement | null;
}) => void;
const UpgradeContext = createContext<OpenUpgrade | null>(null);

export function PremiumUpgradeProvider({
  children,
  premiumPrice,
}: {
  children: React.ReactNode;
  premiumPrice: PremiumPrice;
}) {
  const access = useWorkspaceEntitlements();
  const [feature, setFeature] = useState<UpgradeFeature | undefined>(undefined);
  const [isOpen, setIsOpen] = useState(false);
  const returnFocusRef = useRef<HTMLElement | null>(null);
  const open = useCallback<OpenUpgrade>(
    ({ feature: name, trigger } = {}) => {
      if (
        access.effectivePlan !== "FREE" ||
        !access.controlsAvailable ||
        access.reasons.send === "ACCOUNT_SUSPENDED" ||
        access.reasons.send === "ACCOUNT_UNAVAILABLE"
      )
        return;
      returnFocusRef.current =
        trigger ??
        (document.activeElement instanceof HTMLElement
          ? document.activeElement
          : null);
      setFeature(name);
      setIsOpen(true);
    },
    [access],
  );

  return (
    <UpgradeContext value={open}>
      {children}
      {isOpen && (
        <PremiumUpgradeDialog
          reason={feature === "allowance" ? "allowance" : "feature"}
          feature={feature}
          premiumPrice={premiumPrice}
          returnFocusRef={returnFocusRef}
          onClose={() => setIsOpen(false)}
        />
      )}
    </UpgradeContext>
  );
}

export function usePremiumUpgrade(fallback?: OpenUpgrade): OpenUpgrade {
  const open = useContext(UpgradeContext);
  const router = useRouter();
  // Public and admin appearance menus also use this control, outside the workspace.
  return open ?? fallback ?? (() => router.push("/usage"));
}

"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";

import {
  useEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import Link from "next/link";
import { Tooltip } from "@/components/ui/Tooltip";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { Check, Crown } from "lucide-react";

const highlightColors = [
  "Cyan",
  "Teal",
  "Emerald",
  "Lime",
  "Amber",
  "Orange",
  "Rose",
  "Pink",
  "Violet",
  "Blue",
] as const;
type HighlightColor = Lowercase<(typeof highlightColors)[number]>;
const storageKey = "mailloop-preview-highlight";
const listeners = new Set<() => void>();
let current: HighlightColor = "cyan";
let initialized = false;
function validated(value: string | null): HighlightColor {
  return highlightColors.some((name) => name.toLowerCase() === value)
    ? (value as HighlightColor)
    : "cyan";
}
function notify() {
  listeners.forEach((listener) => listener());
}
function subscribe(listener: () => void) {
  listeners.add(listener);
  if (!initialized) {
    initialized = true;
    try {
      current = validated(localStorage.getItem(storageKey));
    } catch {
      /* Storage is optional. */
    }
    notify();
  }
  const sync = (event: StorageEvent) => {
    if (event.key === storageKey || event.key === null) {
      current = validated(event.newValue);
      notify();
    }
  };
  window.addEventListener("storage", sync);
  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", sync);
  };
}
export function usePreviewHighlight() {
  const access = useWorkspaceEntitlements();
  const preference = useSyncExternalStore(
    subscribe,
    () => current,
    () => "cyan" as HighlightColor,
  );
  return access.features.previewHighlightColors ? preference : "cyan";
}
function choose(color: HighlightColor) {
  current = color;
  try {
    localStorage.setItem(storageKey, color);
  } catch {
    /* Keep the in-memory preference. */
  }
  notify();
}

export function PreviewHighlightPicker() {
  const access = useWorkspaceEntitlements();
  return (
    <ColorPicker
      key={String(access.features.previewHighlightColors)}
      premium={access.features.previewHighlightColors}
    />
  );
}

function ColorPicker({ premium }: { premium: boolean }) {
  const upgrade = usePremiumUpgrade();
  const color = usePreviewHighlight();
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const id = useId();
  const isUpgradeTarget = (target: EventTarget | null) =>
    target instanceof Element &&
    target
      .closest("[data-preview-highlight-upgrade]")
      ?.getAttribute("data-preview-highlight-upgrade") === id;
  const close = () => {
    setOpen(false);
    trigger.current?.focus({ preventScroll: true });
  };
  useEffect(() => {
    if (!open) return;
    root.current
      ?.querySelector<HTMLButtonElement>('[aria-checked="true"]')
      ?.focus({ preventScroll: true });
    const outside = (event: PointerEvent) => {
      if (
        !root.current?.contains(event.target as Node) &&
        !(
          event.target instanceof Element &&
          event.target
            .closest("[data-preview-highlight-upgrade]")
            ?.getAttribute("data-preview-highlight-upgrade") === id
        )
      )
        setOpen(false);
    };
    document.addEventListener("pointerdown", outside);
    return () => document.removeEventListener("pointerdown", outside);
  }, [open, id]);
  return (
    <div
      ref={root}
      className="preview-highlight-picker relative flex-none"
      onBlur={(event) => {
        if (
          !event.currentTarget.contains(event.relatedTarget as Node) &&
          !isUpgradeTarget(event.relatedTarget)
        )
          setOpen(false);
      }}
      onKeyDown=[REDACTED_SECRET]
        if (event.key === "Escape" && open) {
          // Let the tooltip dismiss first, keeping the palette available.
          if (
            document.querySelector(`[data-preview-highlight-upgrade="${id}"]`)
          )
            return;
          event.preventDefault();
          event.stopPropagation();
          close();
          return;
        }
        if (isUpgradeTarget(event.target)) return;
        if (
          ![
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "Home",
            "End",
          ].includes(event.key)
        )
          return;
        event.preventDefault();
        if (!open) {
          setOpen(true);
          return;
        }
        const items = Array.from(
          root.current?.querySelectorAll<HTMLButtonElement>(
            '[role="menuitemradio"]',
          ) ?? [],
        );
        const index = items.indexOf(
          document.activeElement as HTMLButtonElement,
        );
        const offset =
          (
            {
              ArrowLeft: -1,
              ArrowRight: 1,
              ArrowUp: -5,
              ArrowDown: 5,
            } as Record<string, number>
          )[event.key] ?? 0;
        items[
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? 9
              : (index + offset + 10) % 10
        ]?.focus();
      }}
    >
      <button
        ref={trigger}
        type="button"
        className="preview-highlight-trigger grid place-items-center w-11 h-11 [border:1px_solid_var(--control-border,_var(--border))] rounded-[10px] [background:var(--card)] cursor-pointer"
        aria-label="Highlight color"
        title={`Highlight color: ${color}`}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        onClick={() => (open ? close() : setOpen(true))}
      >
        <span
          className="preview-highlight-swatch w-5 h-5 rounded-[50%] [background:var(--preview-highlight-swatch)]"
          data-preview-highlight={color}
          aria-hidden="true"
        />
      </button>
      {open && (
        <div
          id={id}
          role="menu"
          aria-label="Highlight color"
          className="preview-highlight-menu absolute right-0 [top:calc(100%_+_8px)] z-[50] grid grid-cols-[repeat(5,_36px)] gap-2 w-max p-3 rounded-[14px] [background:var(--card)] [border:1px_solid_var(--control-border,_var(--border))] shadow-[var(--shadow)]"
        >
          {highlightColors.map((name) => {
            const value = name.toLowerCase() as HighlightColor;
            const locked = !premium && value !== "cyan";
            const swatch = (
              <button
                key={value}
                type="button"
                role="menuitemradio"
                aria-label={locked ? `${name} — Premium required` : name}
                title={locked ? undefined : name}
                aria-checked={color === value}
                tabIndex={color === value ? 0 : -1}
                data-preview-highlight={value}
                onClick={() => {
                  if (locked) {
                    upgrade({
                      feature: "highlights",
                      trigger: trigger.current,
                    });
                    setOpen(false);
                    return;
                  }
                  if (premium) choose(value);
                  close();
                }}
              >
                {locked ? (
                  <Crown
                    className="premium-icon"
                    size={14}
                    aria-hidden="true"
                  />
                ) : color === value ? (
                  <Check size={18} aria-hidden="true" />
                ) : null}
              </button>
            );
            return locked ? (
              <Tooltip
                key={value}
                interactive
                placement="top"
                content={
                  <div
                    className="preview-highlight-upgrade"
                    data-preview-highlight-upgrade={id}
                  >
                    <strong>Custom preview highlight colors</strong>
                    <p>
                      Choose from 10 colors to highlight names, companies, and
                      job roles in your email previews. Free includes Cyan.
                    </p>
                    <Link
                      href="/usage"
                      className="relative isolate inline-block overflow-hidden align-middle"
                    >
                      Upgrade to Premium
                    </Link>
                  </div>
                }
              >
                {swatch}
              </Tooltip>
            ) : (
              swatch
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import type { ComponentPropsWithoutRef } from "react";

// Keep pointer updates out of React state; the card content can stay server-rendered.
export function CardSpotlight(props: ComponentPropsWithoutRef<"article">) {
  return (
    <article
      {...props}
      onPointerMove={(event) => {
        if (
          event.pointerType !== "mouse" ||
          window.matchMedia("(prefers-reduced-motion: reduce)").matches
        )
          return;
        const card = event.currentTarget;
        const bounds = card.getBoundingClientRect();
        card.style.setProperty("--spot-x", `${event.clientX - bounds.left}px`);
        card.style.setProperty("--spot-y", `${event.clientY - bounds.top}px`);
      }}
    />
  );
}

