import { cn } from "@/lib/utils";
import { useLayoutEffect, useRef, useState, type CSSProperties } from "react";

type ChecklistItem = { label: string; done: boolean; hint: string };

function ChecklistRow({
  item,
  phase,
  delay,
}: {
  item: ChecklistItem;
  phase: "idle" | "done" | "undone";
  delay: number;
}) {
  // Retain outgoing text while its container fades and collapses.
  const [lastHint, setLastHint] = useState(item.hint);
  const hint = useRef<HTMLSpanElement>(null);
  useLayoutEffect(() => {
    const element = hint.current;
    if (!element) return;
    const measure = () =>
      element.style.setProperty("--hint-height", `${element.scrollHeight}px`);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [lastHint]);
  if (item.hint && item.hint !== lastHint) setLastHint(item.hint);
  return (
    <li
      className="send-checklist-row flex items-start gap-3 min-w-0"
      data-done={item.done}
      aria-atomic="true"
      style={{ "--checklist-delay": `${delay}ms` } as CSSProperties}
    >
      <span
        className="send-checklist-icon relative grid place-items-center w-5.5 h-5.5 mt-[1px] shrink-0 text-[var(--checklist-ok)]"
        data-phase={phase}
        aria-hidden="true"
      >
        <span className="send-checklist-empty absolute w-5 h-5 [border:2px_solid_var(--checklist-ring)] rounded-[50%] opacity-[1]" />
        <svg
          className="relative"
          width="22"
          height="22"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2.2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <circle cx="12" cy="12" r="10" pathLength="1" />
          <path d="M8 12.5l3 3 5-6" pathLength="1" />
        </svg>
      </span>
      <div className="send-checklist-copy min-w-0 text-[15px] leading-normal">
        <span
          className={cn(
            "send-checklist-label block",
            item.done
              ? "text-[var(--recipients-text,var(--foreground,var(--color-globals-color-65)))] font-semibold"
              : "text-[var(--recipients-text-muted,var(--muted-foreground,var(--color-globals-color-62)))] font-normal",
          )}
        >
          <span className="sr-only">
            {item.done ? "Complete: " : "Incomplete: "}
          </span>
          {item.label}
        </span>
        <span
          ref={hint}
          className="send-checklist-hint block overflow-hidden wrap-anywhere max-h-0 opacity-[0] text-[13px] text-[var(--recipients-text-muted,_var(--muted-foreground,_var(--color-globals-color-76)))] [&[data-visible='true']]:max-h-[var(--hint-height,_30em)] [&[data-visible='true']]:opacity-[1]"
          data-visible={!!item.hint}
          aria-hidden={!item.hint}
        >
          {item.hint || lastHint}
        </span>
      </div>
    </li>
  );
}

export function SendChecklist({
  templateSelected,
  recipientCount,
  missingRoles,
  canEditRoles,
  attachResume,
}: {
  templateSelected: boolean;
  recipientCount: number;
  missingRoles: string[];
  canEditRoles: boolean;
  attachResume: boolean;
}) {
  const items: ChecklistItem[] = [
    {
      label: "Pick a template",
      done: templateSelected,
      hint: templateSelected ? "" : "Choose one under 01 / The Message",
    },
    {
      label: "Select at least one recipient",
      done: recipientCount > 0,
      hint: recipientCount
        ? `${recipientCount} selected`
        : "Tick people in your shortlist",
    },
    {
      label: "Every recipient has a role",
      done: recipientCount > 0 && !missingRoles.length,
      hint: missingRoles.length
        ? `${missingRoles.join(", ")} ${missingRoles.length === 1 ? "needs" : "need"} a role. ${canEditRoles ? "Edit each recipient’s role." : "Edit each recipient’s role in Contacts."}`
        : "",
    },
    { label: "PDF attached (optional)", done: attachResume, hint: "" },
  ];
  const signature = items.map((item) => (item.done ? "1" : "0")).join("");
  const ready = items.slice(0, 3).every((item) => item.done);
  const [motion, setMotion] = useState({
    signature,
    ready,
    phases: items.map(() => "idle" as "idle" | "done" | "undone"),
    delays: items.map(() => 0),
    pulses: 0,
  });
  if (motion.signature !== signature) {
    let changed = 0;
    const delays = items.map((_, index) =>
      motion.signature[index] !== signature[index] ? changed++ * 60 : 0,
    );
    setMotion({
      signature,
      ready,
      phases: items.map((item, index) =>
        motion.signature[index] === signature[index]
          ? "idle"
          : item.done
            ? "done"
            : "undone",
      ),
      delays,
      pulses: motion.pulses + (!motion.ready && ready ? 1 : 0),
    });
  }
  return (
    <section
      className="send-checklist [font-family:var(--font-sans)] relative flex flex-col gap-3.5 py-5 px-5.5 [border:1px_solid_var(--line2,_var(--recipients-border,_var(--border,_var(--color-globals-border-63))))] rounded-[20px] [background:var(--checklist-background)] text-[var(--recipients-text,_var(--foreground,_var(--color-globals-color-65)))]"
      aria-labelledby="send-checklist-title"
      data-ready={ready}
    >
      {motion.pulses > 0 && (
        <span
          key={motion.pulses}
          className="send-checklist-glow absolute inset-[-1px] [border:1px_solid_var(--accent)] rounded-[inherit] pointer-events-none opacity-[0]"
          aria-hidden="true"
        />
      )}
      <h3
        id="send-checklist-title"
        className="text-[16px] font-bold leading-normal"
      >
        Before you can send
      </h3>
      <div aria-live="polite">
        <ul className="flex flex-col gap-3 p-0 m-0 list-none">
          {items.map((item, index) => (
            <ChecklistRow
              key={item.label}
              item={item}
              phase={motion.phases[index]}
              delay={motion.delays[index]}
            />
          ))}
        </ul>
      </div>
    </section>
  );
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  useCallback,
  type Dispatch,
  type SetStateAction,
  type ReactNode,
} from "react";
import { usePathname } from "next/navigation";
import { getSendingActive } from "@/lib/sending-status-actions";

const SendingContext = createContext<{
  locked: boolean;
  setSubmitting: Dispatch<SetStateAction<boolean>>;
  markQueued: () => void;
} | null>(null);

export function SendingStatusProvider({
  initialSending,
  children,
}: {
  initialSending: boolean;
  children: ReactNode;
}) {
  const [sending, setSending] = useState(initialSending);
  const [submitting, setSubmitting] = useState(false);
  const version = useRef(0);
  const pathname = usePathname();
  const markQueued = useCallback(() => {
    ++version.current;
    setSending(true);
  }, []);

  useEffect(() => {
    let cancelled = false;
    let pending = false;
    const refresh = async () => {
      if (pending || document.visibilityState !== "visible") return;
      pending = true;
      const requestedVersion = version.current;
      try {
        const active = await getSendingActive();
        if (!cancelled && requestedVersion === version.current)
          setSending(active);
      } catch {
        // A failed status check must not unlock an active batch.
      } finally {
        pending = false;
      }
    };
    void refresh();
    const interval = window.setInterval(() => void refresh(), 5000);
    document.addEventListener("visibilitychange", refresh);
    window.addEventListener("focus", refresh);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", refresh);
      window.removeEventListener("focus", refresh);
    };
  }, [pathname]);

  return (
    <SendingContext.Provider
      value={{ locked: submitting || sending, setSubmitting, markQueued }}
    >
      {children}
    </SendingContext.Provider>
  );
}

export function useSendingStatus() {
  return useContext(SendingContext);
}

