export async function saveContact(form: FormData) {
  const user = await requireUser();
  return mutation(user.id, async (tx) => {
    const data = contactSchema.parse(Object.fromEntries(form));
    const id = form.get("id");
    const previouslySent = await hasSuccessfulDelivery(tx, user.id, data.email);
    if (previouslySent)
      await requireEntitlement(user.id, "manualRepeatSend", tx);
    const access = await readEntitlements(user.id, tx);
    let savedId: string;
    if (id) {
      savedId = z.uuid().parse(id);
      const updated = await tx.contact.updateMany({
        where: { id: savedId, userId: user.id, archivedAt: null },
        data,
      });
      if (!updated.count) throw new AppError("Contact not found.");
    } else {
      const saved = await tx.contact.upsert({
        where: { userId_email: { userId: user.id, email: data.email } },
        update: { ...data, archivedAt: null },
        create: { ...data, userId: user.id },
        select: { id: true },
      });
      savedId = saved.id;
    }
    if (access.features.manualRepeatSend && previouslySent)
      await restoreShortlistContact(tx, user.id, savedId);
    revalidatePath("/", "layout");
    return { ok: true, message: "Contact saved." };
  });
}
