import "server-only";
import { randomUUID } from "node:crypto";
import type { Prisma } from "@/generated/prisma/client";
export async function appendAudit(
  tx: Prisma.TransactionClient,
  event: {
    actorId: string;
    targetId: string | null;
    action: string;
    requestId: string;
    requestHash: string;
    reason: string;
    before: Prisma.InputJsonObject;
    after: Prisma.InputJsonObject;
  },
) {
  await tx.$executeRaw`INSERT INTO "AdminAuditLog" (id,"actorUserId","targetUserId","actorIdSnapshot","targetIdSnapshot",action,"requestId","requestHash",reason,before,after) VALUES (${randomUUID()},${event.actorId},${event.targetId},${event.actorId},${event.targetId},${event.action},${event.requestId},${event.requestHash},${event.reason},${JSON.stringify(event.before)}::jsonb,${JSON.stringify(event.after)}::jsonb)`;
}

export function freshAuthentication(at: unknown, now = Date.now()) {
  return (
    typeof at === "number" &&
    Number.isSafeInteger(at) &&
    at * 1000 <= now &&
    now - at * 1000 < 15 * 60000
  );
}

import "server-only";
import { auth } from "@/auth";
import type { Prisma } from "@/generated/prisma/client";
import { adminDb } from "./db";
import { AdminError, uuid } from "./contracts";
const adminActorSelect = {
  id: true,
  isAdmin: true,
  isSuspended: true,
  deletionRequestedAt: true,
} as const;
import { freshAuthentication } from "./auth-freshness";
export { freshAuthentication } from "./auth-freshness";
export async function checkActor(tx: Prisma.TransactionClient, userId: string) {
  const user = await tx.user.findUnique({
    where: { id: userId },
    select: adminActorSelect,
  });
  if (!user?.isAdmin || user.isSuspended || user.deletionRequestedAt)
    throw new AdminError("DENIED");
  return user;
}
export async function requireAdmin(mutation = false) {
  try {
    const session = await auth();
    if (!uuid.safeParse(session?.user?.id).success)
      throw new AdminError("DENIED");
    const database = adminDb();
    // Fail closed for a misconfigured owner URL or inherited PUBLIC grants.
    const boundary = await database.$queryRaw<{ restricted: boolean }[]>`
      SELECT NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname=current_user AND (rolsuper OR rolcreaterole OR rolcreatedb OR rolbypassrls))
      AND NOT has_column_privilege(current_user, '"User"', 'encryptedRefreshToken', 'SELECT')
      AND NOT has_column_privilege(current_user, '"User"', 'googleId', 'SELECT')
      AND NOT has_column_privilege(current_user, '"User"', 'isAdmin', 'UPDATE')
      AND NOT has_column_privilege(current_user, '"Send"', 'body', 'SELECT')
      AND NOT has_column_privilege(current_user, '"Send"', 'subject', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Contact"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Template"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"Attachment"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"BillingWebhookEvent"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"AccountDeletionJob"', 'SELECT')
      AND NOT has_table_privilege(current_user, '"AdminAuditLog"', 'SELECT') AS restricted`;
    if (!boundary[0]?.restricted) throw new AdminError("UNAVAILABLE");
    const actor = await checkActor(database, session!.user.id);
    if (
      mutation &&
      (!freshAuthentication(session!.adminAuthAt) ||
        session!.adminAuthUserId !== actor.id)
    )
      throw new AdminError("REAUTH_REQUIRED");
    return { ...actor, authenticatedAt: session!.adminAuthAt };
  } catch (error) {
    if (error instanceof AdminError) throw error;
    throw new AdminError("UNAVAILABLE");
  }
}

import { z } from "zod";
export const reasonCodes = [
  "SUPPORT",
  "ABUSE",
  "SECURITY",
  "OPERATIONS",
  "RECOVERY",
] as const;
export const actions = [
  "PLAN_OVERRIDE",
  "SUSPENSION",
  "SENDING_CONTROL",
  "ADMIN_PROMOTED",
  "ADMIN_REVOKED",
  "LEGACY",
] as const;
export const uuid = z.uuid();
const reasonCode = z.enum(reasonCodes);
const instant = z.iso.datetime({ precision: 3 });
export const overrideInput = z
  .strictObject({
    targetId: uuid,
    plan: z.enum(["FREE", "PAID"]).nullable(),
    startsAt: instant.nullable(),
    expiresAt: instant.nullable(),
    reasonCode,
    requestId: uuid,
    confirmation: z.boolean(),
  })
  .superRefine((v, ctx) => {
    if (v.plan === null && (v.startsAt !== null || v.expiresAt !== null))
      ctx.addIssue({ code: "custom", message: "INVALID_INPUT" });
    if (v.startsAt && v.expiresAt && v.startsAt >= v.expiresAt)
      ctx.addIssue({ code: "custom", message: "INVALID_INPUT" });
  });
export const suspensionInput = z.strictObject({
  targetId: uuid,
  suspended: z.boolean(),
  reasonCode,
  requestId: uuid,
});
export const controlInput = z.strictObject({
  sendingEnabled: z.boolean(),
  expectedUpdatedAt: instant,
  reasonCode,
  requestId: uuid,
});
export const userFilters = z.strictObject({
  search: z.string().trim().max(160).default(""),
  plan: z.enum(["FREE", "PAID"]).optional(),
  status: z
    .enum([
      "NONE",
      "PENDING",
      "ACTIVE",
      "PAST_DUE",
      "ON_HOLD",
      "CANCELLED",
      "EXPIRED",
      "FAILED",
      "PAUSED",
    ])
    .optional(),
  suspended: z.enum(["true", "false"]).optional(),
  cursor: z.string().max(300).optional(),
});
export function encodeCursor(row: { id: string; createdAt: Date }) {
  return Buffer.from(
    JSON.stringify([row.createdAt.toISOString(), row.id]),
  ).toString("base64url");
}
export function decodeCursor(value?: string) {
  if (!value) return null;
  try {
    const [createdAt, id] = z
      .tuple([instant, uuid])
      .parse(JSON.parse(Buffer.from(value, "base64url").toString("utf8")));
    return { createdAt: new Date(createdAt), id };
  } catch {
    throw new AdminError("INVALID_INPUT");
  }
}
type AdminCode =
  | "DENIED"
  | "REAUTH_REQUIRED"
  | "INVALID_INPUT"
  | "CONFLICT"
  | "RATE_LIMITED"
  | "UNAVAILABLE";
export class AdminError extends Error {
  constructor(readonly code: AdminCode) {
    super(code);
  }
}
export type MutationResult =
  | { ok: true; requestId: string }
  | { ok: false; code: AdminCode; retryAfter?: number };

import "server-only";
import { PrismaPg } from "@prisma/adapter-pg";
import { PrismaClient } from "@/generated/prisma/client";
let client: PrismaClient | undefined;
// Lazy creation permits the public app to run without operator credentials.
// Never use DATABASE_URL here, including in development or tests.
export function adminDb() {
  const url = process.env.ADMIN_DATABASE_URL;
  if (!url) throw new Error("ADMIN_UNAVAILABLE");
  try {
    const admin = new URL(url);
    if (
      process.env.DATABASE_URL &&
      admin.username === new URL(process.env.DATABASE_URL).username
    )
      throw new Error();
  } catch {
    throw new Error("ADMIN_UNAVAILABLE");
  }
  return (client ??= new PrismaClient({
    adapter: new PrismaPg({ connectionString: url, max: 3 }),
    log: [],
  }));
}

import { consumeBudgets, RateLimitError } from "@/lib/rate-limit";
import "server-only";
import { createHash } from "node:crypto";
import { Prisma } from "@/generated/prisma/client";
import { z } from "zod";
import { adminDb } from "./db";
import { requireAdmin, checkActor, freshAuthentication } from "./auth";
import {
  AdminError,
  overrideInput,
  suspensionInput,
  controlInput,
  type MutationResult,
} from "./contracts";
import { appendAudit } from "./audit";
import { reservationSelect, evidenceSelect } from "./projections";
import { countAdminUsage } from "./usage";
import { adminUserSelect } from "./projections";
import { ensureUsagePeriods, lockUsageOwner } from "@/lib/usage-ledger";
import { resolveUsagePeriods, UsagePeriodError } from "@/lib/usage-periods";
// Internal entrypoint still authenticates; exported server actions never accept an actor.
async function mutate<T extends { requestId: string; reasonCode: string }>(
  schema: z.ZodType<T>,
  input: unknown,
  action: string,
  target: (v: T) => string | null,
  work: (
    tx: Prisma.TransactionClient,
    v: T,
    actorId: string,
  ) => Promise<{
    before: Prisma.InputJsonObject;
    after: Prisma.InputJsonObject;
  }>,
): Promise<MutationResult> {
  try {
    const actor = await requireAdmin(true);
    await consumeBudgets(
      actor.id,
      action === "SENDING_CONTROL"
        ? ["admin", "systemActor", "systemGlobal"]
        : ["admin"],
      adminDb(),
    );
    const parsed = schema.safeParse(input);
    if (!parsed.success) throw new AdminError("INVALID_INPUT");
    const v = parsed.data,
      targetId = target(v),
      hash = createHash("sha256")
        .update(JSON.stringify([actor.id, action, targetId, v]))
        .digest("hex");
    return await adminDb().$transaction(
      async (tx) => {
        // Request serialization precedes stable actor/target owner ordering.
        await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${v.requestId},73461))::text`;
        const ids = [
          ...new Set([actor.id, ...(targetId ? [targetId] : [])]),
        ].sort();
        await tx.$queryRaw`SELECT id FROM "User" WHERE id IN (${Prisma.join(ids)}) ORDER BY id FOR UPDATE`;
        await checkActor(tx, actor.id);
        if (!freshAuthentication(actor.authenticatedAt))
          throw new AdminError("REAUTH_REQUIRED");
        const replay = await tx.$queryRaw<
          {
            requestHash: string;
            actorIdSnapshot: string;
            action: string;
            targetIdSnapshot: string | null;
          }[]
        >`SELECT "requestHash","actorIdSnapshot",action,"targetIdSnapshot" FROM "AdminAuditSafe" WHERE "requestId"=${v.requestId}`;
        if (replay.length) {
          const r = replay[0];
          if (
            r.requestHash !== hash ||
            r.actorIdSnapshot !== actor.id ||
            r.action !== action ||
            r.targetIdSnapshot !== targetId
          )
            throw new AdminError("CONFLICT");
          return { ok: true as const, requestId: v.requestId };
        }
        if (targetId) {
          const u = await tx.user.findUnique({
            where: { id: targetId },
            select: { id: true, deletionRequestedAt: true },
          });
          if (!u || u.deletionRequestedAt) throw new AdminError("DENIED");
        }
        const diff = await work(tx, v, actor.id);
        await appendAudit(tx, {
          actorId: actor.id,
          targetId,
          action,
          requestId: v.requestId,
          requestHash: hash,
          reason: v.reasonCode,
          ...diff,
        });
        return { ok: true as const, requestId: v.requestId };
      },
      { timeout: 15000, maxWait: 10000 },
    );
  } catch (error) {
    return {
      ok: false,
      code:
        error instanceof RateLimitError
          ? "RATE_LIMITED"
          : error instanceof AdminError
            ? error.code
            : "UNAVAILABLE",
      ...(error instanceof RateLimitError
        ? { retryAfter: error.retryAfter }
        : {}),
    };
  }
}
export function changeOverride(input: unknown) {
  return mutate(
    overrideInput,
    input,
    "PLAN_OVERRIDE",
    (v) => v.targetId,
    async (tx, v) => {
      const u = await tx.user.findUniqueOrThrow({
        where: { id: v.targetId },
        select: {
          plan: true,
          subscriptionStatus: true,
          planOverride: true,
          planOverrideStartsAt: true,
          planOverrideExpiresAt: true,
        },
      });
      if (v.plan === "FREE" && !v.confirmation)
        throw new AdminError("INVALID_INPUT");
      const now = new Date(),
        starts = v.plan ? new Date(v.startsAt ?? now.toISOString()) : null,
        expires = v.plan
          ? new Date(
              v.expiresAt ?? new Date(+starts! + 30 * 86400000).toISOString(),
            )
          : null;
      if (expires && (expires <= now || expires <= starts!))
        throw new AdminError("INVALID_INPUT");
      await tx.user.updateMany({
        where: { id: v.targetId },
        data: {
          planOverride: v.plan,
          planOverrideStartsAt: starts,
          planOverrideExpiresAt: expires,
          planOverrideReason: v.plan ? v.reasonCode : null,
        },
      });
      // Re-evaluate buckets without campaign content or provider mutations.
      const updated = await tx.user.findUniqueOrThrow({
        where: { id: v.targetId },
        select: adminUserSelect,
      });
      try {
        const specs = resolveUsagePeriods(updated, now);
        await ensureUsagePeriods(await lockUsageOwner(tx, v.targetId), specs);
      } catch (error) {
        // An unresolved provider boundary must not invent calendar credit.
        if (!(error instanceof UsagePeriodError)) throw error;
      }
      return {
        before: {
          planOverride: u.planOverride,
          startsAt: u.planOverrideStartsAt?.toISOString() ?? null,
          expiresAt: u.planOverrideExpiresAt?.toISOString() ?? null,
        },
        after: {
          planOverride: v.plan,
          startsAt: starts?.toISOString() ?? null,
          expiresAt: expires?.toISOString() ?? null,
        },
      };
    },
