      where: { userId, dodoSubscriptionId: user.dodoSubscriptionId ?? "" },
    });
    if (!subscription || subscription.dodoCustomerId !== user.dodoCustomerId)
      throw new BillingError(
        "NO_SUBSCRIPTION",
        "No current subscription is available.",
        409,
      );
    if (
      subscription.cancelAtPeriodEnd ||
      ["CANCELLED", "EXPIRED", "FAILED"].includes(subscription.status)
    )
      return { subscription, requested: false };
    // Claim before any provider write. Concurrent calls reuse this durable marker.
    if (subscription.cancelRequestedAt)
      return { subscription, requested: false };
    await tx.billingSubscription.updateMany({
      where: { userId, id: subscription.id },
      data: { cancelRequestedAt: new Date() },
    });
    await tx.user.update({
      where: { id: userId },
      data: { billingStateVersion: { increment: 1 } },
    });
    return { subscription, requested: true };
  });
  if (reservation.requested) {
    await dodoClient()
      .subscriptions.update(
        reservation.subscription.dodoSubscriptionId,
        {
          cancel_at_next_billing_date: true,
        },
        { maxRetries: 0 },
      )
      .catch(() => {
        // A timeout is uncertain. Recovery reads provider state before retrying.
      });
  }
  return {
    cancellationPending:
      !reservation.subscription.cancelAtPeriodEnd &&
      !["CANCELLED", "EXPIRED", "FAILED"].includes(
        reservation.subscription.status,
      ),
  };
}

export async function recoverBillingCancellation(
  userId: string,
  subscriptionId: string,
) {
  const stored = await db.billingSubscription.findFirst({
    where: {
      userId,
      dodoSubscriptionId: subscriptionId,
      cancelRequestedAt: { not: null },
    },
  });
  if (!stored) return;
  await withUsageTransaction(db, userId, ({ tx }) => ensureBillingBinding(tx));
  const provider = providerSubscriptionSchema.parse(
    await dodoClient().subscriptions.retrieve(subscriptionId),
  );
  if (
    provider.subscription_id !== subscriptionId ||
    provider.customer.customer_id !== stored.dodoCustomerId ||
    (provider.metadata.mailloopUserId &&
      provider.metadata.mailloopUserId !== userId)
  )
    throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
  if (
    !provider.cancel_at_next_billing_date &&
    !["cancelled", "expired", "failed"].includes(provider.status)
  ) {
    // Allow the first request time to settle before retrying the same idempotent flag.
    if (Date.now() - stored.cancelRequestedAt!.getTime() < 30_000) return;
    await dodoClient().subscriptions.update(
      subscriptionId,
      { cancel_at_next_billing_date: true },
      { maxRetries: 0 },
    );
  }
  await reconcileBillingSubscription(userId, subscriptionId);
}

import "server-only";

import { randomUUID } from "node:crypto";
import { z } from "zod";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { billingCheckoutUrl, dodoClient } from "@/lib/billing/dodo";
import {
  ensureBillingBinding,
  openCheckoutStates,
  verifyBillingProduct,
} from "@/lib/billing/store";
import { reconcileBillingSubscription } from "@/lib/billing/lifecycle";
import { withUsageTransaction } from "@/lib/usage-ledger";

const checkoutInput = z
  .object({
    plan: z.literal("paid_monthly"),
    idempotencyKey: z.uuid(),
  })
  .strict();
// Hosted sessions last 24h. The upper bound includes the request timeout and a
// safety margin. No new checkout is allowed until this bound AND reconciliation.
const CHECKOUT_RECOVERY_MARGIN_MS = 5 * 60_000;
export const CHECKOUT_RECOVERY_WINDOW_MS =
  24 * 60 * 60_000 + CHECKOUT_RECOVERY_MARGIN_MS;
// expiresAt is the recovery bound, not the hosted link's expiry. Stop returning
// the link one minute before its 24h lifetime ends, keeping recovery unchanged.
const CHECKOUT_URL_EXPIRY_BUFFER_MS = CHECKOUT_RECOVERY_MARGIN_MS + 60_000;

function hasOutstandingSubscription(subscription: {
  status: string;
  cancel_at_next_billing_date: boolean;
  next_billing_date: string;
}) {
  return (
    !["cancelled", "expired", "failed"].includes(subscription.status) ||
    (subscription.status === "cancelled" &&
      subscription.cancel_at_next_billing_date &&
      new Date(subscription.next_billing_date) > new Date())
  );
}

export async function providerSubscriptions(
  customerId: string,
  signal?: AbortSignal,
) {
  const subscriptions = [];
  for await (const item of dodoClient().subscriptions.list(
    {
      customer_id: customerId,
    },
    { signal },
  ))
    subscriptions.push(item);
  return subscriptions;
}

export async function recoverCheckoutAttempt(
  userId: string,
  attemptId: string,
) {
  const attempt = await db.checkoutAttempt.findFirst({
    where: { id: attemptId, userId, status: { in: openCheckoutStates } },
  });
  if (!attempt || Date.now() - attempt.updatedAt.getTime() < 30_000) return;
  const user = await db.user.findUniqueOrThrow({ where: { id: userId } });
  let customerId = user.dodoCustomerId;
  if (!customerId) {
    // A lost customer-create response is recovered by server-generated metadata,
    // never by trusting email identity alone or repeating the creation request.
    const matching = [];
    for await (const customer of dodoClient().customers.list({
      email: user.email,
    })) {
      if (
        customer.metadata?.mailloopUserId === userId &&
        customer.metadata?.checkoutAttemptId === attempt.id
      )
        matching.push(customer);
    }
    if (matching.length > 1)
      throw new BillingError("CUSTOMER_CREATION_CONFLICT");
    customerId = matching[0]?.customer_id ?? null;
    if (customerId)
      await withUsageTransaction(db, userId, async ({ tx }) => {
        const current = await tx.user.findUniqueOrThrow({
          where: { id: userId },
        });
        if (current.dodoCustomerId && current.dodoCustomerId !== customerId)
          throw new BillingError("CUSTOMER_CREATION_CONFLICT");
        await tx.user.update({
          where: { id: userId },
          data: {
            dodoCustomerId: customerId,
            billingStateVersion: { increment: 1 },
          },
        });
      });
  }
  const subscriptions = customerId
    ? await providerSubscriptions(customerId)
    : [];
  const outstanding = subscriptions.filter(hasOutstandingSubscription);
  for (const sub of subscriptions.filter(
    (s) =>
      s.product_id === billingConfig().productId &&
      (s.metadata?.checkoutAttemptId === attempt.id ||
        new Date(s.created_at) >= attempt.createdAt),
  ))
    await reconcileBillingSubscription(userId, sub.subscription_id);
  if (outstanding.length) return; // including an activated but unsettled mandate
  if (attempt.dodoSessionId) {
    const session = await dodoClient().checkoutSessions.retrieve(
      attempt.dodoSessionId,
    );
    // A succeeded/processing checkout with no visible subscription is uncertain,
    // even past the local expiry. Never replace it with a fresh subscription.
    if (
      session.payment_status &&
      !["failed", "cancelled"].includes(session.payment_status)
    )
      return;
  }
  if (new Date() < attempt.expiresAt) return;
  await withUsageTransaction(db, userId, async ({ tx }) => {
    await tx.checkoutAttempt.updateMany({
      where: {
        id: attempt.id,
        userId,
        updatedAt: attempt.updatedAt,
        status: { in: openCheckoutStates },
      },
      data: { status: "EXPIRED", checkoutUrl: null, failureCode: null },
    });
  });
}

export async function createBillingCheckout(userId: string, input: unknown) {
  const parsed = checkoutInput.safeParse(input);
  if (!parsed.success)
    throw new BillingError(
      "INVALID_CHECKOUT",
      "Choose a valid plan and checkout attempt.",
      400,
    );
  const config = billingConfig();
  const client = dodoClient();
  const control = await db.systemControl.findUnique({
    where: { key: "global" },
  });
  if (!control?.billingCheckoutEnabled)
    throw new BillingError(
      "CHECKOUT_DISABLED",
      "Checkout is currently disabled.",
    );
  await verifyBillingProduct();
  const pending = await db.checkoutAttempt.findFirst({
    where: { userId, status: { in: openCheckoutStates } },
  });
  if (pending && pending.expiresAt <= new Date())
    await recoverCheckoutAttempt(userId, pending.id);

  const reservation = await withUsageTransaction(db, userId, async ({ tx }) => {
    await ensureBillingBinding(tx);
    const control = await tx.systemControl.findUnique({
      where: { key: "global" },
    });
    if (!control?.billingCheckoutEnabled)
      throw new BillingError(
        "CHECKOUT_DISABLED",
        "Checkout is currently disabled.",
      );
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    if (user.deletionRequestedAt || user.isSuspended)
      throw new BillingError(
        "ACCOUNT_UNAVAILABLE",
        "This account cannot start checkout.",
        403,
      );
    if (
      await tx.billingSubscription.count({
        where: {
          userId,
          OR: [
            { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
            {
              status: "CANCELLED",
              cancelAtPeriodEnd: true,
              periodEnd: { gt: new Date() },
            },
          ],
        },
      })
    )
      throw new BillingError(
        "ALREADY_SUBSCRIBED",
        "Manage your existing subscription in billing settings.",
        409,
      );
    const open = await tx.checkoutAttempt.findFirst({
      where: { userId, status: { in: openCheckoutStates } },
    });
    if (open) {
      if (
        open.status === "READY" &&
        open.checkoutUrl &&
        open.expiresAt.getTime() - CHECKOUT_URL_EXPIRY_BUFFER_MS > Date.now()
      )
        return { user, attempt: open, created: false };
      throw new BillingError(
        "CHECKOUT_PENDING",
        "Your previous checkout is being verified. Try again shortly.",
        409,
      );
    }
    const prior = await tx.checkoutAttempt.findFirst({
      where: { userId, idempotencyKey: parsed.data.idempotencyKey },
    });
    if (prior)
      throw new BillingError(
        "CHECKOUT_ATTEMPT_FINISHED",
        "This checkout attempt has finished. Refresh before trying again.",
        409,
      );
    if (
      (await tx.checkoutAttempt.count({
        where: { userId, createdAt: { gte: new Date(Date.now() - 3600_000) } },
      })) >= 5
    )
      throw new BillingError(
        "CHECKOUT_RATE_LIMIT",
        "Too many checkout attempts. Try again later.",
        429,
      );
    const attempt = await tx.checkoutAttempt.create({
      data: {
        id: randomUUID(),
        userId,
        ownerIdSnapshot: userId,
        productId: config.productId,
        idempotencyKey: parsed.data.idempotencyKey,
        expiresAt: new Date(Date.now() + CHECKOUT_RECOVERY_WINDOW_MS),
        status: user.dodoCustomerId ? "CREATING" : "CUSTOMER_CREATING",
      },
    });
    return { user, attempt, created: true };
  });
  if (!reservation.created)
    return {
      checkoutUrl: billingCheckoutUrl(
        reservation.attempt.checkoutUrl!,
        config.environment,
      ),
    };
  const { attempt } = reservation;
  let customerId = reservation.user.dodoCustomerId;
  let uncertainCreation = false;
  try {
    if (!customerId) {
      uncertainCreation = true;
      const customer = await client.customers.create(
        {
          email: reservation.user.email,
          name: reservation.user.name || reservation.user.email,
          metadata: { mailloopUserId: userId, checkoutAttemptId: attempt.id },
        },
        { maxRetries: 0 },
      );
      customerId = customer.customer_id;
      await withUsageTransaction(db, userId, async ({ tx }) => {
        const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
        if (user.dodoCustomerId && user.dodoCustomerId !== customerId)
          throw new BillingError("CUSTOMER_CREATION_CONFLICT");
        await tx.user.update({
          where: { id: userId },
          data: {
            dodoCustomerId: customerId,
            billingStateVersion: { increment: 1 },
          },
        });
        await tx.checkoutAttempt.updateMany({
          where: { id: attempt.id, userId },
          data: { status: "CREATING" },
        });
      });
      uncertainCreation = false;
    }
    const currentSubscriptions = await providerSubscriptions(customerId);
    if (currentSubscriptions.some(hasOutstandingSubscription))
      throw new BillingError(
        "ALREADY_SUBSCRIBED",
        "Manage your existing subscription in billing settings.",
        409,
      );
    // The final owner check commits before the outbound request. Deletion racing
    // after this point retains the attempt until it expires and cancels any late
    // subscription; it can never remove the account first.
    await withUsageTransaction(db, userId, async ({ tx }) => {
      const current = await tx.user.findUniqueOrThrow({
        where: { id: userId },
      });
      const control = await tx.systemControl.findUnique({
        where: { key: "global" },
      });
      if (!control?.billingCheckoutEnabled)
        throw new BillingError(
          "CHECKOUT_DISABLED",
          "Checkout is currently disabled.",
        );
      if (current.deletionRequestedAt || current.isSuspended)
        throw new BillingError(
          "ACCOUNT_UNAVAILABLE",
          "Account unavailable.",
          403,
        );
      await tx.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId, status: "CREATING" },
        data: { failureCode: "CHECKOUT_REQUEST_STARTED" },
      });
    });
    uncertainCreation = true;
    const session = await client.checkoutSessions.create(
      {
        // Let the hosted billing country select currency. A forced USD value
        // converts the India INR rule back to dollars instead of charging INR.
        product_cart: [{ product_id: config.productId, quantity: 1 }],
        customer: { customer_id: customerId },
        metadata: { mailloopUserId: userId, checkoutAttemptId: attempt.id },
        return_url: `${config.origin}/usage/return`,
        cancel_url: `${config.origin}/usage`,
        feature_flags: {
          allow_customer_editing_email: false,
          allow_customer_editing_country: true,
          allow_currency_selection: false,
          allow_editing_addons: false,
          allow_discount_code: false,
        },
      },
      { maxRetries: 0 },
    );
    if (!session.checkout_url) throw new BillingError("CHECKOUT_URL_MISSING");
    const checkoutUrl = billingCheckoutUrl(
      session.checkout_url,
      config.environment,
    );
    const available = await withUsageTransaction(db, userId, async ({ tx }) => {
      const current = await tx.user.findUniqueOrThrow({
        where: { id: userId },
      });
      await tx.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId, status: { in: openCheckoutStates } },
        data: {
          status: "READY",
          dodoSessionId: session.session_id,
          checkoutUrl,
          failureCode: null,
          expiresAt: new Date(Date.now() + CHECKOUT_RECOVERY_WINDOW_MS),
        },
      });
      return !current.deletionRequestedAt && !current.isSuspended;
    });
    if (!available)
      throw new BillingError(
        "ACCOUNT_UNAVAILABLE",
        "Account unavailable.",
        403,
      );
    return { checkoutUrl };
  } catch (error) {
    await db.checkoutAttempt.updateMany({
      where: {
        id: attempt.id,
        userId,
        status: { in: ["CUSTOMER_CREATING", "CREATING"] },
      },
      data: {
        status: uncertainCreation ? "UNKNOWN" : "FAILED",
        failureCode: uncertainCreation
          ? "PROVIDER_CREATION_UNCERTAIN"
          : "CHECKOUT_PREPARATION_FAILED",
      },
    });
    if (error instanceof BillingError) throw error;
    throw new BillingError(
      "CHECKOUT_UNCERTAIN",
      "Checkout could not be confirmed. Your previous attempt will be verified before another is created.",
    );
  }
}

export async function createBillingPortal(userId: string) {
  const config = billingConfig();
  const customerId = await withUsageTransaction(db, userId, async ({ tx }) => {
    await ensureBillingBinding(tx);
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    if (user.deletionRequestedAt || !user.dodoCustomerId)
      throw new BillingError(
        "BILLING_ACCOUNT_UNAVAILABLE",
        "No billing account is available.",
        409,
      );
    return user.dodoCustomerId;
  });
  const portal = await dodoClient().customers.customerPortal.create(
    customerId,
    { return_url: `${config.origin}/settings#plan`, send_email: false },
  );
  const url = new URL(portal.link);
  if (
    url.protocol !== "https:" ||
    url.hostname !== "test.customer.dodopayments.com" ||
    url.username ||
    url.password ||
    url.port
  )
    throw new BillingError("INVALID_PORTAL_URL");
  return { portalUrl: url.toString() };
}

import "server-only";

import { z } from "zod";
import { AppError } from "@/lib/errors";

export class BillingError extends AppError {
  retryAfter?: number;
  constructor(
    readonly code: string,
    message = "Billing is temporarily unavailable.",
    readonly status = 503,
  ) {
    super(message);
  }
}

// Require an explicit mode. Never infer live mode from a key or SDK default.
export function billingConfig(
  env: Record<string, string | undefined> = process.env,
) {
  const parsed = z
    .object({
      DODO_PAYMENTS_ENVIRONMENT: z.enum(["test_mode", "live_mode"]),
      DODO_PAYMENTS_API_KEY: z.string().trim().min(1),
      DODO_PAID_MONTHLY_PRODUCT_ID: z.string().trim().min(1),
      DODO_PAYMENTS_WEBHOOK_KEY: z.string().trim().min(1),
      DODO_PAYMENTS_BUSINESS_ID: z.string().trim().min(1),
    })
    .safeParse(env);
  if (
    !parsed.success ||
    env.DODO_PAYMENTS_BASE_URL ||
    env.DODO_PAYMENTS_CUSTOM_HEADERS
  )
    throw new BillingError("BILLING_CONFIGURATION");
  let origin: URL;
  try {
    origin = new URL(env.APP_ORIGIN || env.AUTH_URL || "");
  } catch {
    throw new BillingError("BILLING_CONFIGURATION");
  }
  if (
    origin.username ||
    origin.password ||
    origin.search ||
    origin.hash ||
    origin.pathname !== "/" ||
    !(
      origin.protocol === "https:" ||
      (origin.protocol === "http:" &&
        ["localhost", "127.0.0.1", "[::1]"].includes(origin.hostname))
    )
  )
    throw new BillingError("BILLING_CONFIGURATION");
  if (
    parsed.data.DODO_PAYMENTS_ENVIRONMENT === "live_mode" &&
    origin.protocol !== "https:"
  )
    throw new BillingError("BILLING_CONFIGURATION");
  return {
    environment: parsed.data.DODO_PAYMENTS_ENVIRONMENT,
    apiKey: parsed.data.DODO_PAYMENTS_API_KEY,
    productId: parsed.data.DODO_PAID_MONTHLY_PRODUCT_ID,
    webhookKey: parsed.data.DODO_PAYMENTS_WEBHOOK_KEY,
    businessId: parsed.data.DODO_PAYMENTS_BUSINESS_ID,
    origin: origin.origin,
  };
}

export { BILLING_PRICES } from "@/lib/pricing";

import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";
import { ensureBillingBinding, openCheckoutStates } from "@/lib/billing/store";
import { providerSubscriptions } from "@/lib/billing/checkout";
import { providerSubscriptionSchema } from "@/lib/billing/events";
import { deletionCheckoutSchema, runDeletionJob } from "@/lib/deletion-jobs";

function terminal(provider: {
  status: string;
  cancel_at_next_billing_date: boolean;
}) {
  return (
    ["expired", "failed"].includes(provider.status) ||
    (provider.status === "cancelled" && !provider.cancel_at_next_billing_date)
  );
}

/** Independent of User. Read before every uncertain write; confirm terminal
 * state afterwards. The SDK has bounded requests, retries disabled, test only. */
export async function cancelDeletionBilling(userId: string): Promise<boolean> {
  billingConfig();
  await db.$transaction((tx) => ensureBillingBinding(tx));
  const job = await db.accountDeletionJob.findUniqueOrThrow({
    where: { userId },
  });
  const attempts = deletionCheckoutSchema.parse(job.checkoutRecovery);
  const signal = AbortSignal.timeout(60_000);
  const matchedAttempts = new Set<string>();
  const customers = new Set(job.customerIds);
  // Lost customer-create responses are recovered through server metadata. Email
  // is deliberately unavailable after purge. Include duplicate matching customers.
  if (attempts.length) {
    const earliest = Math.min(...attempts.map((a) => Date.parse(a.createdAt)));
    for await (const customer of dodoClient().customers.list(
      {
        created_at_gte: new Date(earliest - 5 * 60000).toISOString(),
        created_at_lte: new Date(+job.requestedAt + 5 * 60000).toISOString(),
      },
      { signal },
    )) {
      if (
        customer.metadata?.mailloopUserId === userId &&
        attempts.some((a) => a.id === customer.metadata?.checkoutAttemptId)
      )
        customers.add(customer.customer_id);
    }
  }
  await db.accountDeletionJob.updateMany({
    where: { userId },
    data: {
      customerIds: {
        push: [...customers].filter((id) => !job.customerIds.includes(id)),
      },
    },
  });
  const ids = new Set(job.subscriptionIds);
  for (const customerId of customers)
    for (const sub of await providerSubscriptions(customerId, signal))
      ids.add(sub.subscription_id);
  await db.accountDeletionJob.updateMany({
    where: { userId },
    data: {
      subscriptionIds: {
        push: [...ids].filter((id) => !job.subscriptionIds.includes(id)),
      },
    },
  });
  for (const id of ids) {
    let provider = providerSubscriptionSchema.parse(
      await dodoClient().subscriptions.retrieve(id, { signal }),
    );
    if (
      provider.subscription_id !== id ||
      !customers.has(provider.customer.customer_id) ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (!terminal(provider)) {
      await dodoClient()
        .subscriptions.update(
          id,
          {
            status: "cancelled",
            cancel_at_next_billing_date: false,
          },
          { signal },
        )
        .catch(() => {});
      provider = providerSubscriptionSchema.parse(
        await dodoClient().subscriptions.retrieve(id, { signal }),
      );
    }
    if (
      provider.subscription_id !== id ||
      !customers.has(provider.customer.customer_id) ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (!terminal(provider)) return false;
    if (provider.metadata.checkoutAttemptId)
      matchedAttempts.add(provider.metadata.checkoutAttemptId);
    await db.billingSubscription.updateMany({
      where: { userId, dodoSubscriptionId: id },
      data: {
        status: provider.status.toUpperCase() as
          "CANCELLED" | "EXPIRED" | "FAILED",
        cancelAtPeriodEnd: false,
        gracePeriodEnd: null,
        cancelRequestedAt: null,
      },
    });
  }
  // Still-open hosted checkout can create a subscription after cancellation.
  for (const attempt of attempts) {
    if (["COMPLETED", "FAILED", "EXPIRED"].includes(attempt.status)) continue;
    if (attempt.sessionId) {
      const session = await dodoClient().checkoutSessions.retrieve(
        attempt.sessionId,
        { signal },
      );
      if (
        session.payment_status &&
        !["failed", "cancelled"].includes(session.payment_status) &&
        !matchedAttempts.has(attempt.id)
      )
        return false;
    }
    if (new Date() < new Date(attempt.expiresAt)) return false;
  }
  for (const customerId of customers)
    if (
      (await providerSubscriptions(customerId, signal)).some(
        (s) => !terminal(s),
      )
    )
      return false;
  return true;
}

export async function stopBillingForDeletion(userId: string): Promise<boolean> {
  await runDeletionJob(userId, new Date(), { billingOnly: true });
  return Boolean(
    (
      await db.accountDeletionJob.findUnique({
        where: { userId },
        select: { billingCancelledAt: true },
      })
    )?.billingCancelledAt,
  );
}

export async function assertBillingDeletionSafe(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  if (
    (await tx.checkoutAttempt.count({
      where: { userId, status: { in: openCheckoutStates } },
    })) ||
    (await tx.billingSubscription.count({
      where: { userId, status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
    }))
  )
    throw new BillingError("BILLING_DELETION_PENDING");
}

import "server-only";

import DodoPayments from "dodopayments";
import { BillingError, billingConfig } from "./config";

export function dodoClient() {
  const config = billingConfig();
  return new DodoPayments({
    bearerToken: config.apiKey,
    webhookKey: config.webhookKey,
    environment: config.environment,
    baseURL: null,
    maxRetries: 0,
    timeout: 15_000,
    logLevel: "off",
  });
}

export function billingCheckoutUrl(
  value: string,
  environment: "test_mode" | "live_mode",
) {
  const url = new URL(value);
  if (
    url.protocol !== "https:" ||
    url.hostname !==
      (environment === "test_mode"
        ? "test.checkout.dodopayments.com"
        : "checkout.dodopayments.com") ||
    url.username ||
    url.password ||
    url.port ||
    url.hash
  )
    throw new BillingError("INVALID_CHECKOUT_URL");
  return url.toString();
}

import "server-only";

import { z } from "zod";

export const subscriptionEventTypes = [
  "subscription.active",
  "subscription.renewed",
  "subscription.updated",
  "subscription.past_due",
  "subscription.on_hold",
  "subscription.cancelled",
  "subscription.expired",
  "subscription.failed",
  "subscription.paused",
  "subscription.unpaused",
  "subscription.plan_changed",
  "subscription.update_payment_method",
] as const;
export const billingEventTypes = [
  ...subscriptionEventTypes,
  "payment.succeeded",
  "payment.failed",
  "payment.processing",
  "payment.cancelled",
] as const;
export const subscriptionStatuses = [
  "pending",
  "active",
  "past_due",
  "on_hold",
  "cancelled",
  "expired",
  "failed",
  "paused",
] as const;
const id = z.string().min(1).max(200);
const timestamp = z.iso.datetime({ offset: true });
const metadata = z
  .object({
    mailloopUserId: z.uuid().optional(),
    checkoutAttemptId: z.uuid().optional(),
  })
  .default({});
export const providerSubscriptionSchema = z.object({
  subscription_id: id,
  created_at: timestamp.optional(),
  customer: z.object({ customer_id: id }),
  product_id: id,
  status: z.enum(subscriptionStatuses),
  previous_billing_date: timestamp,
  next_billing_date: timestamp,
  cancel_at_next_billing_date: z.boolean(),
  currency: z.string().regex(/^[A-Z]{3}$/),
  billing: z.object({ country: z.string().regex(/^[A-Z]{2}$/) }),
  recurring_pre_tax_amount: z.number().int().nonnegative(),
  metadata,
  past_due_ends_at: timestamp.nullish(),
});
export type ProviderSubscription = z.infer<typeof providerSubscriptionSchema>;

export const normalizedSubscriptionSchema = z.object({
  kind: z.literal("subscription"),
  subscription: providerSubscriptionSchema,
});
export const normalizedPaymentSchema = z.object({
  kind: z.literal("payment"),
  paymentId: id,
  customerId: id,
  subscriptionId: id,
  checkoutSessionId: id.nullable(),
  succeeded: z.boolean(),
  status: z.enum(["succeeded", "failed", "processing", "cancelled"]).optional(),
  currency: z.string().regex(/^[A-Z]{3}$/),
  amount: z.number().int().nonnegative(),
  startsAt: timestamp.nullable(),
  endsAt: timestamp.nullable(),
  metadata,
});
export const normalizedBillingSchema = z.discriminatedUnion("kind", [
  normalizedSubscriptionSchema,
  normalizedPaymentSchema,
]);
export type NormalizedBilling = z.infer<typeof normalizedBillingSchema>;

// Explicit allowlists discard customer names, emails, addresses, card data and
// unrelated metadata before anything reaches the durable inbox or Inngest.
export function normalizeBillingEvent(input: unknown) {
  const envelope = z
    .object({ business_id: id, type: z.string(), timestamp, data: z.unknown() })
    .parse(input);
  if (!(billingEventTypes as readonly string[]).includes(envelope.type))
    return null;
  if (envelope.type.startsWith("subscription.")) {
    return {
      ...envelope,
      data: {
        kind: "subscription" as const,
        subscription: providerSubscriptionSchema.parse(envelope.data),
      },
    };
  }
  const payment = z
    .object({
      payment_id: id,
      customer: z.object({ customer_id: id }),
      status: z.string(),
      currency: z.string().regex(/^[A-Z]{3}$/),
      total_amount: z.number().int().nonnegative(),
      is_multi_subscription: z.boolean().optional(),
      is_update_payment_method: z.boolean().optional(),
      subscription_id: id.nullish(),
      subscription_ids: z.array(id).optional(),
      checkout_session_id: id.nullish(),
      service_periods: z
        .array(
          z.object({
            subscription_id: id,
            starts_at: timestamp,
            ends_at: timestamp,
          }),
        )
        .default([]),
      metadata,
    })
    .parse(envelope.data);
  if (payment.is_multi_subscription || payment.is_update_payment_method)
    return null;
  const subscriptionId =
    payment.subscription_id ?? payment.subscription_ids?.[0];
  if (!subscriptionId || (payment.subscription_ids?.length ?? 0) > 1)
    return null;
  const succeeded = envelope.type === "payment.succeeded";
  if (payment.status !== envelope.type.slice("payment.".length))
    throw new Error("Payment status mismatch");
  const period = payment.service_periods.find(
    (p) => p.subscription_id === subscriptionId,
  );
  if (
    succeeded &&
    (!period ||
      payment.total_amount <= 0 ||
      new Date(period.starts_at) >= new Date(period.ends_at))
  )
    throw new Error("Missing settled subscription service period");
  return {
    ...envelope,
    data: {
      kind: "payment" as const,
      paymentId: payment.payment_id,
      customerId: payment.customer.customer_id,
      subscriptionId,
      checkoutSessionId: payment.checkout_session_id ?? null,
      succeeded,
      status: payment.status as
        "succeeded" | "failed" | "processing" | "cancelled",
      currency: payment.currency,
      amount: payment.total_amount,
      startsAt: period?.starts_at ?? null,
      endsAt: period?.ends_at ?? null,
      metadata: payment.metadata,
    },
  };
}

import { consumeBudgets, rateLimitHttpError } from "@/lib/rate-limit";
import "server-only";
import { auth } from "@/auth";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";

export const privateBillingHeaders = {
  "Cache-Control": "private, no-store",
  "X-Content-Type-Options": "nosniff",
};
export async function billingSessionUser() {
  const session = await auth();
  if (!session?.user?.id)
    throw new BillingError("UNAUTHENTICATED", "Sign in first.", 401);
  const user = await db.user.findUnique({
    where: { id: session.user.id },
    select: { id: true, deletionRequestedAt: true, isSuspended: true },
  });
  if (!user || user.deletionRequestedAt)
    throw new BillingError("ACCOUNT_UNAVAILABLE", "Account unavailable.", 403);
  return user.id;
}
export function requireBillingOrigin(request: Request) {
  const origin = request.headers.get("origin");
  const configuredOrigin = billingConfig().origin;
  const isCanonicalProductionOrigin =
    configuredOrigin === "https://mailloop.in" &&
    origin === "https://www.mailloop.in";
  if (origin !== configuredOrigin && !isCanonicalProductionOrigin)
    throw new BillingError("INVALID_ORIGIN", "Invalid request origin.", 403);
}
export function billingHttpError(error: unknown) {
  const limited = rateLimitHttpError(error);
  if (limited) return limited;
  const known = error instanceof BillingError;
  return Response.json(
    {
      error: known ? error.message : "Billing is temporarily unavailable.",
      code: known ? error.code : "BILLING_UNAVAILABLE",
    },
    {
      status: known ? error.status : 503,
      headers: {
        ...privateBillingHeaders,
        ...(known && error.status === 429
          ? { "Retry-After": String(error.retryAfter ?? 60) }
          : {}),
      },
    },
  );
}

export const billingRequestLimits = {
  checkout: 5,
  portal: 10,
