) {
  await consumeBudgets(userId, [
    operation === "portal" || operation === "cancel"
      ? "billingManagement"
      : operation,
  ]);
}

import { safeLog } from "@/lib/observability";
import "server-only";

import { db } from "@/lib/db";
import { billingConfig } from "@/lib/billing/config";

import {
  processBillingEvent,
  reconcileBillingSubscription,
} from "@/lib/billing/lifecycle";
import { recoverCheckoutAttempt } from "@/lib/billing/checkout";
import { openCheckoutStates } from "@/lib/billing/store";
import { recoverBillingCancellation } from "./cancel";

// The committed inbox is the source of pending work. If post-response processing
// is interrupted, scheduled recovery retries the receipt using its durable backoff.
export async function retryBillingInbox() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const rows = await db.billingWebhookEvent.findMany({
    where: {
      processedAt: null,
      state: { in: ["RECEIVED", "RETRY"] },
      OR: [{ nextAttemptAt: null }, { nextAttemptAt: { lte: new Date() } }],
    },
    orderBy: [{ receivedAt: "asc" }, { id: "asc" }],
    take: 100,
  });
  let processed = 0;
  for (const row of rows) {
    try {
      await processBillingEvent(row.id);
      processed++;
    } catch {
      /* durable nextAttemptAt */
    }
  }
  return { processed, pending: rows.length - processed };
}

// Provider callbacks normally update access immediately; scheduled recovery repairs
// interrupted processing and missed delivery.
export async function recoverBilling() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const inbox = await retryBillingInbox();
  const attempts = await db.checkoutAttempt.findMany({
    where: {
      userId: { not: null },
      status: { in: openCheckoutStates },
      updatedAt: { lte: new Date(Date.now() - 30_000) },
    },
    orderBy: [{ updatedAt: "asc" }, { id: "asc" }],
    take: 50,
    select: { id: true, userId: true },
  });
  let checkoutFailures = 0;
  for (const attempt of attempts) {
    try {
      await recoverCheckoutAttempt(attempt.userId!, attempt.id);
      await db.checkoutAttempt.updateMany({
        where: {
          id: attempt.id,
          userId: attempt.userId,
          status: { in: openCheckoutStates },
        },
        data: { updatedAt: new Date() },
      });
    } catch {
      checkoutFailures++;
      // Rotate failures so one uncertain owner cannot starve the rest.
      await db.checkoutAttempt.updateMany({
        where: { id: attempt.id, userId: attempt.userId },
        data: { updatedAt: new Date() },
      });
    }
  }
  // Include mid-period cancellation/failure and recovery from hold, even if a
  // provider webhook was missed. Rotate through all attached nonterminal rows.
  const subscriptions = await db.billingSubscription.findMany({
    where: {
      userId: { not: null },
      OR: [
        { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
        { status: "CANCELLED", cancelAtPeriodEnd: true },
        { cancelRequestedAt: { not: null } },
      ],
    },
    orderBy: [{ updatedAt: "asc" }, { id: "asc" }],
    take: 50,
    select: { userId: true, dodoSubscriptionId: true },
  });
  let failed = 0;
  for (const subscription of subscriptions) {
    try {
      await recoverBillingCancellation(
        subscription.userId!,
        subscription.dodoSubscriptionId,
      );
      await reconcileBillingSubscription(
        subscription.userId!,
        subscription.dodoSubscriptionId,
      );
    } catch {
      failed++;
      // A permanently failing row must not starve other owners in the sweep.
      await db.billingSubscription.updateMany({
        where: {
          userId: subscription.userId,
          dodoSubscriptionId: subscription.dodoSubscriptionId,
        },
        data: { updatedAt: new Date() },
      });
    }
  }
  await db.billingRateLimit.deleteMany({
    where: { minuteBucket: { lt: new Date(Date.now() - 86400_000) } },
  });
  return {
    inbox,
    subscriptions: subscriptions.length,
    failed,
    checkoutFailures,
  };
}

// Pages are bounded. Owner locks and billingStateVersion fence reconciliation
// against callbacks and recovery; rerunning an interrupted command is safe.
export async function reconcileBillingPage(
  afterId: string | null,
  cutoff: string,
) {
  const rows = await db.billingSubscription.findMany({
    where: {
      userId: { not: null },
      createdAt: { lte: new Date(cutoff) },
      OR: [
        { status: { notIn: ["CANCELLED", "EXPIRED", "FAILED"] } },
        { status: "CANCELLED", cancelAtPeriodEnd: true },
        { cancelRequestedAt: { not: null } },
      ],
      ...(afterId ? { id: { gt: afterId } } : {}),
    },
    orderBy: { id: "asc" },
    take: 50,
    select: { id: true, userId: true, dodoSubscriptionId: true },
  });
  let failed = 0,
    missingSettlement = 0;
  for (const row of rows) {
    try {
      await recoverBillingCancellation(row.userId!, row.dodoSubscriptionId);
      await reconcileBillingSubscription(row.userId!, row.dodoSubscriptionId);
      const current = await db.billingSubscription.findFirst({
        where: { userId: row.userId, id: row.id },
      });
      if (
        current &&
        ["ACTIVE", "PAST_DUE"].includes(current.status) &&
        (!current.settledPaymentId ||
          !current.periodEnd ||
          current.periodEnd <= new Date())
      )
        missingSettlement++;
    } catch {
      failed++;
      safeLog("error", "billing", {
        subscriptionRecordId: row.id,
        code: "BILLING_RECONCILIATION_FAILED",
      });
    }
  }
  return {
    cursor: rows.length === 50 ? rows.at(-1)!.id : null,
    scanned: rows.length,
    failed,
    missingSettlement,
  };
}

async function reconcileCheckoutPage(afterId: string | null, cutoff: string) {
  const rows = await db.checkoutAttempt.findMany({
    where: {
      userId: { not: null },
      status: { in: openCheckoutStates },
      createdAt: { lte: new Date(cutoff) },
      ...(afterId ? { id: { gt: afterId } } : {}),
    },
    orderBy: { id: "asc" },
    take: 50,
    select: { id: true, userId: true },
  });
  let failed = 0;
  for (const row of rows) {
    try {
      await recoverCheckoutAttempt(row.userId!, row.id);
    } catch {
      failed++;
    }
  }
  return {
    cursor: rows.length === 50 ? rows.at(-1)!.id : null,
    scanned: rows.length,
    failed,
  };
}

export async function reconcileBilling() {
  try {
    billingConfig();
  } catch {
    return { disabled: true };
  }
  const cutoff = new Date().toISOString();
  let cursor: string | null = null;
  const totals = { scanned: 0, failed: 0, missingSettlement: 0 };
  do {
    const result = await reconcileBillingPage(cursor, cutoff);
    totals.scanned += result.scanned;
    totals.failed += result.failed;
    totals.missingSettlement += result.missingSettlement;
    cursor = result.cursor;
  } while (cursor);
  do {
    const result = await reconcileCheckoutPage(cursor, cutoff);
    totals.failed += result.failed;
    cursor = result.cursor;
  } while (cursor);
  const recovery = await recoverBilling();
  if (!("disabled" in recovery))
    totals.failed +=
      recovery.failed +
      recovery.checkoutFailures +
      (recovery.inbox && "pending" in recovery.inbox
        ? (recovery.inbox.pending ?? 0)
        : 0);
  const [quarantined, staleInbox, conflictingSubscriptions] = await Promise.all(
    [
      db.billingWebhookEvent.count({ where: { state: "QUARANTINED" } }),
      db.billingWebhookEvent.count({
        where: {
          processedAt: null,
          state: { in: ["RECEIVED", "RETRY"] },
          receivedAt: { lt: new Date(Date.now() - 3600_000) },
        },
      }),
      db.billingWebhookEvent.count({
        where: { failureCode: "CONFLICTING_SUBSCRIPTIONS" },
      }),
    ],
  );
  safeLog("info", "nightly", {
    ...totals,
    quarantined,
    staleInbox,
    conflictingSubscriptions,
    complete: totals.failed === 0,
  });
  if (totals.failed) throw new Error("BILLING_NIGHTLY_INCOMPLETE");
  return totals;
}

import "server-only";

import type { SubscriptionStatus } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { BillingError, billingConfig } from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";
import {
  normalizedBillingSchema,
  normalizedPaymentSchema,
  normalizedSubscriptionSchema,
  providerSubscriptionSchema,
} from "@/lib/billing/events";
import { ensureBillingBinding } from "@/lib/billing/store";
import { recoverRetainedDeletion, runDeletionJob } from "@/lib/deletion-jobs";
import { withUsageTransaction } from "@/lib/usage-ledger";

// A provider active status is not settlement proof. Periods are selected only
// from verified payment.succeeded inbox rows for this customer/subscription.
// A localized payment can use a different currency from the subscription; its
// signed service_periods establish coverage, not currency or amount conversion.
export async function reconcileBillingSubscription(
  userId: string,
  subscriptionId: string,
  eventId?: string,
) {
  let previousSnapshot: string | null = null;
  for (let retry = 0; retry < 3; retry++) {
    const before = await db.user.findUniqueOrThrow({
      where: { id: userId },
      select: { dodoCustomerId: true, billingStateVersion: true },
    });
    const fetchStarted = new Date();
    const provider = providerSubscriptionSchema.parse(
      await dodoClient().subscriptions.retrieve(subscriptionId),
    );
    const config = billingConfig();
    const snapshot = JSON.stringify([
      provider.status,
      provider.previous_billing_date,
      provider.next_billing_date,
      provider.cancel_at_next_billing_date,
    ]);
    const snapshotRepeated = previousSnapshot === snapshot;
    previousSnapshot = snapshot;
    if (
      provider.subscription_id !== subscriptionId ||
      provider.customer.customer_id !== before.dodoCustomerId ||
      (provider.metadata.mailloopUserId &&
        provider.metadata.mailloopUserId !== userId)
    )
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");

    const result = await withUsageTransaction(db, userId, async ({ tx }) => {
      await ensureBillingBinding(tx);
      const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
      if (
        eventId &&
        (
          await tx.billingWebhookEvent.findUniqueOrThrow({
            where: { id: eventId },
            select: { processedAt: true },
          })
        ).processedAt
      )
        return true;
      if (user.billingStateVersion !== before.billingStateVersion) return false;
      if (user.deletionRequestedAt)
        throw new BillingError("ACCOUNT_UNAVAILABLE");
      const finishEvent = async () => {
        if (eventId)
          await tx.billingWebhookEvent.updateMany({
            where: { id: eventId, processedAt: null },
            data: {
              state: "PROCESSED",
              processedAt: new Date(),
              nextAttemptAt: null,
              failureCode: null,
              attempts: { increment: 1 },
            },
          });
      };
      const existing = await tx.billingSubscription.findFirst({
        where: { userId, dodoSubscriptionId: subscriptionId },
      });
      const otherOwner = await tx.billingSubscription.findUnique({
        where: { dodoSubscriptionId: subscriptionId },
        select: { userId: true },
      });
      if (otherOwner && otherOwner.userId !== userId)
        throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
      // This release sells one fixed product. A portal/dashboard plan change
      // cannot reuse an older product's payment as proof for the allowed plan.
      // Keep the drifted product as a review marker, including if it changes
      // back. Cancellation followed by a new checkout establishes fresh proof.
      if (
        provider.product_id !== config.productId ||
        (existing && existing.productId !== config.productId)
      ) {
        if (!existing)
          throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
        await tx.billingSubscription.updateMany({
          where: { userId, dodoSubscriptionId: subscriptionId },
          data: {
            productId:
              provider.product_id !== config.productId
                ? provider.product_id
                : existing.productId,
            status: provider.status.toUpperCase() as SubscriptionStatus,
            cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
            cancelRequestedAt:
              provider.cancel_at_next_billing_date ||
              ["cancelled", "expired", "failed"].includes(provider.status)
                ? null
                : existing.cancelRequestedAt,
          },
        });
        await tx.user.updateMany({
          where: { id: userId, dodoSubscriptionId: subscriptionId },
          data: {
            plan: "FREE",
            cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
            subscriptionStatus:
              provider.status.toUpperCase() as SubscriptionStatus,
            gracePeriodEnd: null,
            billingStateVersion: { increment: 1 },
          },
        });
        return "unsupported" as const;
      }
      if (
        provider.metadata.checkoutAttemptId &&
        !(await tx.checkoutAttempt.findFirst({
          where: { id: provider.metadata.checkoutAttemptId, userId },
          select: { id: true },
        }))
      )
        throw new BillingError("CHECKOUT_OWNERSHIP_MISMATCH");
      const events = await tx.billingWebhookEvent.findMany({
        where: {
          businessId: config.businessId,
          customerId: user.dodoCustomerId!,
          subscriptionId,
          state: { notIn: ["QUARANTINED", "IGNORED"] },
        },
        orderBy: [{ occurredAt: "desc" }, { id: "desc" }],
      });
      const arrivedDuringFetch = events
        .filter((e) => e.receivedAt >= fetchStarted)
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .find((e) => e.success);
      if (
        arrivedDuringFetch?.success &&
        (arrivedDuringFetch.data.subscription.status !== provider.status ||
          new Date(
            arrivedDuringFetch.data.subscription.next_billing_date,
          ).getTime() !== new Date(provider.next_billing_date).getTime())
      )
        return false;
      const latestSignedSubscription = events
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .find((e) => e.success);
      if (!snapshotRepeated && latestSignedSubscription?.success) {
        const signed = latestSignedSubscription.data.subscription;
        if (
          signed.status !== provider.status ||
          signed.previous_billing_date !== provider.previous_billing_date ||
          signed.next_billing_date !== provider.next_billing_date ||
          signed.cancel_at_next_billing_date !==
            provider.cancel_at_next_billing_date
        )
          return false; // Recheck a conflicting API snapshot before trusting it.
      }
      const paymentData = events
        .filter((e) => e.eventType === "payment.succeeded")
        .map((e) => normalizedPaymentSchema.safeParse(e.normalizedData))
        .filter((p) => p.success)
        .map((p) => p.data);
      const ownedAttempts = await tx.checkoutAttempt.findMany({
        where: {
          userId,
          id: {
            in: paymentData
              .map((p) => p.metadata.checkoutAttemptId)
              .filter((id): id is string => Boolean(id)),
          },
        },
        select: { id: true },
      });
      const ownedAttemptIds = new Set(ownedAttempts.map((a) => a.id));
      const settlements = events
        .filter((e) => e.eventType === "payment.succeeded")
        .map((e) => normalizedPaymentSchema.safeParse(e.normalizedData))
        .filter((p) => p.success)
        .map((p) => p.data)
        .filter(
          (p) =>
            p.succeeded &&
            p.amount > 0 &&
            p.startsAt &&
            p.endsAt &&
            new Date(p.startsAt) < new Date(p.endsAt) &&
            (!p.metadata.checkoutAttemptId ||
              ownedAttemptIds.has(p.metadata.checkoutAttemptId)) &&
            (!p.metadata.mailloopUserId ||
              p.metadata.mailloopUserId === userId) &&
            p.customerId === user.dodoCustomerId &&
            p.subscriptionId === subscriptionId,
        );
      const paidCandidate = settlements.sort(
        (a, b) => new Date(b.endsAt!).getTime() - new Date(a.endsAt!).getTime(),
      )[0];
      if (
        paidCandidate &&
        new Date(paidCandidate.endsAt!) >
          new Date(provider.next_billing_date) &&
        !["cancelled", "expired", "failed"].includes(provider.status)
      )
        return false;
      if (
        paidCandidate &&
        existing?.periodEnd &&
        new Date(paidCandidate.endsAt!).getTime() ===
          existing.periodEnd.getTime() &&
        existing.periodStart &&
        new Date(paidCandidate.startsAt!).getTime() !==
          existing.periodStart.getTime()
      )
        throw new BillingError("CONFLICTING_SETTLEMENT_PERIOD");
      const paid =
        paidCandidate &&
        (!existing?.periodEnd ||
          new Date(paidCandidate.endsAt!) >= existing.periodEnd)
          ? paidCandidate
          : undefined;
      // A regressed GET cannot overwrite newer settled history. Retry the read.
      if (
        existing?.periodEnd &&
        new Date(provider.next_billing_date) < existing.periodEnd &&
        !["cancelled", "expired", "failed"].includes(provider.status)
      )
        return false;
      const periodStart = paid
        ? new Date(paid.startsAt!)
        : (existing?.periodStart ?? null);
      const periodEnd = paid
        ? new Date(paid.endsAt!)
        : (existing?.periodEnd ?? null);
      const settledPaymentId =
        paid?.paymentId ?? existing?.settledPaymentId ?? null;
      const hasPayment = Boolean(settledPaymentId && periodStart && periodEnd);
      // Retrieval currently omits grace deadline. Only accept a signed snapshot
      // whose status and provider billing dates still match the retrieved state.
      const graceEvent = events
        .map((e) => normalizedSubscriptionSchema.safeParse(e.normalizedData))
        .filter((e) => e.success)
        .map((e) => e.data.subscription)
        .find(
          (s) =>
            s.status === "past_due" &&
            new Date(s.previous_billing_date).getTime() ===
              new Date(provider.previous_billing_date).getTime() &&
            new Date(s.next_billing_date).getTime() ===
              new Date(provider.next_billing_date).getTime() &&
            s.past_due_ends_at,
        );
      const grace =
        provider.status === "past_due"
          ? graceEvent?.past_due_ends_at
          : ["active", "on_hold", "paused"].includes(provider.status) &&
              existing?.gracePeriodEnd &&
              (!paid || new Date(paid.startsAt!) <= existing.periodStart!)
            ? existing.gracePeriodEnd.toISOString()
            : null;
      const gracePeriodEnd =
        hasPayment && grace && new Date(grace) >= periodEnd!
          ? new Date(grace)
          : null;
      const now = new Date();
      const recoveringWithoutSettlement =
        provider.status === "active" && Boolean(gracePeriodEnd);
      const status = (
        recoveringWithoutSettlement ? "PAST_DUE" : provider.status.toUpperCase()
      ) as SubscriptionStatus;
      const record = {
        ownerIdSnapshot: userId,
        dodoCustomerId: provider.customer.customer_id,
        productId: provider.product_id,
        status,
        periodStart,
        periodEnd,
        gracePeriodEnd,
        cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
        cancelRequestedAt:
          provider.cancel_at_next_billing_date ||
          ["cancelled", "expired", "failed"].includes(provider.status)
            ? null
            : (existing?.cancelRequestedAt ?? null),
        currency: provider.currency,
        billingCountry: provider.billing.country,
        recurringAmountMinor: provider.recurring_pre_tax_amount,
        settledPaymentId,
        paymentConfirmedAt: hasPayment
          ? (existing?.paymentConfirmedAt ?? now)
          : null,
        lastEventAt: events[0]?.occurredAt ?? existing?.lastEventAt ?? null,
      };
      await tx.billingSubscription.upsert({
        where: { dodoSubscriptionId: subscriptionId },
        create: {
          ...record,
          userId,
          dodoSubscriptionId: subscriptionId,
          ...(provider.created_at
            ? { createdAt: new Date(provider.created_at) }
            : {}),
        },
        update: record,
      });

      // An obsolete subscription may update history, never replace a different
      // still-live projection. Reject simultaneous paid subscriptions for review.
      const projectingOther =
        user.dodoSubscriptionId && user.dodoSubscriptionId !== subscriptionId;
      if (projectingOther) {
        const current = await tx.billingSubscription.findFirst({
          where: { userId, dodoSubscriptionId: user.dodoSubscriptionId! },
        });
        const candidateCreatedAt =
          existing?.createdAt ??
          (provider.created_at ? new Date(provider.created_at) : null);
        if (
          current &&
          candidateCreatedAt &&
          candidateCreatedAt <= current.createdAt
        ) {
          await finishEvent();
          return true;
        }
        if (
          current &&
          (!["CANCELLED", "EXPIRED", "FAILED"].includes(current.status) ||
            (current.status === "CANCELLED" &&
              current.cancelAtPeriodEnd &&
              current.periodEnd &&
              current.periodEnd > new Date()))
        ) {
          if (["active", "past_due"].includes(provider.status))
            throw new BillingError("CONFLICTING_SUBSCRIPTIONS");
          await finishEvent();
          return true;
        }
        if (["cancelled", "expired", "failed"].includes(provider.status)) {
          await finishEvent();
          return true;
        }
      }
      const withinPaid = hasPayment && periodStart! <= now && now < periodEnd!;
      // cancel_at_next_billing_date leaves the provider active. Some cancellation
      // payloads report cancelled early with that flag; preserve only paid time.
      const scheduled =
        provider.cancel_at_next_billing_date &&
        provider.status === "cancelled" &&
        withinPaid;
      const eligible =
        (provider.status === "active" && hasPayment) ||
        (provider.status === "past_due" && hasPayment) ||
        scheduled;
      const projectionStatus: SubscriptionStatus =
        !hasPayment &&
        ["active", "pending", "past_due"].includes(provider.status)
          ? "PENDING"
          : scheduled
            ? "ACTIVE"
            : status;
      await tx.user.update({
        where: { id: userId },
        data: {
          plan: eligible ? "PAID" : "FREE",
          subscriptionStatus: projectionStatus,
          dodoSubscriptionId: subscriptionId,
          currentPeriodStart: periodStart,
          currentPeriodEnd: periodEnd,
          gracePeriodEnd,
          cancelAtPeriodEnd: provider.cancel_at_next_billing_date,
          billingCurrency: provider.currency,
          billingCountry: provider.billing.country,
          lastBillingEventAt: record.lastEventAt,
          billingStateVersion: { increment: 1 },
        },
      });
      // Keep the attempt open during initial activation until settlement or a
      // terminal provider state proves another checkout cannot conflict.
      if (
        hasPayment ||
        ["cancelled", "expired", "failed"].includes(provider.status)
      )
        await tx.checkoutAttempt.updateMany({
          where: {
            userId,
            productId: config.productId,
            status: {
              in: ["CREATING", "CUSTOMER_CREATING", "READY", "UNKNOWN"],
            },
            OR: [
              { id: provider.metadata.checkoutAttemptId ?? "" },
              {
                dodoSessionId: {
                  in: settlements
                    .map((p) => p.checkoutSessionId)
                    .filter((id): id is string => Boolean(id)),
                },
              },
            ],
          },
          data: {
            status: hasPayment ? "COMPLETED" : "FAILED",
            checkoutUrl: null,
            billingCountry: provider.billing.country,
          },
        });
      await finishEvent();
      return true;
    });
    if (result === "unsupported")
      throw new BillingError(
        "UNSUPPORTED_SUBSCRIPTION_PRODUCT",
        "This subscription changed to an unsupported product. Cancel it in the portal before starting a new checkout.",
        409,
      );
    if (result) return;
  }
  throw new BillingError("BILLING_SNAPSHOT_CHANGED");
}

export async function processBillingEvent(eventId: string) {
  const event = await db.billingWebhookEvent.findUnique({
    where: { id: eventId },
  });
  if (
    !event ||
    event.processedAt ||
    !["RECEIVED", "RETRY"].includes(event.state)
  )
    return;
  try {
    const data = normalizedBillingSchema.parse(event.normalizedData);
    if (event.businessId !== billingConfig().businessId)
      throw new BillingError("WEBHOOK_BUSINESS_MISMATCH");
    const customerId =
      data.kind === "payment"
        ? data.customerId
        : data.subscription.customer.customer_id;
    const subscriptionId =
      data.kind === "payment"
        ? data.subscriptionId
        : data.subscription.subscription_id;
    const deletionMetadata =
      data.kind === "payment" ? data.metadata : data.subscription.metadata;
    const deletion = await db.accountDeletionJob.findFirst({
      where: {
        OR: [
          { customerIds: { has: customerId } },
          ...(deletionMetadata.mailloopUserId
            ? [{ userId: deletionMetadata.mailloopUserId }]
            : []),
        ],
      },
    });
    if (deletion) {
      if (
        deletionMetadata.mailloopUserId &&
        deletionMetadata.mailloopUserId !== deletion.userId
      )
        throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
      // The signed event supplies durable recovery identifiers, never access.
      // Push avoids losing another late event racing the cancellation worker.
      await db.accountDeletionJob.updateMany({
        where: { userId: deletion.userId },
        data: {
          customerIds: { push: customerId },
          subscriptionIds: { push: subscriptionId },
          billingRequired: true,
          billingCancelledAt: null,
          completedAt: null,
          billingRecoveryVersion: { increment: 1 },
          nextAttemptAt: new Date(),
          nextBillingAttemptAt: new Date(),
        },
      });
      await db.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state: "IGNORED_DELETED_OWNER",
          processedAt: new Date(),
          nextAttemptAt: null,
          failureCode: null,
          normalizedData: { deletedOwner: true },
          attempts: { increment: 1 },
        },
      });
      await runDeletionJob(deletion.userId, new Date(), {
        billingOnly: true,
      }).catch(() => false);
      return;
    }
    // Service-owned identity discovery; subsequent resources are owner-scoped.
    const owner = await db.user.findUnique({
      where: { dodoCustomerId: customerId },
      select: { id: true, deletionRequestedAt: true },
    });
    if (!owner) {
      const retained = await db.billingSubscription.findFirst({
        where: {
          userId: null,
          dodoCustomerId: customerId,
          ownerIdSnapshot: { not: null },
        },
        select: { ownerIdSnapshot: true },
      });
      if (!retained?.ownerIdSnapshot)
        throw new BillingError("BILLING_OWNER_UNRESOLVED");
      await recoverRetainedDeletion(retained.ownerIdSnapshot, customerId);
      // One bounded re-entry routes this verified event through the new job.
      return processBillingEvent(eventId);
    }
    if (owner.deletionRequestedAt) {
      await runDeletionJob(owner.id, new Date(), { billingOnly: true });
      throw new BillingError("DELETED_OWNER_RECOVERY_PENDING");
    }
    const metadata =
      data.kind === "payment" ? data.metadata : data.subscription.metadata;
    if (metadata.mailloopUserId && metadata.mailloopUserId !== owner.id)
      throw new BillingError("SUBSCRIPTION_OWNERSHIP_MISMATCH");
    if (metadata.checkoutAttemptId) {
      const attempt = await db.checkoutAttempt.findFirst({
        where: { id: metadata.checkoutAttemptId, userId: owner.id },
      });
      if (!attempt) throw new BillingError("CHECKOUT_OWNERSHIP_MISMATCH");
    }
    if (data.kind === "payment" && !data.succeeded) {
      await db.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state: "PROCESSED",
          processedAt: new Date(),
          nextAttemptAt: null,
          failureCode: null,
          attempts: { increment: 1 },
        },
      });
      return;
    }
    await reconcileBillingSubscription(owner.id, subscriptionId, eventId);
  } catch (error) {
    await db.$transaction(async (tx) => {
      await tx.billingWebhookEvent.updateMany({
        where: { id: eventId, processedAt: null },
        data: {
          state:
            event.attempts >= 7 ||
            (error instanceof BillingError &&
              [
                "UNSUPPORTED_SUBSCRIPTION_PRODUCT",
                "SUBSCRIPTION_OWNERSHIP_MISMATCH",
                "CHECKOUT_OWNERSHIP_MISMATCH",
                "CONFLICTING_SUBSCRIPTIONS",
              ].includes(error.code))
              ? "QUARANTINED"
              : "RETRY",
          failureCode:
            error instanceof BillingError
              ? error.code
              : "BILLING_RECONCILIATION_FAILED",
          attempts: { increment: 1 },
          nextAttemptAt: new Date(
            Date.now() +
              Math.min(3600_000, 30_000 * 2 ** Math.min(event.attempts, 7)),
          ),
        },
      });
    });
    throw new BillingError("BILLING_EVENT_RETRY");
  }
}

import "server-only";

import { billingConfig } from "@/lib/billing/config";
import { recoverBilling, reconcileBilling } from "@/lib/billing/jobs";
import { inngest } from "@/lib/inngest-client";
import { sweepSubscriptionLifecycle } from "@/lib/subscription-maintenance";

// One invocation every four hours keeps baseline usage within Inngest Free's monthly
// execution allowance. The operations are safe to repeat if Inngest retries.
export const billingMaintenance = inngest.createFunction(
  {
    id: "billing-maintenance",
    triggers: { cron: "0 */4 * * *" },
    concurrency: 1,
  },
  async ({ event }) => {
    // Preview deployments may share production's database.
    if (process.env.VERCEL && process.env.VERCEL_ENV !== "production")
      return { skipped: true };

    const scheduledAt = new Date(event.ts);
    if (Number.isNaN(scheduledAt.getTime()))
      throw new Error("BILLING_SCHEDULE_INVALID_TIME");

    await sweepSubscriptionLifecycle();

    billingConfig();
    const result = await recoverBilling();
    if ("disabled" in result) throw new Error("BILLING_RECOVERY_DISABLED");
    const failed =
      result.failed +
      result.checkoutFailures +
      (result.inbox && "pending" in result.inbox
        ? (result.inbox.pending ?? 0)
        : 0);
    if (failed) throw new Error("BILLING_RECOVERY_INCOMPLETE");

    if (scheduledAt.getUTCHours() === 0 && scheduledAt.getUTCMinutes() === 0) {
      billingConfig();
      await reconcileBilling();
    }

    return { complete: true };
  },
);

import "server-only";
import { db } from "@/lib/db";
import { billingConfig } from "@/lib/billing/config";

import { getEffectivePlan } from "@/lib/entitlements";

export async function readBillingStatus(userId: string) {
  let config: ReturnType<typeof billingConfig> | null = null;
  try {
    config = billingConfig();
  } catch {
    /* unavailable until configured */
  }
  const user = await db.user.findUniqueOrThrow({
    where: { id: userId },
    select: {
      id: true,
      plan: true,
      subscriptionStatus: true,
      dodoSubscriptionId: true,
      currentPeriodStart: true,
      currentPeriodEnd: true,
      cancelAtPeriodEnd: true,
      gracePeriodEnd: true,
      billingCountry: true,
      billingCurrency: true,
      dodoCustomerId: true,
      planOverride: true,
      planOverrideStartsAt: true,
      planOverrideExpiresAt: true,
      grandfatheredUntil: true,
      deletionRequestedAt: true,
      isSuspended: true,
      gmailAuthorized: true,
    },
  });
  // Persisted evidence remains readable during provider configuration outages.
  const [subscription, attempt] = await Promise.all([
    db.billingSubscription.findFirst({
      where: { userId, dodoSubscriptionId: user.dodoSubscriptionId ?? "" },
      select: {
        settledPaymentId: true,
        cancelRequestedAt: true,
        recurringAmountMinor: true,
        currency: true,
      },
    }),
    db.checkoutAttempt.findFirst({
      where: { userId },
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      select: { status: true },
    }),
  ]);
  const control = await db.systemControl.findUnique({
    where: { key: "global" },
    select: {
      billingCheckoutEnabled: true,
      dodoEnvironment: true,
      dodoBusinessId: true,
    },
  });
  const configured = Boolean(
    config &&
    control &&
    ((control.dodoEnvironment === null && control.dodoBusinessId === null) ||
      (control.dodoEnvironment === config.environment &&
        control.dodoBusinessId === config.businessId)),
  );
  const now = new Date();
  return {
    configured,
    checkoutEnabled: configured && Boolean(control?.billingCheckoutEnabled),
    cancellationPending: Boolean(subscription?.cancelRequestedAt),
    mode: configured
      ? config?.environment === "live_mode"
        ? ("live" as const)
        : ("test" as const)
      : null,
    plan: getEffectivePlan(user, now),
    status: user.subscriptionStatus,
    paymentConfirmed: Boolean(subscription?.settledPaymentId),
    cancelAtPeriodEnd: user.cancelAtPeriodEnd,
    periodStart: user.currentPeriodStart?.toISOString() ?? null,
    recurringAmountMinor: subscription?.recurringAmountMinor ?? null,
    recurringCurrency: subscription?.currency ?? null,
    isSuspended: user.isSuspended,
    periodEnd: user.currentPeriodEnd?.toISOString() ?? null,
    gracePeriodEnd: user.gracePeriodEnd?.toISOString() ?? null,
    billingCountry: user.billingCountry,
    billingCurrency: user.billingCurrency,
    hasCustomer: Boolean(user.dodoCustomerId),
    checkoutState: attempt?.status ?? null,
    hasOverride: Boolean(
      (user.planOverride !== null &&
        user.planOverrideStartsAt &&
        user.planOverrideStartsAt <= now &&
        (!user.planOverrideExpiresAt || user.planOverrideExpiresAt > now)) ||
      (user.grandfatheredUntil && user.grandfatheredUntil > now),
    ),
  };
}
export type ClientBillingStatus = Awaited<ReturnType<typeof readBillingStatus>>;

import "server-only";

import type { Prisma } from "@/generated/prisma/client";
import {
  billingConfig,
  BillingError,
  BILLING_PRICES,
} from "@/lib/billing/config";
import { dodoClient } from "@/lib/billing/dodo";

export const openCheckoutStates = [
  "CREATING",
  "CUSTOMER_CREATING",
  "READY",
  "UNKNOWN",
];
export const nonRenewingStates = ["CANCELLED", "EXPIRED", "FAILED"] as const;

// Call only inside a short owner-locked transaction. This singleton is service
// configuration, not user data. Never adopt pre-existing unbound provider data.
export async function ensureBillingBinding(tx: Prisma.TransactionClient) {
  const config = billingConfig();
  await tx.$queryRaw`SELECT id FROM "SystemControl" WHERE key = 'global' FOR UPDATE`;
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  if (!control) throw new BillingError("BILLING_CONTROL_MISSING");
  if (control.dodoEnvironment === null && control.dodoBusinessId === null) {
    if (
      (await tx.billingSubscription.count()) ||
      (await tx.checkoutAttempt.count()) ||
      (await tx.user.count({ where: { dodoCustomerId: { not: null } } }))
    )
      throw new BillingError("BILLING_BINDING_REVIEW_REQUIRED");
    await tx.systemControl.update({
      where: { key: "global" },
      data: {
        dodoEnvironment: config.environment,
        dodoBusinessId: config.businessId,
      },
    });
  } else if (
    control.dodoEnvironment !== config.environment ||
    control.dodoBusinessId !== config.businessId
  ) {
    throw new BillingError("BILLING_BINDING_MISMATCH");
  }
}

export async function verifyBillingProduct() {
  const config = billingConfig();
  const client = dodoClient();
  const [product, localized] = await Promise.all([
    client.products.retrieve(config.productId),
    client.products.localizedPrices.list(config.productId),
  ]);
  const india = localized.items[0];
  if (
    product.business_id !== config.businessId ||
    product.product_id !== config.productId ||
    !product.is_recurring ||
    product.price.type !== "recurring_price" ||
    product.price.payment_frequency_count !== 1 ||
    product.price.payment_frequency_interval !== "Month" ||
    (product.price.trial_period_days ?? 0) !== 0 ||
    product.price.price !== BILLING_PRICES.USD ||
    product.price.currency !== "USD" ||
    product.pricing_mode !== "by_country" ||
    product.price.tax_inclusive !== true ||
    product.price.subscription_period_count !== 20 ||
    product.price.subscription_period_interval !== "Year" ||
    (product.price.discount ?? 0) !== 0 ||
    (product.price.discount_bps ?? 0) !== 0 ||
    product.price.purchasing_power_parity === true ||
    (product.price.trial_amount ?? 0) !== 0 ||
    (product.addons?.length ?? 0) !== 0 ||
    localized.items.length !== 1 ||
    india?.product_id !== config.productId ||
    india.mode !== "by_country" ||
    india.country_code !== "IN" ||
    india.currency !== "INR" ||
    india.amount !== BILLING_PRICES.INR
  )
    throw new BillingError("BILLING_PRODUCT_MISMATCH");
  return product;
}

import { safeLog } from "@/lib/observability";
import "server-only";

import { createHash } from "node:crypto";
import { z } from "zod";
import { db } from "@/lib/db";
import { billingConfig, BillingError } from "./config";
import { billingEventTypes, normalizeBillingEvent } from "./events";

export async function storeBillingEvent(
  rawBody: string,
  verifiedPayload: unknown,
  webhookId: string,
) {
  const envelope = z
    .object({
      business_id: z.string(),
      type: z.unknown().optional(),
      timestamp: z.unknown().optional(),
    })
    .safeParse(verifiedPayload);
  if (
    !envelope.success ||
    envelope.data.business_id !== billingConfig().businessId
  )
    throw new BillingError(
      "WEBHOOK_BUSINESS_MISMATCH",
      "Invalid webhook business.",
      400,
    );
  const eventType =
    typeof envelope.data.type === "string" && envelope.data.type.length <= 200
      ? envelope.data.type
      : "unknown";
  const recognized = (billingEventTypes as readonly string[]).includes(
    eventType,
  );
  let event: ReturnType<typeof normalizeBillingEvent> = null;
  try {
    event = normalizeBillingEvent(verifiedPayload);
  } catch {
    /* persist minimal quarantine receipt */
  }
  const state = event ? "RECEIVED" : recognized ? "QUARANTINED" : "IGNORED";
  const occurredAt = new Date(
    typeof envelope.data.timestamp === "string" ? envelope.data.timestamp : "",
  );
  const payloadHash = createHash("sha256").update(rawBody).digest("hex");
  const data = event?.data;
  // Native upsert preserves the first delivery, even under concurrent requests.
  const row = await db.$transaction(async (tx) => {
    const receipt = await tx.billingWebhookEvent.upsert({
      where: { webhookId },
      create: {
        webhookId,
        payloadHash,
        businessId: envelope.data.business_id,
        eventType,
        subscriptionId:
          data?.kind === "subscription"
            ? data.subscription.subscription_id
            : (data?.subscriptionId ?? null),
        customerId:
          data?.kind === "subscription"
            ? data.subscription.customer.customer_id
            : (data?.customerId ?? null),
        paymentId: data?.kind === "payment" ? data.paymentId : null,
        occurredAt: Number.isFinite(occurredAt.getTime())
          ? occurredAt
          : new Date(),
        normalizedData: data ?? {},
        state,
        processedAt: state === "IGNORED" ? new Date() : null,
        failureCode: state === "QUARANTINED" ? "UNUSABLE_BILLING_DATA" : null,
      },
      update: {},
    });
    return receipt;
  });
  if (row.payloadHash !== payloadHash) {
    safeLog("error", "webhook", {
      code: "WEBHOOK_ID_CONFLICT",
      receiptId: row.id,
    });
    throw new BillingError("WEBHOOK_ID_CONFLICT", "Conflicting webhook.", 409);
  }
  return row;
}

import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import {
  getClientEntitlements,
  getEffectivePlan,
  hasUnresolvedBillingPeriod,
  EntitlementError,
} from "@/lib/entitlements";
import { requireTemplateAccess } from "@/lib/template-policy";
import { AppError } from "@/lib/errors";
import { cancelQueuedIn } from "@/lib/cancellation";

// Owner lock is required. The immutable send snapshots describe the original
// campaign, including its completed and cancelled recipients.
export async function cancelIneligibleCampaign(
  tx: Prisma.TransactionClient,
  userId: string,
  campaignId: string,
  now = new Date(Date.now()),
) {
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  const access = getClientEntitlements(user, control, now);
  if (
    !access.paidGatingEnabled ||
    !access.features.templateUse ||
    hasUnresolvedBillingPeriod(user, now)
  )
    return false;
  const campaign = await tx.campaign.findFirst({
    where: { id: campaignId, userId },
    include: {
      sends: {
        select: { id: true, recipientRole: true, recipientEmail: true },
      },
    },
  });
  if (!campaign) return true;
  let reason: string | null = null;
  let reasonCode = "FREE_FEATURE";
  if (
    Math.max(campaign.approvedRecipientCount, campaign.sends.length) >
    access.limits.campaignRecipients
  ) {
    reason = `This campaign exceeds your current ${access.limits.campaignRecipients}-recipient limit.`;
    reasonCode = "FREE_RECIPIENT_LIMIT";
  }
  if (!reason) {
    try {
      if (!campaign.templateId)
        throw new AppError("The campaign template is unavailable.");
      await requireTemplateAccess(tx, userId, campaign.templateId);
    } catch (error) {
      if (!(error instanceof AppError)) throw error;
      reasonCode = "FREE_TEMPLATE";
      reason =
        error instanceof EntitlementError
          ? "This campaign requires a template outside your current plan."
          : error.message;
    }
  }
  // Approved role snapshots remain usable after downgrade or contact removal.
  // New role titles are checked atomically when the campaign is submitted.
  if (!reason) return false;
  await cancelCampaignWithNotice(
    tx,
    userId,
    campaignId,
    reasonCode,
    reason,
    now,
  );
  return true;
}

export async function cancelCampaignWithNotice(
  tx: Prisma.TransactionClient,
  userId: string,
  campaignId: string,
  reasonCode: string,
  reason: string,
  now = new Date(Date.now()),
) {
  const ready = await tx.send.findMany({
    where: {
      campaignId,
      campaign: { userId },
      status: "QUEUED",
      deliveryState: "READY",
      attemptedAt: null,
    },
    select: { id: true },
  });
  const result = await cancelQueuedIn(tx, userId, { campaignId });
  if (!result.cancelled) return;
  await tx.send.updateMany({
    where: {
      id: { in: ready.map((s) => s.id) },
      campaign: { userId },
      status: "CANCELLED",
    },
    data: { error: `Cancelled: ${reason}` },
  });
  await tx.accountNotice.upsert({
    where: {
      userId_deduplicationKey: {
        userId,
        deduplicationKey: `downgrade:${campaignId}`,
      },
    },
    create: {
      userId,
      deduplicationKey: `downgrade:${campaignId}`,
      campaignIdSnapshot: campaignId,
      reasonCode,
      cancelledCount: result.cancelled,
      createdAt: now,
    },
    update: {},
  });
}

import { resolveUsagePeriods } from "@/lib/usage-periods";
import {
  ensureUsagePeriods,
  requireUsageReady,
  rebindReadyRemainder,
  type UsageOwnerTransaction,
} from "@/lib/usage-ledger";

/** One owner lock covers the complete allocation, notices and cancellation.
 * Delayed READY work competes too; attempted/uncertain evidence is never released. */
export async function applyFreeCampaignPolicy(
  owner: UsageOwnerTransaction,
  now = new Date(Date.now()),
) {
  const { tx, userId } = owner;
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const control = await tx.systemControl.findUnique({
    where: { key: "global" },
  });
  if (
    !control?.paidGatingEnabled ||
    user.deletionRequestedAt ||
    user.isSuspended ||
    getEffectivePlan(user, now) !== "FREE" ||
    hasUnresolvedBillingPeriod(user, now)
  )
    return;
  // Whole-campaign allocation is a downgrade effect. Ordinary Free renewal
  // boundaries continue to use the existing reservation/deferral policy.
  if (
    !user.dodoSubscriptionId &&
    !user.planOverride &&
    !user.grandfatheredUntil
  )
    return;
  const campaigns = await tx.campaign.findMany({
    where: {
      userId,
      sends: {
        some: { status: "QUEUED", deliveryState: "READY", attemptedAt: null },
      },
    },
    orderBy: [{ createdAt: "asc" }, { id: "asc" }],
  });
  if (!campaigns.length) return;
  await requireUsageReady(owner, true, now);
  const specs = resolveUsagePeriods(user, now);
  const buckets = await ensureUsagePeriods(owner, specs);
  const ready = await tx.usageReservation.findMany({
    where: {
      userId,
      status: "RESERVED",
      chargedAt: null,
      send: {
        status: "QUEUED",
        deliveryState: "READY",
        attemptedAt: null,
        sentAt: null,
        gmailMessageId: null,
        campaign: { userId },
      },
    },
    include: { send: { select: { campaignId: true } } },
  });
  let daily =
    buckets.daily.sent +
    buckets.daily.reserved -
    ready.filter((r) => r.dailyPeriodId === buckets.daily.id).length;
  let monthly =
    buckets.monthly.sent +
    buckets.monthly.reserved -
    ready.filter((r) => r.monthlyPeriodId === buckets.monthly.id).length;
  for (const campaign of campaigns) {
    if (await cancelIneligibleCampaign(tx, userId, campaign.id, now)) continue;
    const remainder = ready.filter((r) => r.send?.campaignId === campaign.id);
    if (
      daily + remainder.length > specs.daily.limit ||
      monthly + remainder.length > specs.monthly.limit
    ) {
      await cancelCampaignWithNotice(
        tx,
        userId,
        campaign.id,
        "FREE_ALLOWANCE",
        "The complete unsent remainder exceeds your current Free allowance.",
        now,
      );
      continue;
    }
    await rebindReadyRemainder(
      owner,
      remainder.map((r) => r.deliveryKey),
      specs,
    );
    daily += remainder.length;
    monthly += remainder.length;
  }
}

