import "server-only";
import { db } from "@/lib/db";

export type CampaignProgressData = {
  id: string;
  createdAt: string;
  observedAt: string;
  finishedAt: string | null;
  queued: number;
  sent: number;
  failed: number;
  cancelled: number;
  review: number;
  pendingDispatch: boolean;
  delays: {
    sendId: string;
    recipient: string;
    state: "READY" | "ATTEMPTING";
    startedAt: string;
  }[];
  outstanding: number;
  sending: number;
  nextSendAt: string | null;
};

// Include observed batches until this History visit ends, even after delivery finishes.
export async function readCampaignProgress(
  user: { id: string; nextSendAt: Date | null },
  campaignIds: string[] = [],
): Promise<CampaignProgressData | null> {
  const campaignSelect = {
    id: true,
    createdAt: true,
    sends: {
      where: { campaign: { userId: user.id }, historyDeletedAt: null },
      select: {
        id: true,
        recipientEmail: true,
        status: true,
        createdAt: true,
        deliveryState: true,
        dispatchedAt: true,
        sentAt: true,
        attemptedAt: true,
        cancelledAt: true,
      },
    },
  } as const;
  const batches = await db.campaign.findMany({
    where: {
      userId: user.id,
      sends: { some: { historyDeletedAt: null } },
      OR: [
        { id: { in: campaignIds } },
        {
          sends: {
            some: {
              OR: [{ status: "QUEUED" }, { deliveryState: "UNCERTAIN" }],
            },
          },
        },
      ],
    },
    select: campaignSelect,
    orderBy: [{ createdAt: "asc" }, { id: "asc" }],
  });
  const now = new Date();
  const [queue, activity] = await Promise.all([
    db.send.findMany({
      where: {
        campaign: { userId: user.id },
        status: "QUEUED",
        deliveryState: { in: ["READY", "ATTEMPTING"] },
      },
      select: {
        id: true,
        recipientEmail: true,
        deliveryState: true,
        createdAt: true,
        attemptedAt: true,
        availableAt: true,
        queueExpiresAt: true,
      },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
    }),
    db.send.aggregate({
      where: { campaign: { userId: user.id }, status: { not: "QUEUED" } },
      _max: { sentAt: true, cancelledAt: true, attemptedAt: true },
    }),
  ]);
  const batchSends = batches.flatMap((batch) => batch.sends);
  const visibleIds = new Set(batchSends.map((send) => send.id));
  const delays: CampaignProgressData["delays"] = [];
  const attempting = queue.filter(
    (send) => send.deliveryState === "ATTEMPTING",
  );
  for (const send of attempting) {
    if (visibleIds.has(send.id) && send.attemptedAt)
      delays.push({
        sendId: send.id,
        recipient: send.recipientEmail,
        state: "ATTEMPTING",
        startedAt: send.attemptedAt.toISOString(),
      });
  }
  // Only the head of the eligible queue accrues pickup delay. Publication
  // timestamps are deliberately excluded: recovery retries must not reset it.
  const next = queue.find(
    (send) =>
      send.deliveryState === "READY" &&
      (!send.availableAt || send.availableAt <= now) &&
      (!send.queueExpiresAt || send.queueExpiresAt > now),
  );
  if (!attempting.length && next && visibleIds.has(next.id)) {
    const start = Math.max(
      +next.createdAt,
      +(next.availableAt ?? next.createdAt),
      +(user.nextSendAt ?? next.createdAt),
      ...Object.values(activity._max).map((date) => +(date ?? next.createdAt)),
    );
    if (start <= +now)
      delays.push({
        sendId: next.id,
        recipient: next.recipientEmail,
        state: "READY",
        startedAt: new Date(start).toISOString(),
      });
  }
  const createdAt = batches[0]?.createdAt;
  const outstanding = batchSends.filter(
    (s) => s.status === "QUEUED" && s.deliveryState !== "UNCERTAIN",
  ).length;
  return createdAt
    ? {
        id: batches.map((batch) => batch.id).join(":"),
        observedAt: now.toISOString(),
        createdAt: createdAt.toISOString(),
        finishedAt: batchSends.every(
          (s) => s.status !== "QUEUED" && s.deliveryState !== "UNCERTAIN",
        )
          ? (batchSends
              .map(
                (s) => s.cancelledAt ?? s.sentAt ?? s.attemptedAt ?? createdAt,
              )
              .sort((a, b) => b.getTime() - a.getTime())[0]
              ?.toISOString() ?? createdAt.toISOString())
          : null,
        queued: outstanding,
        sent: batchSends.filter(
          (s) =>
            ["SENT", "REPLIED"].includes(s.status) &&
            s.deliveryState !== "UNCERTAIN",
        ).length,
        failed: batchSends.filter(
          (s) => s.status === "FAILED" && s.deliveryState !== "UNCERTAIN",
        ).length,
        cancelled: batchSends.filter((s) => s.status === "CANCELLED").length,
        review: batchSends.filter((s) => s.deliveryState === "UNCERTAIN")
          .length,
        pendingDispatch: batchSends.some(
          (s) =>
            s.status === "QUEUED" &&
            !s.dispatchedAt &&
            s.deliveryState !== "UNCERTAIN",
        ),
        delays,
        outstanding,
        sending: batchSends.filter(
          (s) => s.status === "QUEUED" && s.deliveryState === "ATTEMPTING",
        ).length,
        nextSendAt: user.nextSendAt?.toISOString() ?? null,
      }
    : null;
}

import { applyFreeCampaignPolicy } from "@/lib/campaign-policy";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import "server-only";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import {
  campaignSchema,
  renderTemplate,
  templateSchema,
} from "@/lib/validation";
import { AppError } from "@/lib/errors";
import { countQuotaUsage } from "@/lib/delivery-usage";
import { requireTemplateAccess } from "@/lib/template-policy";
import { isCanonicalRole } from "@/lib/roles";
import {
  canUser,
  EntitlementError,
  getClientEntitlements,
  requireEntitlement,
} from "@/lib/entitlements";
import {
  resolveUsagePeriods,
  historicalUsagePeriods,
} from "@/lib/usage-periods";
import {
  requireUsageReady,
  reserveUsage,
  withUsageTransaction,
} from "@/lib/usage-ledger";
export async function createCampaign(userId: string, input: unknown) {
  const data = campaignSchema.parse(input);
  return withUsageTransaction(db, userId, async (owner) => {
    const { tx } = owner;
    const active = await tx.user.findUnique({ where: { id: userId } });
    if (!active || active.deletionRequestedAt)
      throw new AppError("Account unavailable.");
    const previous = await tx.campaign.findFirst({
      where: { userId, idempotencyKey: data.idempotencyKey },
    });
    if (previous)
      return {
        id: previous.id,
        count: await tx.send.count({
          where: { campaignId: previous.id, campaign: { userId } },
        }),
        skipped: 0,
      };
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    if (!user.gmailAuthorized || !user.encryptedRefreshToken)
      throw new AppError("Reconnect Gmail in Settings before sending.");
    const control = await tx.systemControl.findUnique({
      where: { key: "global" },
    });
    const access = canUser(user, "send", control);
    if (!access.allowed) throw new EntitlementError(access.reason);
    const features = getClientEntitlements(user, control);
    if (data.recipientIds.length > features.limits.campaignRecipients) {
      const error = new AppError(
        `Choose at most ${features.limits.campaignRecipients} recipients for your current plan.`,
      );
      throw Object.assign(error, { code: "CAMPAIGN_RECIPIENT_LIMIT" });
    }
    if (data.resendIds.length)
      await requireEntitlement(userId, "manualRepeatSend", tx);
    await requireUsageReady(owner, control!.paidGatingEnabled);
    await applyFreeCampaignPolicy(owner);
    const now = new Date(Date.now());
    const periods = control!.paidGatingEnabled
      ? resolveUsagePeriods(user, now)
      : historicalUsagePeriods(user, now);
    const template = await tx.template.findFirst({
      where: { id: data.templateId, userId, archivedAt: null },
    });
    if (!template) throw new AppError("Choose an available template.");
    await requireTemplateAccess(tx, userId, template.id);
    templateSchema.parse(template);
    const contacts = await tx.contact.findMany({
      where: {
        id: { in: data.recipientIds },
        userId,
        archivedAt: null,
        shortlistRemovedAt: null,
      },
    });
    if (contacts.length !== data.recipientIds.length)
      throw new AppError("One or more contacts are unavailable.");
    const history = await tx.send.findMany({
      where: {
        campaign: { userId },
        OR: [
          { contactId: { in: contacts.map((c) => c.id) } },
          { recipientEmail: { in: contacts.map((c) => c.email) } },
        ],
        AND: [
          {
            OR: [
              { status: { in: ["QUEUED", "SENT", "REPLIED"] } },
              { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
            ],
          },
        ],
      },
      select: {
        contactId: true,
        recipientEmail: true,
        status: true,
        deliveryState: true,
      },
    });
    const receipts = await tx.deliveryReceipt.findMany({
      where: { userId, recipientEmail: { in: contacts.map((c) => c.email) } },
      select: { recipientEmail: true },
    });
    const selected = contacts.filter((c) => {
      const prior = history.filter(
        (s) => s.contactId === c.id || s.recipientEmail === c.email,
      );
      if (
        prior.some(
          (s) =>
            s.status === "QUEUED" ||
            ["ATTEMPTING", "UNCERTAIN"].includes(s.deliveryState),
        )
      )
        return false;
      const alreadyEmailed =
        receipts.some((r) => r.recipientEmail === c.email) ||
        prior.some(
          (s) =>
            s.recipientEmail === c.email &&
            (s.status === "SENT" || s.status === "REPLIED"),
        );
      return !alreadyEmailed || data.resendIds.includes(c.id);
    });
    if (!selected.length)
      throw new AppError(
        "All selected contacts were skipped. Choose new recipients or select a yellow recipient for a follow-up.",
      );
    if (
      !control!.paidGatingEnabled &&
      (await countQuotaUsage(userId, tx)) + selected.length > DAILY_EMAIL_LIMIT
    )
      throw new AppError(
        `This campaign would exceed ${DAILY_EMAIL_LIMIT} emails per rolling 24 hours, including queued emails.`,
      );
    const attachment =
      data.attachResume && user.currentAttachmentId
        ? await tx.attachment.findFirst({
            where: { id: user.currentAttachmentId, userId, deletedAt: null },
          })
        : null;
    if (
      Object.keys(data.recipientRoles).some(
        (id) => !data.recipientIds.includes(id),
      )
    )
      throw new AppError("Role overrides must belong to selected recipients.");
    if (data.attachResume && !attachment)
      throw new AppError("Upload a PDF in Settings or turn off Attach PDF.");
    const hasRoleOverride = selected.some(
      (contact) =>
        data.recipientRoles[contact.id] !== undefined &&
        data.recipientRoles[contact.id] !== (contact.jobRole?.trim() ?? ""),
    );
    if (hasRoleOverride && !features.features.recipientRoleOverride)
      throw new AppError(
        "Changing a recipient’s role in Compose requires Premium. Edit the saved role in Contacts.",
        "role",
      );
    const snapshots = selected.map((c) => {
      const role = data.recipientRoles[c.id] ?? c.jobRole;
      if (!role?.trim())
        throw new AppError("Choose a job role for every recipient.", "role");
      const values = {
        name: c.name,
        company: c.company,
        role,
      };

      const subject = renderTemplate(template.subject, values);
      if (/[\r\n]/.test(subject))
        throw new AppError(
          "A recipient value makes the subject span multiple lines. Edit that contact.",
        );
      const id = randomUUID();
      return {
        id,
        contactId: c.id,
        recipientEmail: c.email,
        recipientName: c.name,
        recipientRole: role,
        recipientCompany: c.company ?? "",
        templateName: template.name,
        subject,
        body: renderTemplate(template.body, values),
        mimeMessageId: `<${id}@mailloop.in>`,
        availableAt: now,
        queueExpiresAt: new Date(+now + 86400000),
      };
    });
    const campaign = await tx.campaign.create({
      data: {
        userId,
        templateId: template.id,
        role: "",
        status: "QUEUED",
        idempotencyKey: data.idempotencyKey,
        approvedRecipientCount: snapshots.length,
        usesCustomRole: snapshots.some(
          (s) => !isCanonicalRole(s.recipientRole),
        ),
        usesRepeatSend: data.resendIds.some((id) =>
          selected.some((c) => c.id === id),
        ),
        attachmentId: attachment?.id,
        sends: { create: snapshots },
      },
    });
    await reserveUsage(
      owner,
      periods,
      snapshots.map((s) => ({ sendId: s.id, deliveryKey: s.id })),
      control!.paidGatingEnabled,
    );
    return {
      id: campaign.id,
      count: selected.length,
      skipped: contacts.length - selected.length,
    };
  });
}

import "server-only";
import { db } from "@/lib/db";
import { lockUsageOwner, releaseUsage } from "@/lib/usage-ledger";
import type { Prisma } from "@/generated/prisma/client";

export async function completeCampaignIn(
  tx: Prisma.TransactionClient,
  userId: string,
  campaignId: string,
) {
  const rows = await tx.send.findMany({
    where: { campaignId, campaign: { userId } },
    select: { status: true },
  });
  if (!rows.length) return;
  const status = rows.some((s) => s.status === "QUEUED")
    ? "SENDING"
    : rows.some((s) => s.status === "FAILED")
      ? "COMPLETED_WITH_ERRORS"
      : rows.some((s) => s.status === "CANCELLED")
        ? "COMPLETED_WITH_CANCELLATIONS"
        : "COMPLETED";
  await tx.campaign.updateMany({
    where: { id: campaignId, userId },
    data: { status },
  });
}

// Caller holds the user row lock, shared with delivery claims and account deletion.
export async function cancelQueuedIn(
  tx: Prisma.TransactionClient,
  userId: string,
  target: {
    sendId?: string;
    campaignId?: string;
    recipientEmail?: string;
  } = {},
) {
  const where: Prisma.SendWhereInput = {
    campaign: { userId },
    // Account deletion only needs outstanding work, not years of sent history.
    ...(!target.sendId && !target.campaignId && !target.recipientEmail
      ? {
          OR: [
            { status: "QUEUED" as const },
            {
              deliveryState: {
                in: ["ATTEMPTING" as const, "UNCERTAIN" as const],
              },
            },
          ],
        }
      : {}),
    ...(target.recipientEmail
      ? {
          recipientEmail: {
            equals: target.recipientEmail,
            mode: "insensitive",
          },
        }
      : {}),
    ...(target.sendId ? { id: target.sendId } : {}),
    ...(target.campaignId ? { campaignId: target.campaignId } : {}),
  };
  const rows = await tx.send.findMany({
    where,
    select: {
      id: true,
      campaignId: true,
      status: true,
      deliveryState: true,
      attemptedAt: true,
    },
  });
  const owner = await lockUsageOwner(tx, userId);
  for (const row of rows) {
    if (
      row.status !== "QUEUED" ||
      row.deliveryState !== "READY" ||
      row.attemptedAt
    )
      continue;
    const reservation = await tx.usageReservation.findFirst({
      where: { userId, sendId: row.id },
      select: { deliveryKey: true },
    });
    if (reservation)
      await releaseUsage(owner, reservation.deliveryKey, {
        kind: "UNSUBMITTED",
      });
  }
  const eligible = rows.filter(
    (r) =>
      r.status === "QUEUED" && r.deliveryState === "READY" && !r.attemptedAt,
  ).length;
  await tx.send.updateMany({
    where: {
      ...where,
      status: "QUEUED",
      deliveryState: "READY",
      attemptedAt: null,
    },
    data: {
      status: "CANCELLED",
      deliveryState: "DONE",
      cancelledAt: new Date(),
      error: null,
    },
  });
  for (const id of new Set(rows.map((s) => s.campaignId)))
    await completeCampaignIn(tx, userId, id);
  return {
    cancelled: eligible,
    couldNotStop: rows.filter(
      (s) =>
        s.status !== "CANCELLED" &&
        !(
          s.status === "QUEUED" &&
          s.deliveryState === "READY" &&
          !s.attemptedAt
        ),
    ).length,
  };
}
export async function cancelQueued(
  userId: string,
  target: { sendId?: string; campaignId?: string; recipientEmail?: string },
) {
  return db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    return cancelQueuedIn(tx, userId, target);
  });
}

import "server-only";

// No token scope or environment flag can enable mailbox access in send-only v1.
export function canReadGmail() {
  return false;
}
type ActiveUser = { id: string; deletionRequestedAt?: Date | null };
export function canMarkReplied(
  user: ActiveUser,
  access?: { features: { markReplied: boolean } },
) {
  return (
    !!user.id &&
    !user.deletionRequestedAt &&
    access?.features.markReplied === true
  );
}
export function needsSendOnlyReconnect(user: {
  gmailSendOnlyConsentAt: Date | null;
  gmailScopes: string[];
}) {
  return (
    !user.gmailSendOnlyConsentAt ||
    user.gmailScopes.some(
      (scope) =>
        (scope.startsWith("https://www.googleapis.com/auth/gmail.") ||
          scope === "https://mail.google.com/") &&
        scope !== "https://www.googleapis.com/auth/gmail.send",
    )
  );
}

/** A suggestion for the single-contact form, independent of CSV parsing. */
export function suggestNameFromEmail(email: string): string {
  return email
    .trim()
    .split("@")[0]
    .replace(/[._-]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(" ");
}

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const FAILURE = "TOKEN_ENCRYPTION_FAILED";
const uuid =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const keyIdPattern = /^[A-Za-z0-9_-]{1,64}$/;
function parseKey(value: unknown) {
  if (typeof value !== "string" || !/^[a-f\d]{64}$/i.test(value))
    throw new Error(FAILURE);
  return Buffer.from(value, "hex");
}
export function tokenKeyring() {
  try {
    const activeId = process.env.TOKEN_ENCRYPTION_ACTIVE_KEY_ID;
    if (!activeId || !keyIdPattern.test(activeId)) throw new Error();
    const activeKey = parseKey(process.env.TOKEN_ENCRYPTION_ACTIVE_KEY);
    const previous: unknown = JSON.parse(
      process.env.TOKEN_ENCRYPTION_PREVIOUS_KEYS_JSON ?? "{}",
    );
    if (!previous || typeof previous !== "object" || Array.isArray(previous))
      throw new Error();
    const keys = new Map<string, Buffer>([[activeId, activeKey]]);
    for (const [id, key] of Object.entries(previous)) {
      if (!keyIdPattern.test(id) || keys.has(id)) throw new Error();
      keys.set(id, parseKey(key));
    }
    return { activeId, activeKey, keys };
  } catch {
    throw new Error(FAILURE);
  }
}
function aad(ownerId: string, keyId: string) {
  if (!uuid.test(ownerId)) throw new Error(FAILURE);
  return Buffer.from(
    JSON.stringify(["v2", keyId, "gmail-refresh-token", ownerId.toLowerCase()]),
  );
}
function decode(value: string, size?: number) {
  if (!/^[A-Za-z0-9_-]+$/.test(value)) throw new Error(FAILURE);
  const bytes = Buffer.from(value, "base64url");
  if (
    bytes.toString("base64url") !== value ||
    (size !== undefined && bytes.length !== size)
  )
    throw new Error(FAILURE);
  return bytes;
}
export function encryptToken(value: string, ownerId: string) {
  try {
    if (!value || value.length > 16384) throw new Error();
    const { activeId, activeKey } = tokenKeyring();
    const iv = randomBytes(12);
    const cipher = createCipheriv("aes-256-gcm", activeKey, iv);
    cipher.setAAD(aad(ownerId, activeId));
    const encrypted = Buffer.concat([
      cipher.update(value, "utf8"),
      cipher.final(),
    ]);
    return [
      "v2",
      activeId,
      iv.toString("base64url"),
      cipher.getAuthTag().toString("base64url"),
      encrypted.toString("base64url"),
    ].join(".");
  } catch {
    throw new Error(FAILURE);
  }
}
export function decryptToken(value: string, ownerId: string) {
  try {
    if (!uuid.test(ownerId) || value.length > 24000) throw new Error();
    const parts = value.split(".");
    const version = parts[0];
    let key: Buffer, iv: string, tag: string, encrypted: string;
    if (version === "v1" && parts.length === 4) {
      key = parseKey(process.env.TOKEN_ENCRYPTION_KEY);
      [, iv, tag, encrypted] = parts;
    } else if (version === "v2" && parts.length === 5) {
      const keyId = parts[1];
      const found = tokenKeyring().keys.get(keyId);
      if (!found) throw new Error();
      key = found;
      [, , iv, tag, encrypted] = parts;
    } else throw new Error();
    const decipher = createDecipheriv("aes-256-gcm", key, decode(iv, 12));
    if (version === "v2") decipher.setAAD(aad(ownerId, parts[1]));
    decipher.setAuthTag(decode(tag, 16));
    return Buffer.concat([
      decipher.update(decode(encrypted)),
      decipher.final(),
    ]).toString("utf8");
  } catch {
    throw new Error(FAILURE);
  }
}
export function tokenUsesActiveKey(value: string) {
  return value.startsWith(`v2.${tokenKeyring().activeId}.`);
}

