"use server";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/session";
import { clearCompletedHistory } from "@/lib/history";
import { AppError, type ActionResult } from "@/lib/errors";

export async function deleteHistory(): Promise<
  ActionResult & { cleared?: number }
> {
  const user = await requireUser();
  let cleared: number;
  try {
    cleared = await clearCompletedHistory(user.id);
  } catch (error) {
    return {
      ok: false,
      message:
        error instanceof AppError
          ? error.message
          : "Could not delete history. Please try again.",
    };
  }
  for (const path of ["/settings", "/history", "/compose", "/contacts"])
    revalidatePath(path);
  return {
    ok: true,
    cleared,
    message: cleared
      ? "Completed history deleted."
      : "No completed history to delete.",
  };
}

import "server-only";
import { db } from "@/lib/db";
import { AppError } from "@/lib/errors";

import { lockUsageOwner, repairUsageCounters } from "@/lib/usage-ledger";
import { preserveAcceptedSend } from "@/lib/usage-backfill";

export async function clearCompletedHistory(userId: string) {
  return db.$transaction(
    async (tx) => {
      // Serialize with delivery claims, new campaigns, and account deletion.
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
      const owner = await lockUsageOwner(tx, userId);
      // Acquire bucket locks before locking or deleting Send rows.
      await repairUsageCounters(owner);
      const user = await tx.user.findFirst({
        where: { id: userId, deletionRequestedAt: null },
        select: { id: true },
      });
      if (!user) throw new AppError("Account unavailable.");
      // Lock eligible rows while transferring quota and duplicate evidence.
      // A delivery resolving concurrently is either included or left for next time.
      const completed = await tx.$queryRaw<
        {
          id: string;
          recipientEmail: string;
          createdAt: Date;
          sentAt: Date | null;
          status: string;
        }[]
      >`
        SELECT s.id, s."recipientEmail", s."createdAt", s."sentAt", s.status
        FROM "Send" s JOIN "Campaign" c ON c.id = s."campaignId"
        WHERE c."userId" = ${userId} AND s.status IN ('SENT', 'REPLIED', 'FAILED', 'CANCELLED')
          AND s."deliveryState" NOT IN ('ATTEMPTING', 'UNCERTAIN')
        FOR UPDATE OF s`;
      const receipts = completed.filter(
        (s) => (s.status === "SENT" || s.status === "REPLIED") && s.sentAt,
      );
      const receiptRows = [];
      for (const send of receipts) {
        const deliveryKey = await preserveAcceptedSend(owner, send.id);
        receiptRows.push({
          userId,
          recipientEmail: send.recipientEmail,
          createdAt: send.createdAt,
          sentAt: send.sentAt!,
          deliveryKey,
        });
      }
      if (receiptRows.length)
        await tx.deliveryReceipt.createMany({
          data: receiptRows,
          skipDuplicates: true,
        });
      // Active campaigns still need their original size and role snapshots for
      // downgrade checks. Hide and redact completed rows until the campaign is
      // terminal, preserving only the policy/delivery evidence already retained.
      const activeCampaigns = await tx.campaign.findMany({
        where: {
          userId,
          sends: {
            some: {
              OR: [
                { status: "QUEUED" },
                { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
              ],
            },
          },
        },
        select: { id: true },
      });
      const activeIds = activeCampaigns.map((campaign) => campaign.id);
      const retained = await tx.send.updateMany({
        where: {
          id: { in: completed.map((send) => send.id) },
          campaign: { userId },
          campaignId: { in: activeIds },
          historyDeletedAt: null,
        },
        data: {
          historyDeletedAt: new Date(),
          subject: "",
          body: "",
          recipientName: "",
          recipientCompany: "",
          templateName: "",
        },
      });
      const cleared = await tx.send.deleteMany({
        where: {
          id: { in: completed.map((s) => s.id) },
          campaign: { userId },
          campaignId: { notIn: activeIds },
        },
      });
      // Retain campaign keys so replaying an old submission cannot send again.
      await tx.campaign.updateMany({
        where: { userId, sends: { none: {} } },
        data: { role: "", attachmentId: null },
      });
      return cleared.count + retained.count;
    },
    { timeout: 10000 },
  );
}

import Papa from "papaparse";
import { contactSchema } from "@/lib/validation";
const generic = new Set(
  "careers career jobs job hiring hr hello info contact support admin office team sales recruitment recruiting noreply no-reply mail email enquiries help talent resume resumes apply recruitment notifications webmaster billing accounts service marketing press".split(
    " ",
  ),
);
export function suggestName(email: string): string {
  const local = email.trim().split("@")[0].split("+")[0].toLowerCase();
  const first = local.split(/[._-]/)[0].replace(/\d+$/, "");
  if (!/^[a-z]{2,30}$/.test(first) || generic.has(first)) return "";
  return first[0].toUpperCase() + first.slice(1);
}
export type ImportRow = {
  row: number;
  name: string;
  email: string;
  company: string;
  jobRole: string;
  state: "valid" | "duplicate" | "invalid";
  error?: string;
};
export function validateImportRows(
  rows: Omit<ImportRow, "state">[],
  existingEmails: string[] = [],
): ImportRow[] {
  const seen = new Set(existingEmails.map((e) => e.trim().toLowerCase()));
  return rows.map((row) => {
    const email = row.email.trim().toLowerCase();
    const duplicate = seen.has(email);
    seen.add(email);
    const parsed = contactSchema.safeParse({ ...row, email });
    return {
      ...row,
      email,
      state: duplicate
        ? "duplicate"
        : parsed.success && !row.error
          ? "valid"
          : "invalid",
      error: duplicate
        ? undefined
        : (row.error ??
          (parsed.success ? undefined : parsed.error.issues[0].message)),
    };
  });
}
export function parseContacts(
  text: string,
  existingEmails: string[] = [],
  jobRole = "",
): ImportRow[] {
  if (text.length > 1024 * 1024)
    throw new Error("Import at most 1 MB at a time.");
  const csv =
    /^([^\n]*[,\t;])?email([,\t;]|\s*$)/i.test(text.trim().split("\n")[0]) ||
    /^name[,\t;]/i.test(text.trim());
  let rows: Omit<ImportRow, "state">[];
  if (csv) {
    rows = [];
    let tooManyRows = false;
    const result = Papa.parse<Record<string, string>>(text.trim(), {
      header: true,
      skipEmptyLines: "greedy",
      // Stream rows even without quoted fields instead of splitting the whole file.
      fastMode: false,
      transformHeader: (h) => h.trim().toLowerCase(),
      step: ({ data: r, errors }, parser) => {
        if (rows.length === 1000) {
          tooManyRows = true;
          parser.abort();
          return;
        }
        rows.push({
          row: rows.length + 2,
          email: r.email ?? "",
          name: r.name?.trim() || suggestName(r.email ?? ""),
          company: r.company ?? "",
          jobRole: r.jobrole || r.role || jobRole,
          error: errors.length ? "Check the number of columns." : undefined,
        });
      },
    });
    if (tooManyRows) throw new Error("Import at most 1,000 rows at a time.");
    if (!result.meta.fields?.includes("email"))
      throw new Error("Include an email column header.");
  } else {
    rows = [];
    for (const match of text.matchAll(/[^,;\n]+/g)) {
      const email = match[0].trim();
      if (!email) continue;
      if (rows.length === 1000)
        throw new Error("Import at most 1,000 rows at a time.");
      rows.push({
        row: rows.length + 1,
        email,
        name: suggestName(email),
        company: "",
        jobRole,
      });
    }
  }
  return validateImportRows(rows, existingEmails);
}

import { safeSdkLogger, safeWorkerError } from "@/lib/observability";
import "server-only";
import { Inngest, Middleware } from "inngest";

// Normalize errors before step/function results enter failure telemetry. Inngest
// uses pending promises for step discovery, so normal control flow is preserved.
export class SafeTelemetry extends Middleware.BaseMiddleware {
  readonly id = "safe-telemetry";
  async wrapStepHandler({ next }: Middleware.WrapStepHandlerArgs) {
    try {
      return await next();
    } catch {
      throw safeWorkerError();
    }
  }
  async wrapFunctionHandler({ next }: Middleware.WrapFunctionHandlerArgs) {
    try {
      return await next();
    } catch {
      throw safeWorkerError();
    }
  }
}
export const inngest = new Inngest({
  id: "mailloop",
  logger: safeSdkLogger,
  middleware: [SafeTelemetry],
  isDev:
    process.env.NODE_ENV !== "production" && process.env.INNGEST_DEV === "1",
});

