// Discovery reads only cleanup controls; every attachment query remains user-scoped.
// Pagination stays inside one durable step, including when every account is idle.
export async function discoverAccountMaintenance() {
  const eligible: string[] = [];
  let cursor: string | undefined;
  for (;;) {
    const users = await db.user.findMany({
      where: cursor ? { id: { gt: cursor } } : {},
      select: {
        id: true,
        deletionRequestedAt: true,
        currentAttachmentId: true,
      },
      orderBy: { id: "asc" },
      take: 100,
    });
    if (!users.length) break;
    for (const user of users) {
      if (user.deletionRequestedAt) continue;
      if (
        await hasPendingAttachmentCleanup(user.id, user.currentAttachmentId)
      ) {
        eligible.push(user.id);
      }
    }
    cursor = users.at(-1)!.id;
  }
  return eligible;
}

export const maintenance = inngest.createFunction(
  { id: "maintenance", triggers: { cron: "0 3 * * *" }, concurrency: 1 },
  async ({ step }) => {
    const ids = await step.run("discover-cleanup", () =>
      discoverAccountMaintenance(),
    );
    for (let offset = 0; offset < ids.length; offset += 100) {
      await step.sendEvent(
        `cleanup-${offset / 100}`,
        ids.slice(offset, offset + 100).map((userId) => ({
          name: "mailloop/account.maintenance",
          data: { userId },
        })),
      );
    }
  },
);
export const accountMaintenance = inngest.createFunction(
  {
    id: "account-maintenance",
    triggers: { event: "mailloop/account.maintenance" },
    concurrency: { limit: 1, key: "event.data.userId" },
  },
  async ({ event, step }) => {
    const { userId } = z.object({ userId: z.uuid() }).parse(event.data);
    const user = await step.run("account", () =>
      db.user.findUnique({
        where: { id: userId },
        select: { deletionRequestedAt: true },
      }),
    );
    if (!user) return;
    // Ignore stale events for deleted owners; the daily deletion job owns cleanup.
    if (user.deletionRequestedAt) return;
    await step.run("cleanup-attachments", () => cleanupAttachments(userId));
  },
);

"use server";
import { z } from "zod";
import { revalidatePath } from "next/cache";
import { requireUser } from "@/lib/session";
import { cancelQueued } from "@/lib/cancellation";
import { requestAccountDeletion } from "@/lib/account";
import { cleanupAttachments } from "@/lib/storage";
import { db } from "@/lib/db";
import { requireEntitlement } from "@/lib/entitlements";
import { actionErrorDetails, type ActionResult } from "@/lib/errors";
import { AppError } from "@/lib/errors";

export async function cancelEmails(target: {
  sendId?: string;
  campaignId?: string;
}) {
  const user = await requireUser();
  const data = z
    .object({ sendId: z.uuid().optional(), campaignId: z.uuid().optional() })
    .refine((t) => !!t.sendId !== !!t.campaignId)
    .parse(target);
  const counts = await cancelQueued(user.id, data);
  await cleanupAttachments(user.id).catch(() => {});
  revalidatePath("/history");
  revalidatePath("/compose");
  return {
    ok: true,
    ...counts,
    message: `${counts.cancelled} cancelled. ${counts.couldNotStop} could not be stopped (already sent, sending, or needing review).`,
  };
}
export async function deleteAccount(email: string) {
  const user = await requireUser();
  try {
    await requestAccountDeletion(user.id, z.string().max(320).parse(email));
  } catch (e) {
    return {
      ok: false,
      message:
        e instanceof AppError
          ? e.message
          : "Could not request deletion. Try again.",
    };
  }
  return { ok: true, message: "Deletion requested." };
}
export async function saveFollowUpDays(days: number): Promise<ActionResult> {
  const user = await requireUser();
  try {
    await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${user.id} FOR UPDATE`;
      const value = z
        .union([z.literal(0), z.literal(3), z.literal(7), z.literal(14)])
        .parse(days);
      const active = await tx.user.findFirst({
        where: { id: user.id, deletionRequestedAt: null },
        select: { id: true },
      });
      if (!active) throw new AppError("Account unavailable.");
      if (value) await requireEntitlement(user.id, "followUpReminders", tx);
      await tx.user.update({
        where: { id: user.id },
        data: { followUpDays: value },
      });
    });
    revalidatePath("/settings");
    revalidatePath("/history");
    return { ok: true, message: "Reminder preference saved." };
  } catch (error) {
    return {
      ok: false,
      message:
        error instanceof AppError
          ? error.message
          : "Choose Off, 3, 7, or 14 days.",
      ...(error instanceof AppError ? actionErrorDetails(error) : {}),
    };
  }
}

import "server-only";
import { db } from "@/lib/db";
import { inngest } from "@/lib/inngest-client";
import {
  expireDeletionCredentials,
  prepareDeletionJob,
  runDeletionJob,
} from "@/lib/deletion-jobs";

export const deletionJobSweep = inngest.createFunction(
  {
    id: "account-deletion-jobs",
    triggers: { cron: "0 2 * * *" },
    concurrency: 1,
  },
  async ({ step }) => {
    await step.run("expire-credentials", () => expireDeletionCredentials());
    // Prepare legacy requests first; only the job scan publishes work, once per owner.
    let cursor: string | undefined;
    for (let page = 0; ; page++) {
      const ids = await step.run(`legacy-${page}`, async () => {
        const rows = await db.user.findMany({
          where: {
            deletionRequestedAt: { not: null },
            ...(cursor ? { id: { gt: cursor } } : {}),
          },
          select: { id: true },
          orderBy: { id: "asc" },
          take: 50,
        });
        for (const { id } of rows) await prepareDeletionJob(id);
        return rows;
      });
      if (ids.length < 50) break;
      cursor = ids.at(-1)!.id;
    }
    cursor = undefined;
    for (let page = 0; ; page++) {
      const jobs = await step.run(`jobs-${page}`, () =>
        db.accountDeletionJob.findMany({
          where: {
            completedAt: null,
            nextAttemptAt: { lte: new Date() },
            ...(cursor ? { id: { gt: cursor } } : {}),
          },
          select: { id: true, userId: true },
          orderBy: { id: "asc" },
          take: 50,
        }),
      );
      if (jobs.length)
        await step.sendEvent(
          `dispatch-${page}`,
          jobs.map(({ userId }) => ({
            name: "mailloop/account.deletion",
            data: { userId },
          })),
        );
      if (jobs.length < 50) break;
      cursor = jobs.at(-1)!.id;
    }
  },
);

import { z } from "zod";
export const deletionJobWorker = inngest.createFunction(
  {
    id: "account-deletion-worker",
    triggers: { event: "mailloop/account.deletion" },
