export type PriceSearchParams = Promise<{
  country?: string | string[];
}>;

export async function localizedPrice(searchParams: PriceSearchParams) {
  const requestHeaders = await headers();
  const countryHeader =
    requestHeaders.get("x-vercel-ip-country") ??
    requestHeaders.get("cf-ipcountry");
  const override =
    countryHeader === null && process.env.NODE_ENV === "development"
      ? (await searchParams).country
      : undefined;
  const country = (
    countryHeader ?? (typeof override === "string" ? override : "")
  )
    .trim()
    .toUpperCase();
  return country === "IN" ? PRICE_CONFIG.IN : PRICE_CONFIG.DEFAULT;
}

export type MessageText = { text: string; start: number };
export type MessageBlock =
  | ({ kind: "text" } & MessageText)
  | { kind: "ul" | "ol"; number: number; items: MessageText[] };

/** A small, shared formatting subset: bold, bullets, and numbered lists. */
export function messageBlocks(body: string): MessageBlock[] {
  const blocks: MessageBlock[] = [];
  let offset = 0;
  for (const line of body.split(/\r\n|\r|\n/)) {
    const bullet = /^\s*(?:[-*] |(\d+)\. )(.+)$/.exec(line);
    const previous = blocks.at(-1);
    if (bullet) {
      const kind = bullet[1] ? "ol" : "ul";
      const item = {
        text: bullet[2],
        start: offset + line.length - bullet[2].length,
      };
      if (previous?.kind === kind) previous.items.push(item);
      else blocks.push({ kind, number: Number(bullet[1] ?? 1), items: [item] });
    } else if (previous?.kind === "text") {
      previous.text = body.slice(previous.start, offset + line.length);
    } else blocks.push({ kind: "text", text: line, start: offset });
    const newline =
      body.slice(offset + line.length).match(/^(\r\n|\r|\n)/)?.[0] ?? "";
    offset += line.length + newline.length;
  }
  return blocks;
}

export function messageInline({ text, start }: MessageText) {
  const fragments: (MessageText & { bold: boolean })[] = [];
  let cursor = 0;
  for (const match of text.matchAll(/\*\*([^\r\n]+?)\*\*/g)) {
    if (match.index > cursor)
      fragments.push({
        text: text.slice(cursor, match.index),
        start: start + cursor,
        bold: false,
      });
    fragments.push({
      text: match[1],
      start: start + match.index + 2,
      bold: true,
    });
    cursor = match.index + match[0].length;
  }
  if (cursor < text.length)
    fragments.push({
      text: text.slice(cursor),
      start: start + cursor,
      bold: false,
    });
  return fragments;
}

import "server-only";
import { z } from "zod";
const id = z.uuid();
const count = z.number().int().min(0).max(1_000_000_000);
export const usageCodes = [
  "SETTLEMENT_FAILED",
  "UNCERTAIN",
  "PREPARATION_DEFERRED",
  "WORKER_FAILED",
  "PUBLICATION_DELAY",
  "PUBLICATION_FAILED",
  "COUNTER_DRIFT",
  "MISSING_ACCOUNTING",
  "UNCERTAINTY_OLDER_THAN_15_MINUTES",
  "OUTSTANDING_ORPHAN",
  "REPAIR_FAILED",
] as const;
const schemas = {
  auth: z.object({ code: z.enum(["AUTH_FAILED", "AUTH_WARNING"]) }),
  usage: z.object({
    code: z.enum(usageCodes),
    userId: id,
    sendId: id.optional(),
  }),
  gmail: z.object({
    category: z.enum([
      "LOCAL_PERMANENT",
      "RECONNECT_REQUIRED",
      "UNAUTHORIZED",
      "OWNER_THROTTLE",
      "PROVIDER_DAILY_LIMIT",
      "PROJECT_DAILY_LIMIT",
      "DOMAIN_POLICY",
      "MESSAGE_REJECTED",
      "PREPARATION_TRANSIENT",
      "UNCERTAIN",
    ]),
    status: z.number().int().min(0).max(599),
  }),
  webhook: z.object({
    code: z.enum([
      "WEBHOOK_ID_CONFLICT",
      "WEBHOOK_FAILED",
      "WEBHOOK_QUARANTINED",
    ]),
    receiptId: id,
  }),
  billing: z.object({
    code: z.literal("BILLING_RECONCILIATION_FAILED"),
    subscriptionRecordId: id,
  }),
  nightly: z.object({
    scanned: count,
    failed: count,
    missingSettlement: count,
    quarantined: count,
    staleInbox: count,
    conflictingSubscriptions: count,
    complete: z.boolean(),
  }),
  lifecycle: z.object({ code: z.literal("OWNER_RETRY_PENDING"), count }),
  worker: z.object({
    code: z.enum(["WORKER_FAILURE", "SDK_DIAGNOSTIC"]),
  }),
} as const;
export type OperationalEvent = keyof typeof schemas;
// Input is unknown even to typed callers. Schemas strip extra keys and validate
// values (a token under an allowed key is still rejected). No Error serialization.
export function safeLog(
  level: "debug" | "info" | "warn" | "error",
  event: OperationalEvent,
  input: unknown,
) {
  if (!Object.hasOwn(schemas, event)) return;
  const result = schemas[event].safeParse(input);
  if (!result.success) return;
  const payload = { event, ...result.data };
  console[level](JSON.stringify(payload));
}
export function safeWorkerError() {
  const error = new Error("WORKER_FAILURE");
  error.stack = "Error: WORKER_FAILURE";
  return error;
}
// SDK log arguments can include full HTTP requests and nested errors. Discard all
// arguments; SDK diagnostics retain only the fixed event and level.
export const safeSdkLogger = {
  debug: () => safeLog("debug", "worker", { code: "SDK_DIAGNOSTIC" }),
  info: () => safeLog("info", "worker", { code: "SDK_DIAGNOSTIC" }),
  warn: () => safeLog("warn", "worker", { code: "SDK_DIAGNOSTIC" }),
  error: () => safeLog("error", "worker", { code: "SDK_DIAGNOSTIC" }),
};

export function pageNumber(value?: string) {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? Math.min(n, 100000) : 1;
}

