import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import type { ClientEntitlements } from "@/lib/entitlements";
// JSON-safe contract shared by server reporting and advisory client displays.
export type QuotaAllowance = {
  sent: number;
  reserved: number;
  used: number;
  limit: number;
  remaining: number;
  startsAt: string | null;
  endsAt: string | null;
  resetsAt: string | null;
};
export type QuotaSnapshot = {
  notices?: {
    id: string;
    campaignIdSnapshot: string;
    reasonCode: string;
    cancelledCount: number;
    createdAt: string;
  }[];
  accessVersion?: string;
} & (
  | { mode: "legacy"; used: number; limit: typeof DAILY_EMAIL_LIMIT }
  | {
      mode: "gated";
      entitlements: ClientEntitlements;
      used: number;
      limit: number;
      plan: "FREE" | "PAID";
      daily: QuotaAllowance;
      monthly: QuotaAllowance;
      sendingAllowed: boolean;
      pauseReason: string | null;
    }
);

import { createHash } from "node:crypto";
import { readAccountNotices } from "@/lib/account-notices";
import { applyFreeCampaignPolicy } from "@/lib/campaign-policy";
import { DAILY_EMAIL_LIMIT } from "@/lib/email-limits";
import "server-only";
import { cache } from "react";
import { db } from "@/lib/db";
import { countQuotaUsage } from "@/lib/delivery-usage";
import {
  canUser,
  getEffectivePlan,
  getClientEntitlements,
} from "@/lib/entitlements";
import {
  ensureUsagePeriods,
  requireUsageReady,
  UsageNotReadyError,
  withUsageTransaction,
} from "@/lib/usage-ledger";
import {
  resolveUsagePeriods,
  historicalUsagePeriods,
  UsagePeriodError,
  type UsagePeriodSpec,
} from "@/lib/usage-periods";
import { PLANS } from "@/lib/plans";
import type { UsagePeriod } from "@/generated/prisma/client";
import type { QuotaAllowance, QuotaSnapshot } from "@/lib/quota-snapshot";

function allowance(period: UsagePeriod, spec: UsagePeriodSpec): QuotaAllowance {
  const used = period.sent + period.reserved;
  return {
    sent: period.sent,
    reserved: period.reserved,
    used,
    limit: spec.limit,
    remaining: Math.max(0, spec.limit - used),
    startsAt: period.startsAt.toISOString(),
    endsAt: period.endsAt.toISOString(),
    resetsAt: period.operationalEndsAt.toISOString(),
  };
}

// Request-local cache is for display only. Authorizing writes always reloads
// controls and accounting inside its own owner-locked database transaction.
export const readQuotaSnapshot = cache(
  async (userId: string): Promise<QuotaSnapshot> =>
    withUsageTransaction(db, userId, async (owner) => {
      const { tx } = owner;
      const user = await tx.user.findFirstOrThrow({
        where: { id: userId, deletionRequestedAt: null },
      });
      const control = await tx.systemControl.findUniqueOrThrow({
        where: { key: "global" },
      });
      // Quota reads also enforce clock boundaries when a sweep is delayed.
      let lifecyclePause: string | null = null;
      try {
        await applyFreeCampaignPolicy(owner);
      } catch (error) {
        if (!(error instanceof UsageNotReadyError)) throw error;
        lifecyclePause = error.message;
      }
      const access = getClientEntitlements(user, control);
      const lifecycle = {
        notices: await readAccountNotices(userId, tx),
        accessVersion: createHash("sha256")
          .update(JSON.stringify([user.billingStateVersion, access]))
          .digest("hex"),
      };
      if (!control.paidGatingEnabled)
        return {
          ...lifecycle,
          mode: "legacy",
          used: await countQuotaUsage(userId, tx),
          limit: DAILY_EMAIL_LIMIT,
        };
      const now = new Date(Date.now());
      let pauseReason: string | null = lifecyclePause;
      let billingUnresolved = false;
      try {
        await requireUsageReady(owner, true, now);
      } catch {
        pauseReason = "Usage accounting is being verified. Sending is paused.";
      }
      let specs;
      try {
        specs = resolveUsagePeriods(user, now);
      } catch (error) {
        if (!(error instanceof UsagePeriodError)) throw error;
        billingUnresolved = true;
        pauseReason = error.message;
        // Display the prior known provider allowance during an unresolved renewal,
        // without creating free credit. Sending remains paused until verified.
        if (
          !user.currentPeriodStart ||
          !user.currentPeriodEnd ||
          !user.dodoSubscriptionId
        ) {
          const day = historicalUsagePeriods(user, now).daily;
          const existing = await tx.usagePeriod.findFirst({
            where: { userId, key: day.key },
          });
          const daily: QuotaAllowance = {
            sent: existing?.sent ?? 0,
            reserved: existing?.reserved ?? 0,
            used: (existing?.sent ?? 0) + (existing?.reserved ?? 0),
            limit: PLANS.PAID.dailyEmails,
            remaining: 0,
            startsAt: day.startsAt.toISOString(),
            endsAt: day.endsAt.toISOString(),
            resetsAt: day.endsAt.toISOString(),
          };
          return {
            ...lifecycle,
            mode: "gated",
            entitlements: getClientEntitlements(user, control),
            used: daily.used,
            limit: daily.limit,
            plan: "PAID",
            daily,
            monthly: {
              sent: 0,
              reserved: 0,
              used: 0,
              limit: PLANS.PAID.monthlyEmails,
              remaining: 0,
              startsAt: null,
              endsAt: null,
              resetsAt: null,
            },
            sendingAllowed: false,
            pauseReason,
          };
        }
        const known = historicalUsagePeriods(user, user.currentPeriodStart);
        specs = { ...known, daily: historicalUsagePeriods(user, now).daily };
        specs.daily.limit = PLANS.PAID.dailyEmails;
        specs.monthly.limit = PLANS.PAID.monthlyEmails;
      }
      const periods = await ensureUsagePeriods(owner, specs);
      const sendAccess = canUser(user, "send", control, now);
      if (!sendAccess.allowed)
        pauseReason ??=
          sendAccess.reason === "SENDING_DISABLED"
            ? "Sending is temporarily paused."
            : sendAccess.reason === "ACCOUNT_SUSPENDED"
              ? "This account is suspended."
              : sendAccess.reason === "GMAIL_DOMAIN_POLICY"
                ? "Ask your workspace administrator to allow Mailloop, then reconnect Gmail."
                : sendAccess.reason === "GMAIL_PROVIDER_PAUSED"
                  ? "Gmail has paused sending. This is separate from your Mailloop allowance."
                  : "Reconnect Gmail in Settings before sending.";
      const daily = allowance(periods.daily, specs.daily),
        monthly = allowance(periods.monthly, specs.monthly);
      return {
        ...lifecycle,
        mode: "gated",
        entitlements: getClientEntitlements(user, control),
        used: daily.used,
        limit: daily.limit,
        plan: billingUnresolved ? "PAID" : getEffectivePlan(user, now),
        daily,
        monthly,
        sendingAllowed: !pauseReason,
        pauseReason,
      };
    }),
);

// Retained for callers that only need the top-level daily/legacy number.
export const readQuotaUsage = cache(
  async (userId: string) => (await readQuotaSnapshot(userId)).used,
);

import "server-only";
import { db } from "@/lib/db";
import { inngest } from "@/lib/inngest-client";

export async function cleanupExpiredRateLimits() {
  let deleted = 0;
  // Bound daily work to 10,000 rows. Locked budgets wait for a later pass.
  for (let batch = 0; batch < 20; batch++) {
    const count =
      await db.$executeRaw`DELETE FROM "RateLimitBucket" WHERE id IN (SELECT id FROM "RateLimitBucket" WHERE "cleanupAt"<clock_timestamp()-interval '1 day' ORDER BY "cleanupAt",id LIMIT 500 FOR UPDATE SKIP LOCKED)`;
    deleted += count;
    if (count < 500) break;
  }
  return { deleted };
}

export const rateLimitCleanup = inngest.createFunction(
  {
    id: "rate-limit-cleanup",
    triggers: { cron: "0 4 * * *" },
    concurrency: 1,
  },
  ({ step }) => step.run("cleanup-rate-buckets", cleanupExpiredRateLimits),
);

import "server-only";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import { db } from "@/lib/db";
import type { PrismaClient } from "@/generated/prisma/client";
import { AppError } from "@/lib/errors";

export const budgets = {
  checkout: { limit: 5, windowMs: 600_000 },
  billingManagement: { limit: 10, windowMs: 60_000 },
  status: { limit: 30, windowMs: 60_000 },
  campaign: { limit: 10, windowMs: 60_000 },
  csv: { limit: 5, windowMs: 3_600_000 },
  export: { limit: 2, windowMs: 3_600_000 },
  admin: { limit: 20, windowMs: 60_000 },
  systemActor: { limit: 5, windowMs: 60_000 },
  systemGlobal: { limit: 10, windowMs: 60_000 },
} as const;
export type Budget = keyof typeof budgets;
export class RateLimitError extends AppError {
  readonly code = "RATE_LIMITED";
  constructor(readonly retryAfter: number) {
    super("Too many requests. Try again after the indicated delay.");
  }
}
export class RateLimitUnavailable extends AppError {
  readonly code = "UNAVAILABLE";
  constructor() {
    super("This operation is temporarily unavailable. Try again shortly.");
  }
}
export function rollingAdmission(
  times: Date[],
  now: Date,
  budget: { limit: number; windowMs: number },
) {
  const recent = times
    .filter((t) => +t > +now - budget.windowMs)
    .sort((a, b) => +a - +b);
  if (recent.length >= budget.limit)
    return {
      admitted: false as const,
      times: recent.slice(-budget.limit),
      retryAfter: Math.max(
        1,
        Math.ceil(
          (+recent[recent.length - budget.limit] + budget.windowMs - +now) /
            1000,
        ),
      ),
    };
  return { admitted: true as const, times: [...recent, now], retryAfter: 0 };
}
// Call after authentication, before parsing or side effects. Never pass a business
// transaction: admissions must survive rollback of the requested operation.
export async function consumeBudgets(
  ownerId: string,
  operations: Budget[],
  client: PrismaClient = db,
) {
  if (!z.uuid().safeParse(ownerId).success) throw new RateLimitUnavailable();
  const entries = [...new Set(operations)]
    .map((operation) => ({
      operation,
      scope: operation === "systemGlobal" ? "global" : ownerId,
    }))
    .sort((a, b) =>
      `${a.scope}:${a.operation}`.localeCompare(`${b.scope}:${b.operation}`),
    );
  try {
    const denied = await client.$transaction(
      async (tx) => {
        for (const { scope, operation } of entries) {
          await tx.$executeRaw`INSERT INTO "RateLimitBucket" (id,scope,operation,admissions,"cleanupAt") VALUES (${randomUUID()}::uuid,${scope},${operation},ARRAY[]::timestamp[],clock_timestamp()) ON CONFLICT (scope,operation) DO NOTHING`;
          await tx.$queryRaw`SELECT id FROM "RateLimitBucket" WHERE scope=${scope} AND operation=${operation} FOR UPDATE`;
        }
        // Obtain time after all locks: waiting for a hot budget cannot admit using stale time.
        const [{ now }] = await tx.$queryRaw<
          { now: Date }[]
        >`SELECT clock_timestamp() AS now`;
        const updates = [];
        let retryAfter = 0;
        for (const { scope, operation } of entries) {
          const bucket = await tx.rateLimitBucket.findUniqueOrThrow({
            where: { scope_operation: { scope, operation } },
          });
          const result = rollingAdmission(
            bucket.admissions,
            now,
            budgets[operation],
          );
          if (!result.admitted)
            retryAfter = Math.max(retryAfter, result.retryAfter);
          updates.push({ scope, operation, result });
        }
        if (retryAfter) return retryAfter;
        for (const { scope, operation, result } of updates)
          await tx.rateLimitBucket.update({
            where: { scope_operation: { scope, operation } },
            data: {
              admissions: result.times,
              cleanupAt: new Date(+now + budgets[operation].windowMs),
            },
          });
        return 0;
      },
      { maxWait: 5000, timeout: 10000 },
    );
    if (denied) throw new RateLimitError(denied);
  } catch (error) {
    if (error instanceof RateLimitError) throw error;
    throw new RateLimitUnavailable();
  }
}
export function rateLimitHttpError(error: unknown) {
  if (!(
    error instanceof RateLimitError || error instanceof RateLimitUnavailable
  ))
    return null;
  return Response.json(
    { code: error.code, error: error.message },
    {
      status: error instanceof RateLimitError ? 429 : 503,
      headers: {
        "Cache-Control": "private, no-store",
        ...(error instanceof RateLimitError
          ? { "Retry-After": String(error.retryAfter) }
          : {}),
      },
    },
  );
}

"use server";
import { z } from "zod";
import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/session";
import { requireEntitlement } from "@/lib/entitlements";
import { actionErrorDetails } from "@/lib/errors";
import { AppError, type ActionResult } from "@/lib/errors";
import type { Prisma } from "@/generated/prisma/client";

async function mutate(
  id: string,
  work: (
    tx: Prisma.TransactionClient,
    userId: string,
    id: string,
  ) => Promise<string>,
): Promise<ActionResult> {
  const user = await requireUser();
  try {
    const parsed = z.uuid().parse(id);
    const message = await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${user.id} FOR UPDATE`;
      const active = await tx.user.findFirst({
        where: { id: user.id, deletionRequestedAt: null },
      });
      if (!active) throw new AppError("Account unavailable.");
      return work(tx, user.id, parsed);
    });
    for (const path of ["/history", "/contacts", "/compose"])
      revalidatePath(path);
    return { ok: true, message };
  } catch (error) {
    return {
      ok: false,
      ...(error instanceof AppError ? actionErrorDetails(error) : {}),
      message:
        error instanceof AppError
          ? error.message
          : "Could not save this change. Please try again.",
    };
  }
}
async function ownedSend(
  tx: Prisma.TransactionClient,
  userId: string,
  id: string,
) {
  const send = await tx.send.findFirst({
    where: { id, campaign: { userId }, historyDeletedAt: null },
  });
  if (!send) throw new AppError("Message not found.");
  return send;
}
export async function markReplied(id: string) {
  return mutate(id, async (tx, userId, sendId) => {
    await requireEntitlement(userId, "markReplied", tx);
    const send = await ownedSend(tx, userId, sendId);
    if (send.status !== "SENT" && send.status !== "REPLIED")
      throw new AppError("Only accepted messages can be marked replied.");
    await tx.send.updateMany({
      where: { id: sendId, campaign: { userId } },
      data: {
        status: "REPLIED",
        replyMarkedAt: send.replyMarkedAt ?? new Date(),
      },
    });
    await tx.contact.updateMany({
      where: { id: send.contactId, userId },
      data: { followUpRequestedAt: null },
    });
    return "Reply marked manually.";
  });
}

export async function undoReply(id: string) {
  return mutate(id, async (tx, userId, sendId) => {
    await requireEntitlement(userId, "markReplied", tx);
    const send = await ownedSend(tx, userId, sendId);
    if (send.status === "SENT") return "Reply mark already removed.";
    if (send.status !== "REPLIED")
      throw new AppError("Only replied messages can be undone.");
    await tx.send.updateMany({
      where: {
        id: sendId,
        campaign: { userId },
        historyDeletedAt: null,
        status: "REPLIED",
      },
      data: { status: "SENT", replyMarkedAt: null },
    });
    return "Reply mark removed.";
  });
}

