import "server-only";
import { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";

// Successful delivery history belongs to the exact address in the snapshot.
// Pending deliveries also guard the saved contact ID until they resolve.
export const contactDeliveryState = Prisma.sql`
  SELECT
    EXISTS(SELECT 1 FROM "Send" s JOIN "Campaign" b ON b.id = s."campaignId"
      WHERE b."userId" = c."userId" AND (s."contactId" = c.id OR s."recipientEmail" = c.email)
      AND (s.status = 'QUEUED' OR s."deliveryState" IN ('ATTEMPTING', 'UNCERTAIN'))) AS blocked,
    EXISTS(SELECT 1 FROM "Send" s JOIN "Campaign" b ON b.id = s."campaignId"
      WHERE b."userId" = c."userId" AND s."recipientEmail" = c.email
      AND s.status IN ('SENT', 'REPLIED')
      UNION ALL SELECT 1 FROM "DeliveryReceipt" r WHERE r."userId" = c."userId" AND r."recipientEmail" = c.email) AS "previouslySent",
    (c."followUpRequestedAt" IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM "Send" s JOIN "Campaign" b ON b.id = s."campaignId"
      WHERE b."userId" = c."userId" AND s."recipientEmail" = c.email
      AND s.status IN ('SENT', 'REPLIED') AND s."createdAt" > c."followUpRequestedAt"
      UNION ALL SELECT 1 FROM "DeliveryReceipt" r WHERE r."userId" = c."userId" AND r."recipientEmail" = c.email
        AND r."createdAt" > c."followUpRequestedAt")) AS "followUp",
    (SELECT max(delivery."sentAt") FROM (
      SELECT s."sentAt" FROM "Send" s JOIN "Campaign" b ON b.id = s."campaignId"
      WHERE b."userId" = c."userId" AND s."recipientEmail" = c.email AND s.status IN ('SENT', 'REPLIED')
      UNION ALL SELECT r."sentAt" FROM "DeliveryReceipt" r WHERE r."userId" = c."userId" AND r."recipientEmail" = c.email
    ) delivery) AS "lastSent"
`;
export type ShortlistContact = {
  id: string;
  name: string;
  email: string;
  company: string | null;
  jobRole: string | null;
  blocked: boolean;
  previouslySent: boolean;
  followUp: boolean;
  lastSent: Date | null;
};
export async function readShortlist(userId: string, q = "", page = 1) {
  // Literal search: %, _ and backslashes must not become LIKE patterns.
  const search = `%${q.replace(/[\\%_]/g, "\\$&")}%`;
  const where = Prisma.sql`c."userId" = ${userId} AND c."archivedAt" IS NULL AND c."shortlistRemovedAt" IS NULL
    AND (c.name ILIKE ${search} OR c.email ILIKE ${search} OR c.company ILIKE ${search})
    AND (state.blocked OR NOT state."previouslySent" OR state."followUp")`;
  const [contacts, counts] = await Promise.all([
    db.$queryRaw<ShortlistContact[]>(Prisma.sql`
      SELECT c.id, c.name, c.email, c.company, c."jobRole", state.*
      FROM "Contact" c CROSS JOIN LATERAL (${contactDeliveryState}) state
      WHERE ${where} ORDER BY c.name, c.id LIMIT 20 OFFSET ${(page - 1) * 20}`),
    db.$queryRaw<{ total: bigint }[]>(Prisma.sql`
      SELECT count(*) AS total FROM "Contact" c CROSS JOIN LATERAL (${contactDeliveryState}) state WHERE ${where}`),
  ]);
  return { contacts, total: Number(counts[0].total) };
}

// Contacts retain removed unsent people so they can be re-added, but completed
// recipients return when History or saving their email opens another follow-up.
export async function readContacts(userId: string, q = "", page = 1) {
  const search = `%${q.replace(/[\\%_]/g, "\\$&")}%`;
  const where = Prisma.sql`c."userId" = ${userId} AND c."archivedAt" IS NULL
    AND (c.name ILIKE ${search} OR c.email ILIKE ${search} OR c.company ILIKE ${search})
    AND (state.blocked OR NOT state."previouslySent" OR state."followUp")`;
  const [contacts, counts] = await Promise.all([
    db.$queryRaw<
      (ShortlistContact & { shortlistRemovedAt: Date | null })[]
    >(Prisma.sql`
      SELECT c.id, c.name, c.email, c.company, c."jobRole", c."shortlistRemovedAt", state.*
      FROM "Contact" c CROSS JOIN LATERAL (${contactDeliveryState}) state
      WHERE ${where} ORDER BY c."createdAt" DESC, c.id LIMIT 20 OFFSET ${(page - 1) * 20}`),
    db.$queryRaw<{ total: bigint }[]>(Prisma.sql`
      SELECT count(*) AS total FROM "Contact" c CROSS JOIN LATERAL (${contactDeliveryState}) state WHERE ${where}`),
  ]);
  return { contacts, total: Number(counts[0].total) };
}

import "server-only";
import { mkdir, readFile, writeFile, rm } from "node:fs/promises";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { get, del, list } from "@vercel/blob";
import { db } from "@/lib/db";
import type { Prisma } from "@/generated/prisma/client";
import { MAX_PDF_BYTES, validatePdf } from "@/lib/validation";
import { AppError } from "@/lib/errors";

export function hasBlobStorage() {
  return Boolean(
    process.env.BLOB_READ_WRITE_TOKEN ||
    (process.env.BLOB_STORE_ID && process.env.NODE_ENV === "production"),
  );
}

export function validStoragePath(userId: string, pathname: string) {
  return new RegExp(`^resumes/${userId}/[a-f0-9-]{36}\\.pdf$`).test(pathname);
}
export function safeFileName(value: string) {
  return (
    value.replace(/[\r\n\\/\x00-\x1f]/g, "_").slice(0, 150) || "resume.pdf"
  );
}
export async function readAttachment(userId: string, storagePath: string) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  if (!hasBlobStorage() && process.env.NODE_ENV !== "production") {
    try {
      return await readFile(path.join(process.cwd(), "uploads", storagePath));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT")
        throw new AppError(
          "PDF could not be loaded. Upload it again in Settings.",
        );
      throw error;
    }
  }
  const abortSignal = AbortSignal.timeout(30000);
  const blob = await get(storagePath, {
    access: "private",
    useCache: false,
    abortSignal,
  });
  if (!blob || blob.statusCode !== 200)
    throw new AppError("PDF could not be loaded. Upload it again in Settings.");
  const reader = blob.stream.getReader();
  abortSignal.addEventListener(
    "abort",
    () => {
      void reader.cancel().catch(() => {});
    },
    { once: true },
  );
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.length;
      if (size > MAX_PDF_BYTES) {
        await reader.cancel();
        throw new AppError("PDF exceeds 5 MB.");
      }
      abortSignal.throwIfAborted();
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  abortSignal.throwIfAborted();
  return Buffer.concat(chunks);
}
export async function activateResume(
  userId: string,
  storagePath: string,
  fileName: string,
) {
  try {
    const bytes = await readAttachment(userId, storagePath);
    validatePdf(bytes, "application/pdf");
    await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
      const user = await tx.user.findUnique({ where: { id: userId } });
      if (!user || user.deletionRequestedAt || user.isSuspended)
        throw new AppError("Account unavailable.");
      const existing = await tx.attachment.findFirst({
        where: { userId, storagePath },
      });
      if (existing?.deletedAt)
        throw new AppError("This PDF was removed. Upload it again.");
      const attachment =
        existing ??
        (await tx.attachment.create({
          data: { userId, storagePath, fileName: safeFileName(fileName) },
        }));
      await tx.user.update({
        where: { id: userId },
        data: { currentAttachmentId: attachment.id },
      });
    });
  } catch (error) {
    await discardUnactivatedResume(userId, storagePath);
    throw error;
  }
  await cleanupAttachments(userId);
}
// Retire the path under the same owner lock as activation. The tombstone closes
// the gap between a storage delete and a concurrent unsuspension/activation.
export async function discardUnactivatedResume(
  userId: string,
  storagePath: string,
  unavailableSince?: Date,
) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  const candidate = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const user = await tx.user.findUnique({
      where: { id: userId },
      select: { isSuspended: true, deletionRequestedAt: true },
    });
    if (!user) return { id: null };
    if (
      unavailableSince &&
      !user.isSuspended &&
      !(
        user.deletionRequestedAt && user.deletionRequestedAt <= unavailableSince
      )
    )
      return null;
    const existing = await tx.attachment.findFirst({
      where: { userId, storagePath },
      select: { id: true, rejectedAt: true },
    });
    if (existing) return existing.rejectedAt ? { id: existing.id } : null;
    // Deletion is irreversible; no tombstone is needed to block activation.
    if (user.deletionRequestedAt) return { id: null };
    return tx.attachment.create({
      data: {
        userId,
        storagePath,
        fileName: "resume.pdf",
        deletedAt: new Date(),
        rejectedAt: new Date(),
      },
      select: { id: true },
    });
  });
  if (!candidate) return;
  await deleteStoragePath(userId, storagePath);
  if (candidate.id)
    await db.attachment.updateMany({
      where: { id: candidate.id, userId, rejectedAt: { not: null } },
      data: { storageDeletedAt: new Date() },
    });
}
async function deleteStoragePath(userId: string, storagePath: string) {
  if (!validStoragePath(userId, storagePath))
    throw new AppError("Invalid attachment location.");
  if (hasBlobStorage())
    await del(storagePath, { abortSignal: AbortSignal.timeout(15000) });
  else if (process.env.NODE_ENV !== "production")
    await rm(path.join(process.cwd(), "uploads", storagePath), { force: true });
}
export async function storeLocalResume(userId: string, file: File) {
  if (process.env.NODE_ENV === "production" || hasBlobStorage())
    throw new AppError("Use the secure Blob upload.");
  if (file.size > MAX_PDF_BYTES) throw new AppError("Choose a PDF up to 5 MB.");
  const bytes = Buffer.from(await file.arrayBuffer());
  validatePdf(bytes, file.type);
  const storagePath = `resumes/${userId}/${randomUUID()}.pdf`;
  const full = path.join(process.cwd(), "uploads", storagePath);
  await mkdir(path.dirname(full), { recursive: true, mode: 0o700 });
  await writeFile(full, bytes, { mode: 0o600 });
  await activateResume(userId, storagePath, file.name);
}
function cleanupAttachmentWhere(
  userId: string,
  currentAttachmentId: string | null | undefined,
): Prisma.AttachmentWhereInput {
  return {
    userId,
    storageDeletedAt: null,
    ...(currentAttachmentId ? { id: { not: currentAttachmentId } } : {}),
    campaigns: {
      none: {
        userId,
        sends: {
          some: {
            OR: [
              { status: "QUEUED" },
              { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
            ],
          },
        },
      },
    },
  };
}

export async function hasPendingAttachmentCleanup(
  userId: string,
  currentAttachmentId: string | null,
) {
  return Boolean(
    await db.attachment.findFirst({
      where: cleanupAttachmentWhere(userId, currentAttachmentId),
      select: { id: true },
    }),
  );
}

export async function cleanupAttachments(userId: string) {
  const old = await db.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const user = await tx.user.findUnique({
      where: { id: userId },
      select: { currentAttachmentId: true },
    });
    const candidates = await tx.attachment.findMany({
      where: cleanupAttachmentWhere(userId, user?.currentAttachmentId),
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      take: 10,
    });
    await tx.attachment.updateMany({
      where: {
        userId,
        id: { in: candidates.map((f) => f.id) },
        deletedAt: null,
      },
      data: { deletedAt: new Date() },
    });
    return candidates;
  });
  const files = old.filter((file) =>
    validStoragePath(userId, file.storagePath),
  );
  if (!files.length) return;
  try {
    if (hasBlobStorage())
      await del(
        files.map((file) => file.storagePath),
        {
          abortSignal: AbortSignal.timeout(15000),
        },
      );
    else if (process.env.NODE_ENV !== "production")
      await Promise.all(
        files.map((file) =>
          rm(path.join(process.cwd(), "uploads", file.storagePath), {
            force: true,
          }),
        ),
      );
    else return;
    // Preserve historical rows, but never repeat completed physical deletions.
    await db.attachment.updateMany({
      where: {
        userId,
        id: { in: files.map((file) => file.id) },
        storageDeletedAt: null,
      },
      data: { storageDeletedAt: new Date() },
    });
  } catch {
    /* Unfinished storage work remains pending for the next cleanup job. */
  }
}

export async function deleteOwnedResumes(userId: string) {
  // UUID IDs are used as exact tenant prefixes; never accept arbitrary path input.
  if (!/^[a-f0-9-]{36}$/.test(userId)) throw new AppError("Invalid account.");
  if (hasBlobStorage()) {
    let cursor: string | undefined;
    do {
      const page = await list({
        prefix: `resumes/${userId}/`,
        limit: 100,
        cursor,
        abortSignal: AbortSignal.timeout(15000),
      });
      if (page.blobs.length)
        await del(
          page.blobs.map((blob) => blob.url),
          { abortSignal: AbortSignal.timeout(15000) },
        );
      cursor = page.hasMore ? page.cursor : undefined;
    } while (cursor);
  } else if (process.env.NODE_ENV === "production") {
    throw new AppError("Private Blob storage is not configured.");
  }
  await rm(path.join(process.cwd(), "uploads", "resumes", userId), {
    recursive: true,
    force: true,
  });
}

import "server-only";
import type { EntitlementUser } from "@/lib/entitlements";

/** Access resolution never rewrites a provider observation. All deadlines are
 * half-open. An ordinary renewal needs settlement or a signed grace deadline. */
export function resolveSubscriptionLifecycle(
  user: EntitlementUser & { cancelAtPeriodEnd?: boolean },
  now = new Date(Date.now()),
) {
  const start = user.currentPeriodStart,
    end = user.currentPeriodEnd;
  const valid = Boolean(
    user.dodoSubscriptionId && start && end && start < end && start <= now,
  );
  const terminal = ["CANCELLED", "EXPIRED", "FAILED"].includes(
    user.subscriptionStatus,
  );
  const grace =
    valid &&
    user.subscriptionStatus === "PAST_DUE" &&
    user.gracePeriodEnd &&
    user.gracePeriodEnd >= end!
      ? user.gracePeriodEnd
      : null;
  const scheduled = valid && user.cancelAtPeriodEnd;
  const deadline = scheduled ? end : (grace ?? (valid ? end : null));
  const paid =
    user.plan === "PAID" &&
    valid &&
    !(scheduled && now >= end!) &&
    ((user.subscriptionStatus === "ACTIVE" && now < end!) ||
      (grace && now < grace) ||
      (user.subscriptionStatus === "CANCELLED" && scheduled && now < end!));
  const unresolved =
    user.plan === "PAID" &&
    !paid &&
    !terminal &&
    !(scheduled && now >= end!) &&
    !(grace && now >= grace);
  return { paid: Boolean(paid), unresolved: Boolean(unresolved), deadline };
}

import "server-only";
import { safeLog } from "@/lib/observability";
import { db } from "@/lib/db";
import { applyFreeCampaignPolicy } from "@/lib/campaign-policy";
import { withUsageTransaction } from "@/lib/usage-ledger";

// Scheduled maintenance runs this each minute. Dispatch and claims also check access directly.
export async function sweepSubscriptionLifecycle() {
  let cursor: string | undefined;
  let failed = 0;
  for (;;) {
    const result = await sweepSubscriptionPage(cursor);
    failed += result.failed;
    cursor = result.cursor ?? undefined;
    if (!cursor) break;
  }
  if (failed) throw new Error("SUBSCRIPTION_LIFECYCLE_INCOMPLETE");
}

async function sweepSubscriptionPage(cursor: string | undefined) {
  const owners = await db.user.findMany({
    where: {
      deletionRequestedAt: null,
      ...(cursor ? { id: { gt: cursor } } : {}),
      campaigns: {
        some: {
          sends: { some: { status: "QUEUED", deliveryState: "READY" } },
        },
      },
    },
    select: { id: true },
    orderBy: { id: "asc" },
    take: 50,
  });
  let failed = 0;
  for (const owner of owners) {
    try {
      await withUsageTransaction(db, owner.id, (locked) =>
        applyFreeCampaignPolicy(locked),
      );
    } catch {
      failed++;
    }
  }
  const result = {
    cursor: owners.length === 50 ? owners.at(-1)!.id : null,
    failed,
  };
  if (failed)
    safeLog("error", "lifecycle", {
      code: "OWNER_RETRY_PENDING",
      count: failed,
    });
  return result;
}

import "server-only";
import type { Prisma } from "@/generated/prisma/client";
import { EntitlementError, readEntitlements } from "@/lib/entitlements";
import { AppError } from "@/lib/errors";

// Caller holds the User lock for writes. Reads resolve the same deterministic fallback.
export async function resolveFreeTemplate(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  const user = await tx.user.findUniqueOrThrow({
    where: { id: userId },
    select: { freeTemplateId: true },
  });
  const selected = user.freeTemplateId
    ? await tx.template.findFirst({
        where: { id: user.freeTemplateId, userId, archivedAt: null },
        select: { id: true },
      })
    : null;
  return (
    selected?.id ??
    (
      await tx.template.findFirst({
        where: { userId, archivedAt: null },
        orderBy: [{ createdAt: "asc" }, { id: "asc" }],
        select: { id: true },
      })
    )?.id ??
    null
  );
}
export async function maintainFreeTemplate(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  const id = await resolveFreeTemplate(tx, userId);
  await tx.user.update({ where: { id: userId }, data: { freeTemplateId: id } });
  return id;
}
export async function requireTemplateAccess(
  tx: Prisma.TransactionClient,
  userId: string,
  templateId?: string,
) {
  const access = await readEntitlements(userId, tx);
  if (!access.features.templateUse)
    throw new EntitlementError(access.reasons.templateUse!);
  if (
    templateId &&
    !(await tx.template.findFirst({
      where: { id: templateId, userId, archivedAt: null },
      select: { id: true },
    }))
  )
    throw new AppError("Template not found.");
  if (access.limits.savedTemplates === null) return;
  if (templateId) {
    if (templateId !== (await resolveFreeTemplate(tx, userId)))
      throw new EntitlementError("UPGRADE_REQUIRED");
  } else if (
    (await tx.template.count({ where: { userId, archivedAt: null } })) >=
    access.limits.savedTemplates
  )
    throw new EntitlementError("UPGRADE_REQUIRED");
}

