// One owner page includes its retained deletion job. Jobs outlive User, so use
// the union of owner IDs. Dry-run executes SELECTs and crypto only, no locks/writes.
export async function rotateTokenPage(
  options: { apply?: boolean; after?: string; take?: number } = {},
) {
  tokenKeyring();
  const after = options.after ? z.uuid().parse(options.after) : "";
  const take = Math.min(100, Math.max(1, options.take ?? 50));
  const owners = await db.$queryRaw<
    { id: string }[]
  >`SELECT id FROM (SELECT id FROM "User" WHERE "encryptedRefreshToken" IS NOT NULL UNION SELECT "userId" AS id FROM "AccountDeletionJob" WHERE "encryptedRevocationToken" IS NOT NULL AND "credentialExpiresAt">clock_timestamp()) owners WHERE id>${after} ORDER BY id LIMIT ${take}`;
  const counts = {
    scanned: 0,
    current: 0,
    eligible: 0,
    updated: 0,
    conflicts: 0,
    failed: 0,
  };
  for (const { id: ownerId } of owners) {
    const user = await db.user.findUnique({
      where: { id: ownerId },
      select: { encryptedRefreshToken: true, deletionRequestedAt: true },
    });
    const job = await db.accountDeletionJob.findUnique({
      where: { userId: ownerId },
      select: {
        id: true,
        encryptedRevocationToken: true,
        credentialExpiresAt: true,
      },
    });
    for (const kind of ["user", "job"] as const) {
      const value =
        kind === "user"
          ? user?.encryptedRefreshToken
          : job?.encryptedRevocationToken;
      if (!value || (kind === "job" && job!.credentialExpiresAt <= new Date()))
        continue;
      counts.scanned++;
      try {
        // Validate even current envelopes, including removed or misconfigured keys.
        const plaintext = decryptToken(value, ownerId);
        if (tokenUsesActiveKey(value)) {
          counts.current++;
          continue;
        }
        counts.eligible++;
        if (!options.apply) continue;
        const encrypted = encryptToken(plaintext, ownerId);
        const result =
          kind === "user"
            ? await db.user.updateMany({
                where: {
                  id: ownerId,
                  encryptedRefreshToken: value,
                  deletionRequestedAt: null,
                },
                data: { encryptedRefreshToken: encrypted },
              })
            : await db.accountDeletionJob.updateMany({
                where: {
                  userId: ownerId,
                  id: job!.id,
                  encryptedRevocationToken: value,
                  credentialExpiresAt: { gt: new Date() },
                  credentialErasedAt: null,
                },
                data: { encryptedRevocationToken: encrypted },
              });
        if (result.count) counts.updated++;
        else counts.conflicts++;
      } catch {
        counts.failed++;
      }
    }
  }
  return {
    ...counts,
    cursor: owners.length === take ? owners.at(-1)!.id : null,
  };
}

import "server-only";
import { db } from "@/lib/db";
import { countQuotaUsage } from "@/lib/delivery-usage";
import {
  historicalUsagePeriods,
  resolveUsagePeriods,
  UsagePeriodError,
} from "@/lib/usage-periods";
import {
  adoptUsageReservation,
  ensureUsagePeriods,
  importUsageEvidence,
  repairUsageCounters,
  settleUsageReceipt,
  USAGE_BACKFILL_VERSION,
  withUsageTransaction,
  type UsageOwnerTransaction,
} from "@/lib/usage-ledger";

/** Durable acceptance wins over stale worker state. History deletion and the
 * reconciler call the same primitive before discarding successful Send rows. */
export async function preserveAcceptedSend(
  owner: UsageOwnerTransaction,
  sendId: string,
) {
  const { tx, userId } = owner;
  const send = await tx.send.findFirstOrThrow({
    where: { id: sendId, campaign: { userId } },
  });
  if (
    !send.sentAt ||
    (!["SENT", "REPLIED"].includes(send.status) && !send.gmailMessageId)
  )
    throw new Error("Durable acceptance evidence required.");
  const reservation = await tx.usageReservation.findFirst({
    where: { userId, sendId },
  });
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  const chargedAt = reservation?.chargedAt ?? send.attemptedAt ?? send.sentAt;
  if (reservation) {
    await adoptUsageReservation(owner, {
      sendId,
      deliveryKey: reservation.deliveryKey,
      specs: historicalUsagePeriods(user, chargedAt),
      status: "CONFIRMED",
      chargedAt,
      confirmedAt: send.sentAt,
    });
  } else {
    const existing = await tx.usageImportEvidence.findFirst({
      where: { userId, deliveryKey: send.id },
    });
    if (!existing)
      await importUsageEvidence(owner, {
        sourceKey: `delivery:${send.id}`,
        deliveryKey: send.id,
        chargedAt,
        timestampSource: send.attemptedAt ? "attemptedAt" : "sentAt",
      });
  }
  if (
    !["SENT", "REPLIED"].includes(send.status) ||
    send.deliveryState !== "DONE"
  )
    await tx.send.updateMany({
      where: { id: sendId, campaign: { userId } },
      data: {
        status: "SENT",
        deliveryState: "DONE",
        claimToken: null,
        leaseExpiresAt: null,
        error: null,
      },
    });
  return reservation?.deliveryKey ?? send.id;
}

/** Independent SQL reconstruction, deliberately separate from counter updates. */
async function validateUsageOwner(owner: UsageOwnerTransaction) {
  const { tx, userId } = owner;
  const expected = await tx.$queryRaw<
    {
      id: string;
      sent: number;
      reserved: number;
      importedSent: number;
      importedReserved: number;
    }[]
  >`
    SELECT p.id,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status='CONFIRMED'
        AND ((p.kind='DAILY' AND r."dailyPeriodId"=p.id) OR (p.kind='MONTHLY' AND r."monthlyPeriodId"=p.id)
          OR (r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt")))
      + (SELECT count(*)::int FROM "UsageImportEvidence" e WHERE e."userId"=${userId}
        AND e."chargedAt">=p."startsAt" AND e."chargedAt"<p."operationalEndsAt"
        AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=e."deliveryKey")) AS sent,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status IN ('RESERVED','ATTEMPTING','UNCERTAIN')
        AND ((p.kind='DAILY' AND r."dailyPeriodId"=p.id) OR (p.kind='MONTHLY' AND r."monthlyPeriodId"=p.id)
          OR (r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt"))) AS reserved,
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status='CONFIRMED'
        AND (CASE WHEN p.kind='DAILY' THEN r."dailyPeriodId" ELSE r."monthlyPeriodId" END)<>p.id
        AND r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt")
      + (SELECT count(*)::int FROM "UsageImportEvidence" e WHERE e."userId"=${userId}
        AND e."chargedAt">=p."startsAt" AND e."chargedAt"<p."operationalEndsAt"
        AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=e."deliveryKey")) AS "importedSent",
      (SELECT count(*)::int FROM "UsageReservation" r WHERE r."userId"=${userId} AND r.status IN ('RESERVED','ATTEMPTING','UNCERTAIN')
        AND (CASE WHEN p.kind='DAILY' THEN r."dailyPeriodId" ELSE r."monthlyPeriodId" END)<>p.id
        AND r."chargedAt">=p."startsAt" AND r."chargedAt"<p."operationalEndsAt") AS "importedReserved"
    FROM "UsagePeriod" p WHERE p."userId"=${userId}`;
  const actual = await tx.usagePeriod.findMany({ where: { userId } });
  for (const row of expected) {
    const period = actual.find((p) => p.id === row.id)!;
    for (const key of [
      "sent",
      "reserved",
      "importedSent",
      "importedReserved",
    ] as const)
      if (row[key] !== period[key])
        throw new Error("Usage period validation failed.");
  }
  const missing = await tx.$queryRaw<{ id: string }[]>`
    SELECT s.id FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId" WHERE c."userId"=${userId}
    AND (s.status IN ('QUEUED','SENT','REPLIED') OR s."deliveryState" IN ('ATTEMPTING','UNCERTAIN'))
    AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."sendId"=s.id)
    AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=s.id)
    UNION ALL
    SELECT d.id FROM "DeliveryReceipt" d WHERE d."userId"=${userId}
    AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=d."deliveryKey")
    AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=d."deliveryKey")`;
  if (missing.length) throw new Error("Usage evidence validation failed.");
  return {
    periods: expected.length,
    legacyRollingUsed: await countQuotaUsage(userId, tx),
  };
}

export async function backfillUsageOwner(
  userId: string,
  cutover: Date,
  apply = false,
) {
  const dryRun = Symbol("dry-run");
  let result:
    | {
        ready: boolean;
        sends: number;
        receipts: number;
        periods: number;
        legacyRollingUsed: number;
      }
    | undefined;
  try {
    await withUsageTransaction(db, userId, async (owner) => {
      const { tx } = owner;
      if (apply) {
        const control = await tx.systemControl.findUniqueOrThrow({
          where: { key: "global" },
        });
        if (control.sendingEnabled)
          throw new Error("Pause sending before applying usage backfill.");
      }
      const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
      const originalCutover = user.usageCutoverAt ?? cutover;
      const sends = await tx.send.findMany({
        where: { campaign: { userId } },
        orderBy: { id: "asc" },
      });
      for (const send of sends) {
        if (
          send.sentAt &&
          (["SENT", "REPLIED"].includes(send.status) || send.gmailMessageId)
        ) {
          await preserveAcceptedSend(owner, send.id);
          continue;
        }
        if (
          send.status !== "QUEUED" &&
          !["ATTEMPTING", "UNCERTAIN"].includes(send.deliveryState)
        )
          continue;
        const uncertain =
          send.deliveryState !== "READY" || send.attemptedAt !== null;
        const at = uncertain
          ? (send.attemptedAt ?? send.createdAt)
          : originalCutover;
        await adoptUsageReservation(owner, {
          sendId: send.id,
          deliveryKey: send.id,
          specs: historicalUsagePeriods(user, at),
          status: uncertain ? "UNCERTAIN" : "RESERVED",
          chargedAt: uncertain ? at : null,
        });
        if (!uncertain && !send.queueExpiresAt)
          await tx.send.updateMany({
            where: { id: send.id, campaign: { userId }, queueExpiresAt: null },
            data: {
              queueExpiresAt: new Date(+originalCutover + 86400000),
              availableAt: send.availableAt ?? originalCutover,
            },
          });
      }
      const receipts = await tx.deliveryReceipt.findMany({ where: { userId } });
      for (const receipt of receipts) {
        const key = receipt.deliveryKey ?? receipt.id;
        const [ledger, evidence] = await Promise.all([
          tx.usageReservation.findFirst({
            where: { userId, deliveryKey: key },
          }),
          tx.usageImportEvidence.findFirst({
            where: { userId, deliveryKey: key },
          }),
        ]);
        if (ledger && ledger.status !== "CONFIRMED")
          await settleUsageReceipt(
            owner,
            receipt.id,
            historicalUsagePeriods(user, ledger.chargedAt ?? receipt.sentAt),
          );
        if (!ledger && !evidence)
          await importUsageEvidence(owner, {
            sourceKey: `delivery:${key}`,
            deliveryKey: key,
            chargedAt: receipt.sentAt,
            timestampSource: "sentAt",
          });
        if (!receipt.deliveryKey)
          await tx.deliveryReceipt.updateMany({
            where: { id: receipt.id, userId },
            data: { deliveryKey: key },
          });
      }
      // Even a paused billing boundary needs historical accounting. It does not
      // authorize sending; current-period resolution will continue to fail closed.
      try {
        await ensureUsagePeriods(
          owner,
          resolveUsagePeriods(user, originalCutover),
        );
      } catch (error) {
        if (!(error instanceof UsagePeriodError)) throw error;
        await ensureUsagePeriods(
          owner,
          historicalUsagePeriods(user, originalCutover),
        );
      }
      await repairUsageCounters(owner);
      const validation = await validateUsageOwner(owner);
      await tx.user.update({
        where: { id: userId },
        data: {
          usageBackfillVersion: USAGE_BACKFILL_VERSION,
          usageCutoverAt: originalCutover,
        },
      });
      result = {
        ready: true,
        sends: sends.length,
        receipts: receipts.length,
        ...validation,
      };
      if (!apply) throw dryRun;
    });
  } catch (error) {
    if (error !== dryRun) throw error;
  }
  return result!;
}

import { safeLog } from "@/lib/observability";
import "server-only";

import { randomUUID } from "node:crypto";
import {
  Prisma,
  type PrismaClient,
  type UsagePeriod,
  type UsageReservation,
} from "@/generated/prisma/client";
import { AppError } from "@/lib/errors";
import type { UsagePeriods, UsagePeriodSpec } from "@/lib/usage-periods";

const contexts = new WeakSet<object>();
const ownerBrand: unique symbol = Symbol("usage-owner-transaction");
export type UsageOwnerTransaction = {
  readonly tx: Prisma.TransactionClient;
  readonly userId: string;
  readonly [ownerBrand]: true;
};

/** Internal database primitive, not an authenticated server action.
 * Call before other row locks. Network work must remain outside this transaction.
 */
export async function lockUsageOwner(
  tx: Prisma.TransactionClient,
  userId: string,
): Promise<UsageOwnerTransaction> {
  const rows = await tx.$queryRaw<
    { id: string }[]
  >`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
  if (!rows.length) throw new Error("Usage owner unavailable.");
  const owner = Object.freeze({ tx, userId, [ownerBrand]: true as const });
  contexts.add(owner);
  return owner;
}

function check(owner: UsageOwnerTransaction) {
  if (!contexts.has(owner))
    throw new Error("A locked owner transaction is required.");
}

function retryable(error: unknown): boolean {
  if (!(error instanceof Prisma.PrismaClientKnownRequestError)) return false;
  if (error.code === "P2034") return true;
  const cause = error.meta?.driverAdapterError as
    { cause?: { originalCode?: string } } | undefined;
  return ["40001", "40P01"].includes(cause?.cause?.originalCode ?? "");
}

/** Retries only short database work. Never put Gmail or publication in work. */
export async function withUsageTransaction<T>(
  client: PrismaClient,
  userId: string,
  work: (owner: UsageOwnerTransaction) => Promise<T>,
): Promise<T> {
  for (let attempt = 0; ; attempt++) {
    try {
      return await client.$transaction(
        async (tx) => {
          const owner = await lockUsageOwner(tx, userId);
          try {
            return await work(owner);
          } finally {
            contexts.delete(owner);
          }
        },
        { maxWait: 10000, timeout: 10000 },
      );
    } catch (error) {
      if (attempt >= 2 || !retryable(error)) throw error;
    }
  }
}

export class UsageCapacityError extends AppError {
  readonly code = "USAGE_CAPACITY_EXCEEDED";
  constructor(
    readonly allowance: "DAILY" | "MONTHLY",
    readonly remaining: number,
    readonly resetAt: Date,
  ) {
    super(
      `${allowance === "DAILY" ? "Daily" : "Monthly"} allowance reached. ${remaining} remaining; resets ${resetAt.toISOString()}.`,
    );
  }
}

/** Lock every affected bucket before Send/reservation rows. Owner locking makes
 * creation safe; ordering also covers old/new buckets and overlapping allowances.
 */
async function lockPeriods(owner: UsageOwnerTransaction) {
  check(owner);
  return owner.tx.$queryRaw<
    UsagePeriod[]
  >`SELECT * FROM "UsagePeriod" WHERE "userId" = ${owner.userId} ORDER BY kind, "startsAt", key, id FOR UPDATE`;
}

function contains(period: UsagePeriod, time: Date) {
  return period.startsAt <= time && time < period.operationalEndsAt;
}

/** Reconstruct from durable identities, not Send rows. Imported counters are the
 * disjoint portion that isn't directly assigned to this particular period.
 * All buckets are already locked, so settlement and overlap repair are atomic.
 */
async function refreshCounters(
  owner: UsageOwnerTransaction,
  periods: UsagePeriod[],
  preview = false,
) {
  const { tx, userId } = owner;
  // Temporary testing reset: production always reconstructs the full ledger.
  const resetAt =
    process.env.NODE_ENV === "development"
      ? (
          await tx.user.findUniqueOrThrow({
            where: { id: userId },
            select: { testingUsageResetAt: true },
          })
        ).testingUsageResetAt
      : null;
  const reservations = await tx.usageReservation.findMany({
    where: { userId },
  });
  const evidence = await tx.usageImportEvidence.findMany({ where: { userId } });
  const ledgerKeys = new Set(reservations.map((r) => r.deliveryKey));
  for (const period of periods) {
    let sent = 0,
      reserved = 0,
      importedSent = 0,
      importedReserved = 0;
    for (const row of reservations) {
      if (row.status === "RELEASED") continue;
      if (
        resetAt &&
        period.operationalEndsAt > resetAt &&
        row.status === "CONFIRMED" &&
        row.confirmedAt &&
        row.confirmedAt <= resetAt
      )
        continue;
      const direct =
        (period.kind === "DAILY" ? row.dailyPeriodId : row.monthlyPeriodId) ===
        period.id;
      if (!direct && !(row.chargedAt && contains(period, row.chargedAt)))
        continue;
      if (row.status === "CONFIRMED") {
        sent++;
        if (!direct) importedSent++;
      } else {
        reserved++;
        if (!direct) importedReserved++;
      }
    }
    for (const row of evidence) {
      if (row.deliveryKey && ledgerKeys.has(row.deliveryKey)) continue;
      if (
        resetAt &&
        period.operationalEndsAt > resetAt &&
        row.chargedAt <= resetAt
      )
        continue;
      if (contains(period, row.chargedAt)) {
        sent++;
        importedSent++;
      }
    }
    if (
      period.sent === sent &&
      period.reserved === reserved &&
      period.importedSent === importedSent &&
      period.importedReserved === importedReserved
    )
      continue;
    Object.assign(period, { sent, reserved, importedSent, importedReserved });
    if (preview) continue;
    await tx.usagePeriod.updateMany({
      where: { id: period.id, userId },
      data: { sent, reserved, importedSent, importedReserved },
    });
  }
}

export async function ensureUsagePeriods(
  owner: UsageOwnerTransaction,
  specs: UsagePeriods,
) {
  check(owner);
  const { tx, userId } = owner;
  for (const [kind, spec] of [
    ["DAILY", specs.daily],
    ["MONTHLY", specs.monthly],
  ] as const) {
    if (
      spec.kind !== kind ||
      !Number.isSafeInteger(spec.limit) ||
      spec.limit < 0 ||
      !Number.isFinite(spec.startsAt.getTime()) ||
      !Number.isFinite(spec.endsAt.getTime()) ||
      !Number.isFinite(spec.operationalEndsAt.getTime()) ||
      spec.startsAt >= spec.endsAt ||
      spec.operationalEndsAt < spec.endsAt
    )
      throw new Error("Invalid usage period.");
    const existing = await tx.usagePeriod.findFirst({
      where: { userId, key: spec.key },
    });
    if (existing) {
      if (
        existing.kind !== spec.kind ||
        +existing.startsAt !== +spec.startsAt ||
        +existing.endsAt !== +spec.endsAt
      )
        throw new Error("Usage period identity mismatch.");
    } else
      await tx.usagePeriod.create({
        data: {
          userId,
          key: spec.key,
          kind: spec.kind,
          startsAt: spec.startsAt,
          endsAt: spec.endsAt,
          operationalEndsAt: spec.operationalEndsAt,
        },
      });
  }
  const periods = await lockPeriods(owner);
  // Existing bucket updates follow the same daily/monthly lock order.
  for (const period of periods) {
    const spec =
      period.key === specs.daily.key
        ? specs.daily
        : period.key === specs.monthly.key
          ? specs.monthly
          : null;
    if (spec && period.operationalEndsAt < spec.operationalEndsAt) {
      await tx.usagePeriod.updateMany({
        where: { userId, id: period.id },
        data: { operationalEndsAt: spec.operationalEndsAt },
      });
      period.operationalEndsAt = spec.operationalEndsAt;
    }
  }
  await refreshCounters(owner, periods);
  return {
    daily: periods.find((p) => p.key === specs.daily.key)!,
    monthly: periods.find((p) => p.key === specs.monthly.key)!,
    all: periods,
  };
}

function capacity(period: UsagePeriod, spec: UsagePeriodSpec, extra: number) {
  const remaining = Math.max(0, spec.limit - period.sent - period.reserved);
  if (extra > 0 && remaining < extra)
    throw new UsageCapacityError(
      period.kind,
      remaining,
      period.operationalEndsAt,
    );
}

async function reservationFor(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
) {
  const row = await owner.tx.usageReservation.findFirst({
    where: { userId: owner.userId, deliveryKey },
  });
  if (!row) throw new Error("Usage reservation unavailable.");
  return row;
}

async function sendFor(owner: UsageOwnerTransaction, sendId: string | null) {
  if (!sendId) throw new Error("Usage reservation has no retained send.");
  const send = await owner.tx.send.findFirst({
    where: { id: sendId, campaign: { userId: owner.userId } },
    select: {
      id: true,
      status: true,
      deliveryState: true,
      attemptedAt: true,
      sentAt: true,
      gmailMessageId: true,
      claimToken: true,
      queueExpiresAt: true,
      availableAt: true,
    },
  });
  if (!send) throw new Error("Usage send unavailable.");
  return send;
}

/** Whole-batch capacity check before writes; retries return the same identities.
 * enforceLimits=false is reserved for legacy flag-off callers (rolling-200 is
 * still their responsibility). This module does not read rollout controls.
 */
export async function reserveUsage(
  owner: UsageOwnerTransaction,
  specs: UsagePeriods,
  items: { sendId: string; deliveryKey: string }[],
  enforceLimits: boolean,
) {
  const buckets = await ensureUsagePeriods(owner, specs);
  if (
    new Set(items.map((r) => r.sendId)).size !== items.length ||
    new Set(items.map((r) => r.deliveryKey)).size !== items.length
  )
    throw new Error("Duplicate reservation input.");
  const existing: UsageReservation[] = [],
    pending: typeof items = [];
  for (const item of items) {
    const send = await sendFor(owner, item.sendId);
    const row = await owner.tx.usageReservation.findFirst({
      where: { userId: owner.userId, deliveryKey: item.deliveryKey },
    });
    if (row) {
      if (row.sendId !== item.sendId)
        throw new Error("Delivery identity mismatch.");
      existing.push(row);
    } else {
      if (
        send.status !== "QUEUED" ||
        send.deliveryState !== "READY" ||
        send.attemptedAt
      )
        throw new Error("Only unsubmitted queued sends can reserve usage.");
      if (
        await owner.tx.usageImportEvidence.findFirst({
          where: { userId: owner.userId, deliveryKey: item.deliveryKey },
        })
      )
        throw new Error("Historical delivery cannot reserve new usage.");
      pending.push(item);
    }
  }
  if (enforceLimits) {
    capacity(buckets.daily, specs.daily, pending.length);
    capacity(buckets.monthly, specs.monthly, pending.length);
  }
  for (const item of pending)
    existing.push(
      await owner.tx.usageReservation.create({
        data: {
          userId: owner.userId,
          ...item,
          dailyPeriodId: buckets.daily.id,
          monthlyPeriodId: buckets.monthly.id,
        },
      }),
    );
  await refreshCounters(owner, buckets.all);
  return existing;
}

/** On capacity failure no reservation moves. Caller defers via availableAt. */
export async function rebindUsage(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
  specs: UsagePeriods,
  enforceLimits: boolean,
) {
  const buckets = await ensureUsagePeriods(owner, specs);
  const row = await reservationFor(owner, deliveryKey);
  if (row.status !== "RESERVED" || row.chargedAt)
    throw new Error("Attempted usage cannot be rebound.");
  const send = await sendFor(owner, row.sendId);
  if (
    send.status !== "QUEUED" ||
    send.deliveryState !== "READY" ||
    send.attemptedAt
  )
    throw new Error("Only unsubmitted queued sends can rebind usage.");
  if (enforceLimits) {
    // The reservation already occupies one slot in an unchanged bucket.
    if (
      buckets.daily.sent +
        buckets.daily.reserved +
        (row.dailyPeriodId === buckets.daily.id ? 0 : 1) >
      specs.daily.limit
    )
      throw new UsageCapacityError(
        "DAILY",
        Math.max(
          0,
          specs.daily.limit - buckets.daily.sent - buckets.daily.reserved,
        ),
        buckets.daily.operationalEndsAt,
      );
    if (
      buckets.monthly.sent +
        buckets.monthly.reserved +
        (row.monthlyPeriodId === buckets.monthly.id ? 0 : 1) >
      specs.monthly.limit
    )
      throw new UsageCapacityError(
        "MONTHLY",
        Math.max(
          0,
          specs.monthly.limit - buckets.monthly.sent - buckets.monthly.reserved,
        ),
        buckets.monthly.operationalEndsAt,
      );
  }
  const updated = await owner.tx.usageReservation.update({
    where: { id: row.id, userId: owner.userId },
    data: {
      dailyPeriodId: buckets.daily.id,
      monthlyPeriodId: buckets.monthly.id,
    },
  });
  await refreshCounters(owner, buckets.all);
  return updated;
}

/** Caller has allocated the entire campaign under the owner lock. Rebinding
 * changes no delivery identity and never releases or revives queued work. */
export async function rebindReadyRemainder(
  owner: UsageOwnerTransaction,
  keys: string[],
  specs: UsagePeriods,
) {
  const buckets = await ensureUsagePeriods(owner, specs);
  for (const key of keys) {
    const row = await reservationFor(owner, key);
    const send = await sendFor(owner, row.sendId);
    if (
      row.status !== "RESERVED" ||
      row.chargedAt ||
      send.status !== "QUEUED" ||
      send.deliveryState !== "READY" ||
      send.attemptedAt ||
      send.sentAt ||
      send.gmailMessageId
    )
      throw new Error("Campaign remainder is not proven unsubmitted.");
  }
  await owner.tx.usageReservation.updateMany({
    where: {
      userId: owner.userId,
      deliveryKey: { in: keys },
      status: "RESERVED",
      chargedAt: null,
    },
    data: {
      dailyPeriodId: buckets.daily.id,
      monthlyPeriodId: buckets.monthly.id,
    },
  });
  await refreshCounters(owner, buckets.all);
}

/** Immediately before provider submission; all network preparation precedes this.
 * The lease is evidence of an active worker, not permission to automatically retry.
 */
export async function claimUsage(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
  specs: UsagePeriods,
  enforceLimits: boolean,
  now = new Date(),
) {
  await lockPeriods(owner);
  const existing = await reservationFor(owner, deliveryKey);
  if (existing.status !== "RESERVED")
    return { claimed: false as const, reservation: existing };
  if (
    now < specs.daily.startsAt ||
    now >= specs.daily.operationalEndsAt ||
    now < specs.monthly.startsAt ||
    now >= specs.monthly.operationalEndsAt
  )
    throw new Error("Claim requires current usage periods.");
  const send = await sendFor(owner, existing.sendId);
  if (
    (send.queueExpiresAt && send.queueExpiresAt <= now) ||
    (send.availableAt && send.availableAt > now)
  )
    throw new Error("Queued send is not available to claim.");
  await rebindUsage(owner, deliveryKey, specs, enforceLimits);
  const claimToken = randomUUID(),
    leaseExpiresAt = new Date(now.getTime() + 120000);
  const reservation = await owner.tx.usageReservation.update({
    where: { id: existing.id, userId: owner.userId },
    data: {
      status: "ATTEMPTING",
      chargedAt: now,
      claimToken,
      leaseExpiresAt,
    },
  });
  await owner.tx.send.updateMany({
    where: { id: send.id, campaign: { userId: owner.userId } },
    data: {
      deliveryState: "ATTEMPTING",
      attemptedAt: now,
      claimToken,
      leaseExpiresAt,
    },
  });
  const periods = await lockPeriods(owner);
  await refreshCounters(owner, periods);
  return { claimed: true as const, reservation };
}

export async function confirmUsage(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
  claimToken: string,
  acceptance: { gmailMessageId: string; gmailThreadId?: string; sentAt: Date },
) {
  const periods = await lockPeriods(owner);
  const row = await reservationFor(owner, deliveryKey);
  if (row.claimToken !== claimToken) throw new Error("Usage claim mismatch.");
  if (row.status === "CONFIRMED") return row;
  if (
    !["ATTEMPTING", "UNCERTAIN"].includes(row.status) ||
    !acceptance.gmailMessageId
  )
    throw new Error("Usage cannot be confirmed without acceptance.");
  if (row.sendId) await sendFor(owner, row.sendId);
  const updated = await owner.tx.usageReservation.update({
    where: { id: row.id, userId: owner.userId },
    data: {
      status: "CONFIRMED",
      confirmedAt: acceptance.sentAt,
    },
  });
  if (row.sendId)
    await owner.tx.send.updateMany({
      where: { id: row.sendId, campaign: { userId: owner.userId } },
      data: {
        status: "SENT",
        deliveryState: "DONE",
        sentAt: acceptance.sentAt,
        gmailMessageId: acceptance.gmailMessageId,
        gmailThreadId: acceptance.gmailThreadId,
        error: null,
        claimToken: null,
        leaseExpiresAt: null,
      },
    });
  await refreshCounters(owner, periods);
  return updated;
}

export async function markUsageUncertain(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
  claimToken: string,
  now = new Date(),
  expiredLeaseOnly = false,
) {
  const periods = await lockPeriods(owner);
  const row = await reservationFor(owner, deliveryKey);
  if (row.claimToken !== claimToken) throw new Error("Usage claim mismatch.");
  if (row.status === "UNCERTAIN" || row.status === "CONFIRMED") return row;
  if (row.status !== "ATTEMPTING") throw new Error("Usage has no attempt.");
  if (expiredLeaseOnly && row.leaseExpiresAt! > now) return row;
  if (row.sendId) await sendFor(owner, row.sendId);
  const updated = await owner.tx.usageReservation.update({
    where: { id: row.id, userId: owner.userId },
    data: { status: "UNCERTAIN" },
  });
  if (row.sendId)
    await owner.tx.send.updateMany({
      where: { id: row.sendId, campaign: { userId: owner.userId } },
      data: {
        status: "FAILED",
        deliveryState: "UNCERTAIN",
        error:
          "Delivery needs review. Check Gmail Sent; Mailloop will not automatically resend.",
      },
    });
  await refreshCounters(owner, periods);
  return updated;
}

export type UsageReleaseProof =
  { kind: "UNSUBMITTED" } | { kind: "DEFINITE_REJECTION"; claimToken: string };
export async function releaseUsage(
  owner: UsageOwnerTransaction,
  deliveryKey: string,
  proof: UsageReleaseProof,
  now = new Date(),
) {
  const periods = await lockPeriods(owner);
  const row = await reservationFor(owner, deliveryKey);
  if (row.status === "RELEASED") return row;
  if (proof.kind === "UNSUBMITTED") {
    const send = await sendFor(owner, row.sendId);
    if (
      row.status !== "RESERVED" ||
      row.chargedAt ||
      !(
        send.deliveryState === "READY" ||
        (send.deliveryState === "DONE" &&
          ["FAILED", "CANCELLED"].includes(send.status))
      ) ||
      send.attemptedAt ||
      send.gmailMessageId ||
      send.sentAt
    )
      throw new Error("Usage is not proven unsubmitted.");
  } else if (row.status !== "ATTEMPTING" || row.claimToken !== proof.claimToken)
    throw new Error("Usage has no matching definite rejection.");
  if (row.sendId) await sendFor(owner, row.sendId);
  const updated = await owner.tx.usageReservation.update({
    where: { id: row.id, userId: owner.userId },
    data: { status: "RELEASED", releasedAt: now },
  });
  if (row.sendId)
    await owner.tx.send.updateMany({
      where: { id: row.sendId, campaign: { userId: owner.userId } },
      data: {
        status: proof.kind === "UNSUBMITTED" ? "CANCELLED" : "FAILED",
        deliveryState: "DONE",
        cancelledAt: proof.kind === "UNSUBMITTED" ? now : undefined,
        claimToken: null,
        leaseExpiresAt: null,
      },
    });
  await refreshCounters(owner, periods);
  return updated;
}

/** Called only for durable accepted-send evidence. Stable source keys make
 * imports resumable; timestamp provenance is retained without message content.
 */
export async function importUsageEvidence(
  owner: UsageOwnerTransaction,
  evidence: {
    sourceKey: string;
    deliveryKey: string | null;
    chargedAt: Date;
    timestampSource: "attemptedAt" | "sentAt";
  },
) {
  const periods = await lockPeriods(owner);
  const existing = await owner.tx.usageImportEvidence.findFirst({
    where: { userId: owner.userId, sourceKey: evidence.sourceKey },
  });
  if (existing) {
    if (
      existing.deliveryKey !== evidence.deliveryKey ||
      +existing.chargedAt !== +evidence.chargedAt ||
      existing.timestampSource !== evidence.timestampSource
    )
      throw new Error("Historical usage identity mismatch.");
    return existing;
  }
  const row = await owner.tx.usageImportEvidence.create({
    data: { userId: owner.userId, ...evidence },
  });
  await refreshCounters(owner, periods);
  return row;
}

export const USAGE_BACKFILL_VERSION = 1;
export class UsageNotReadyError extends AppError {
  readonly code = "USAGE_NOT_READY";
  constructor() {
    super("Sending is paused while usage accounting is verified.");
  }
}

/** New, empty owners can initialize under the lock. Existing history requires
 * the explicit backfill. Never authorize from the browser's quota snapshot. */
export async function requireUsageReady(
  owner: UsageOwnerTransaction,
  gated: boolean,
  now = new Date(),
) {
  check(owner);
  const { tx, userId } = owner;
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  if (!gated) return user;
  const missing = await tx.send.count({
    where: {
      campaign: { userId },
      usageReservation: null,
      OR: [
        { status: { in: ["QUEUED", "SENT", "REPLIED"] } },
        { deliveryState: { in: ["ATTEMPTING", "UNCERTAIN"] } },
      ],
    },
  });
  if (user.usageBackfillVersion < USAGE_BACKFILL_VERSION) {
    const [sends, receipts, imports, reservations] = await Promise.all([
      tx.send.count({ where: { campaign: { userId } } }),
      tx.deliveryReceipt.count({ where: { userId } }),
      tx.usageImportEvidence.count({ where: { userId } }),
      tx.usageReservation.count({ where: { userId } }),
    ]);
    if (sends || receipts || imports || reservations)
      throw new UsageNotReadyError();
    return tx.user.update({
      where: { id: userId },
      data: {
        usageBackfillVersion: USAGE_BACKFILL_VERSION,
        usageCutoverAt: now,
      },
    });
  }
  // Historical successes may intentionally be imported rather than ledger-backed.
  if (missing) {
    const unaccounted = await tx.$queryRaw<{ id: string }[]>`
      SELECT s.id FROM "Send" s JOIN "Campaign" c ON c.id=s."campaignId"
      WHERE c."userId"=${userId} AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."sendId"=s.id)
      AND (s.status='QUEUED' OR s."deliveryState" IN ('ATTEMPTING','UNCERTAIN') OR
        (s.status IN ('SENT','REPLIED') AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=s.id))) LIMIT 1`;
    if (unaccounted.length) throw new UsageNotReadyError();
  }
  const missingReceipt = await tx.$queryRaw<{ id: string }[]>`
    SELECT d.id FROM "DeliveryReceipt" d WHERE d."userId"=${userId}
    AND NOT EXISTS (SELECT 1 FROM "UsageReservation" r WHERE r."userId"=${userId} AND r."deliveryKey"=d."deliveryKey")
    AND NOT EXISTS (SELECT 1 FROM "UsageImportEvidence" e WHERE e."userId"=${userId} AND e."deliveryKey"=d."deliveryKey") LIMIT 1`;
  if (missingReceipt.length) throw new UsageNotReadyError();
  return user;
}

export async function repairUsageCounters(
  owner: UsageOwnerTransaction,
  preview = false,
) {
  const periods = await lockPeriods(owner);
  const before = periods.map((p) => ({ ...p }));
  await refreshCounters(owner, periods, preview);
  return periods
    .filter((p, i) =>
      ["sent", "reserved", "importedSent", "importedReserved"].some(
        (key) => p[key as "sent"] !== before[i][key as "sent"],
      ),
    )
    .map((p) => p.id);
}

/** Explicit cutover/adoption only. Caller supplies historical attribution and
 * durable evidence, never a user-provided assertion of delivery. */
export async function adoptUsageReservation(
  owner: UsageOwnerTransaction,
  input: {
    sendId: string;
    deliveryKey: string;
    specs: UsagePeriods;
    status: "RESERVED" | "UNCERTAIN" | "CONFIRMED";
    chargedAt: Date | null;
    confirmedAt?: Date;
  },
) {
  const periods = await ensureUsagePeriods(owner, input.specs);
  const send = await sendFor(owner, input.sendId);
  const existing = await owner.tx.usageReservation.findFirst({
    where: { userId: owner.userId, sendId: input.sendId },
  });
  if (existing && input.status !== "CONFIRMED") {
    if (input.status === "UNCERTAIN" && existing.status === "ATTEMPTING") {
      if (existing.leaseExpiresAt && +existing.leaseExpiresAt > Date.now())
        throw new Error("Drain active requests before usage cutover.");
      return markUsageUncertain(
        owner,
        existing.deliveryKey,
        existing.claimToken!,
        new Date(Date.now()),
        true,
      );
    }
    return existing;
  }
  if (existing?.status === "CONFIRMED") return existing;
  if (input.status === "CONFIRMED" && !send.sentAt && !send.gmailMessageId)
    throw new Error("Durable acceptance evidence required.");
  if (
    input.status === "RESERVED" &&
    (send.attemptedAt || send.deliveryState !== "READY")
  )
    throw new Error("Send is not unsubmitted.");
  const token =
    input.status === "UNCERTAIN" ? (send.claimToken ?? randomUUID()) : null;
  const data = {
    status: input.status,
    chargedAt: existing?.chargedAt ?? input.chargedAt,
    dailyPeriodId: existing?.chargedAt
      ? existing.dailyPeriodId
      : periods.daily.id,
    monthlyPeriodId: existing?.chargedAt
      ? existing.monthlyPeriodId
      : periods.monthly.id,
    confirmedAt: input.status === "CONFIRMED" ? input.confirmedAt! : null,
    releasedAt: null,
    claimToken: existing?.claimToken ?? token,
    leaseExpiresAt:
      existing?.leaseExpiresAt ??
      (input.chargedAt && token ? new Date(+input.chargedAt + 120000) : null),
  };
  const row = existing
    ? await owner.tx.usageReservation.update({
        where: { id: existing.id, userId: owner.userId },
        data,
      })
    : await owner.tx.usageReservation.create({
        data: {
          ...data,
          userId: owner.userId,
          sendId: send.id,
          deliveryKey: input.deliveryKey,
        },
      });
  if (input.status === "UNCERTAIN")
    await owner.tx.send.updateMany({
      where: { id: send.id, campaign: { userId: owner.userId } },
      data: {
        status: "FAILED",
        deliveryState: "UNCERTAIN",
        error:
          "Delivery needs review. Check Gmail Sent; Mailloop will not automatically resend.",
        attemptedAt: input.chargedAt,
        claimToken: row.claimToken,
        leaseExpiresAt: row.leaseExpiresAt,
      },
    });
  await refreshCounters(owner, periods.all);
  return row;
}

export function warnUsage(code: string, userId: string, sendId?: string) {
  safeLog("warn", "usage", { code, userId, ...(sendId ? { sendId } : {}) });
}

/** Retained history receipts are durable acceptance evidence even after the
 * original Send has been deleted. No mailbox lookup or manual assertion. */
export async function settleUsageReceipt(
  owner: UsageOwnerTransaction,
  receiptId: string,
  specs: UsagePeriods,
) {
  const periods = await ensureUsagePeriods(owner, specs);
  const receipt = await owner.tx.deliveryReceipt.findFirstOrThrow({
    where: { id: receiptId, userId: owner.userId },
  });
  if (!receipt.deliveryKey) return;
  const row = await owner.tx.usageReservation.findFirst({
    where: { userId: owner.userId, deliveryKey: receipt.deliveryKey },
  });
  if (!row || row.status === "CONFIRMED") return;
  await owner.tx.usageReservation.update({
    where: { id: row.id, userId: owner.userId },
    data: {
      status: "CONFIRMED",
      chargedAt: row.chargedAt ?? receipt.sentAt,
      confirmedAt: receipt.sentAt,
      releasedAt: null,
      dailyPeriodId: row.chargedAt ? row.dailyPeriodId : periods.daily.id,
      monthlyPeriodId: row.chargedAt ? row.monthlyPeriodId : periods.monthly.id,
    },
  });
  if (row.sendId)
    await owner.tx.send.updateMany({
      where: {
        id: row.sendId,
        campaign: { userId: owner.userId },
        status: { not: "REPLIED" },
      },
      data: {
        status: "SENT",
        deliveryState: "DONE",
        sentAt: receipt.sentAt,
        claimToken: null,
        leaseExpiresAt: null,
      },
    });
  await refreshCounters(owner, periods.all);
}

import "server-only";

import type { UsagePeriodKind } from "@/generated/prisma/client";
import {
  getEffectivePlan,
  hasUnresolvedBillingPeriod,
  type EntitlementUser,
} from "@/lib/entitlements";
import { AppError } from "@/lib/errors";
import { resolveSubscriptionLifecycle } from "@/lib/subscription-lifecycle";
import { PLANS } from "@/lib/plans";

export type UsagePeriodSpec = {
  key: string;
  kind: UsagePeriodKind;
  startsAt: Date;
  endsAt: Date;
  operationalEndsAt: Date;
  limit: number;
};
export type UsagePeriods = { daily: UsagePeriodSpec; monthly: UsagePeriodSpec };

export class UsagePeriodError extends AppError {
  readonly code = "BILLING_PERIOD_UNRESOLVED";
  constructor() {
    super("Sending is paused until the subscription period is verified.");
  }
}

/** Half-open UTC periods. Grace extends one allowance, never its identity. */
export function resolveUsagePeriods(
  user: EntitlementUser,
  now = new Date(Date.now()),
): UsagePeriods {
  if (!Number.isFinite(now.getTime())) throw new Error("Invalid usage time.");
  const plan = getEffectivePlan(user, now);
  const limits = PLANS[plan];
  const start = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
  );
  const end = new Date(start.getTime() + 86400000);
  const daily: UsagePeriodSpec = {
    key: `day:${start.toISOString()}`,
    kind: "DAILY",
    startsAt: start,
    endsAt: end,
    operationalEndsAt: end,
    limit: limits.dailyEmails,
  };
  const providerStart = user.currentPeriodStart;
  const providerEnd = user.currentPeriodEnd;
  const validProvider = resolveSubscriptionLifecycle(user, now).paid;
  // A verified expired/cancelled subscription can downgrade; an active billing
  // boundary cannot invent a new calendar allowance, even under a paid grant.
  if (hasUnresolvedBillingPeriod(user, now)) throw new UsagePeriodError();
  if (plan === "PAID" && validProvider) {
    return {
      daily,
      monthly: {
        key: `provider:${JSON.stringify([user.dodoSubscriptionId, providerStart!.toISOString(), providerEnd!.toISOString()])}`,
        kind: "MONTHLY",
        startsAt: providerStart!,
        endsAt: providerEnd!,
        operationalEndsAt:
          user.subscriptionStatus === "PAST_DUE" &&
          user.gracePeriodEnd! > providerEnd!
            ? user.gracePeriodEnd!
            : providerEnd!,
        limit: limits.monthlyEmails,
      },
    };
  }
  const monthStart = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1),
  );
  const monthEnd = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1),
  );
  return {
    daily,
    monthly: {
      key: `month:${monthStart.toISOString()}`,
      kind: "MONTHLY",
      startsAt: monthStart,
      endsAt: monthEnd,
      operationalEndsAt: monthEnd,
      limit: limits.monthlyEmails,
    },
  };
}

/** Historical attempts keep their UTC charge date. Only known exact provider
 * boundaries can be used; imported evidence seeds any later overlapping bucket. */
export function historicalUsagePeriods(
  user: EntitlementUser,
  at: Date,
): UsagePeriods {
  const calendar = resolveUsagePeriods(
    {
      ...user,
      plan: "FREE",
      subscriptionStatus: "NONE",
      planOverride: null,
      grandfatheredUntil: null,
    },
    at,
  );
  const end = user.gracePeriodEnd ?? user.currentPeriodEnd;
  if (
    user.dodoSubscriptionId &&
    user.currentPeriodStart &&
    user.currentPeriodEnd &&
    user.currentPeriodStart <= at &&
    end &&
    at < end
  ) {
    return resolveUsagePeriods(
      {
        ...user,
        plan: "PAID",
        planOverride: null,
        grandfatheredUntil: null,
        subscriptionStatus: at < user.currentPeriodEnd ? "ACTIVE" : "PAST_DUE",
      },
      at,
    );
  }
  return calendar;
}

import { sendingPause } from "@/lib/sending-pause";
import "server-only";
import {
  applyFreeCampaignPolicy,
  cancelIneligibleCampaign,
} from "@/lib/campaign-policy";
import { db } from "@/lib/db";
import { historicalUsagePeriods } from "@/lib/usage-periods";
import { canUser } from "@/lib/entitlements";
import { completeCampaignIn } from "@/lib/cancellation";
import { preserveAcceptedSend } from "@/lib/usage-backfill";
import {
  markUsageUncertain,
  releaseUsage,
  repairUsageCounters,
  settleUsageReceipt,
  warnUsage,
  withUsageTransaction,
} from "@/lib/usage-ledger";

export type UsageDispatchEvent = {
  id: string;
  name: "mailloop/email.queued";
  data: { userId: string; sendId: string };
};
export type UsagePublisher = (events: UsageDispatchEvent[]) => Promise<unknown>;
const REPAIR_DELAY = 5 * 60000;

/** Commit publication metadata before network work. Every repair has a fresh
 * generation; claim state and the original delivery identity remain unchanged. */
export async function dispatchUsagePending(
  userId: string,
  publish: UsagePublisher,
  now = new Date(Date.now()),
) {
  const active = await db.user.findFirst({
    where: { id: userId, deletionRequestedAt: null },
    select: { id: true },
  });
  if (!active) return 0;
  const pending = await withUsageTransaction(db, userId, async (owner) => {
    const { tx } = owner;
    await applyFreeCampaignPolicy(owner, now);
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    const control = await tx.systemControl.findUnique({
      where: { key: "global" },
    });
    // Policy cancellation also applies to delayed READY work and while the
    // sending switch is paused. Publication eligibility is checked afterwards.
    if (control?.paidGatingEnabled) {
      const campaigns = await tx.campaign.findMany({
        where: {
          userId,
          sends: { some: { status: "QUEUED", deliveryState: "READY" } },
        },
        select: { id: true },
      });
      for (const campaign of campaigns)
        await cancelIneligibleCampaign(tx, userId, campaign.id, now);
    }
    if (
      sendingPause(user, control, now) ||
      !canUser(user, "send", control, now).allowed
    )
      return [];
    const sends = await tx.send.findMany({
      where: {
        campaign: { userId },
        status: "QUEUED",
        deliveryState: "READY",
        AND: [
          { OR: [{ availableAt: null }, { availableAt: { lte: now } }] },
          { OR: [{ queueExpiresAt: null }, { queueExpiresAt: { gt: now } }] },
          {
            OR: [
              { dispatchAttemptedAt: null },
              { dispatchAttemptedAt: { lte: new Date(+now - REPAIR_DELAY) } },
            ],
          },
        ],
      },
      orderBy: [{ createdAt: "asc" }, { id: "asc" }],
      take: 100,
    });
    const rows = [];
    for (const send of sends) {
      if (+now - +send.createdAt > REPAIR_DELAY)
        warnUsage("PUBLICATION_DELAY", userId, send.id);
      const updated = await tx.send.update({
        where: { id: send.id, campaign: { userId } },
        data: {
          dispatchGeneration: { increment: 1 },
          dispatchAttempts: { increment: 1 },
          dispatchAttemptedAt: now,
        },
      });
      rows.push({ id: send.id, generation: updated.dispatchGeneration });
    }
    return rows;
  });
  if (!pending.length) return 0;
  try {
    await publish(
      pending.map((s) => ({
        id: `send-${s.id}-${s.generation}`,
        name: "mailloop/email.queued",
        data: { userId, sendId: s.id },
      })),
    );
    for (const send of pending)
      await db.send.updateMany({
        where: {
          id: send.id,
          campaign: { userId },
          dispatchGeneration: send.generation,
        },
        data: { dispatchedAt: now },
      });
  } catch {
    warnUsage("PUBLICATION_FAILED", userId);
    throw new Error("QUEUE_PUBLICATION_FAILED");
  }
  return pending.length;
}

export async function reconcileUsageOwner(
  userId: string,
  now = new Date(Date.now()),
) {
  return withUsageTransaction(db, userId, async (owner) => {
    const { tx } = owner;
    const drift = await repairUsageCounters(owner);
    if (drift.length) warnUsage("COUNTER_DRIFT", userId);
    const sends = await tx.send.findMany({
      where: { campaign: { userId } },
      orderBy: { id: "asc" },
    });
    const campaigns = new Set<string>();
    for (const send of sends) {
      const ledger = await tx.usageReservation.findFirst({
        where: { userId, sendId: send.id },
      });
      if (
        send.sentAt &&
        (["SENT", "REPLIED"].includes(send.status) || send.gmailMessageId)
      ) {
        if (ledger && ledger.status !== "CONFIRMED") {
          await preserveAcceptedSend(owner, send.id);
          campaigns.add(send.campaignId);
        }
        continue;
      }
      if (!ledger) {
        if (
          send.status === "QUEUED" ||
          ["ATTEMPTING", "UNCERTAIN"].includes(send.deliveryState)
        )
          warnUsage("MISSING_ACCOUNTING", userId, send.id);
        continue;
      }
      if (
        ledger.status === "ATTEMPTING" &&
        ledger.leaseExpiresAt &&
        ledger.leaseExpiresAt <= now
      ) {
        await markUsageUncertain(
          owner,
          ledger.deliveryKey,
          ledger.claimToken!,
          now,
          true,
        );
        campaigns.add(send.campaignId);
      }
      if (
        ["UNCERTAIN", "ATTEMPTING"].includes(ledger.status) &&
        ledger.chargedAt &&
        +now - +ledger.chargedAt > 15 * 60000
      )
        warnUsage("UNCERTAINTY_OLDER_THAN_15_MINUTES", userId, send.id);
      const expired =
        send.status === "QUEUED" &&
        send.deliveryState === "READY" &&
        send.queueExpiresAt &&
        send.queueExpiresAt <= now;
      const terminalUnsent =
        ["FAILED", "CANCELLED"].includes(send.status) &&
        ["READY", "DONE"].includes(send.deliveryState);
      if (
        ledger.status === "RESERVED" &&
        !send.attemptedAt &&
        !send.gmailMessageId &&
        !send.sentAt &&
        (expired || terminalUnsent)
      ) {
        await releaseUsage(
          owner,
          ledger.deliveryKey,
          { kind: "UNSUBMITTED" },
          now,
        );
        if (send.status === "FAILED")
          await tx.send.updateMany({
            where: { id: send.id, campaign: { userId } },
            data: { status: "FAILED" },
          });
        campaigns.add(send.campaignId);
      }
    }
    const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
    const receipts = await tx.deliveryReceipt.findMany({
      where: { userId, deliveryKey: { not: null } },
    });
    for (const receipt of receipts) {
      const row = await tx.usageReservation.findFirst({
        where: { userId, deliveryKey: receipt.deliveryKey! },
      });
      if (row && row.status !== "CONFIRMED")
        await settleUsageReceipt(
          owner,
          receipt.id,
          historicalUsagePeriods(user, row.chargedAt ?? receipt.sentAt),
        );
    }
    const orphans = await tx.usageReservation.findMany({
      where: {
        userId,
        sendId: null,
        status: { in: ["RESERVED", "ATTEMPTING", "UNCERTAIN"] },
      },
    });
    for (const row of orphans) {
      if (
        row.status === "ATTEMPTING" &&
        row.leaseExpiresAt &&
        row.leaseExpiresAt <= now
      )
        await markUsageUncertain(
          owner,
          row.deliveryKey,
          row.claimToken!,
          now,
          true,
        );
      if (row.chargedAt && +now - +row.chargedAt > 15 * 60000)
        warnUsage("UNCERTAINTY_OLDER_THAN_15_MINUTES", userId);
    }
    if (orphans.length) warnUsage("OUTSTANDING_ORPHAN", userId);
    await repairUsageCounters(owner);
    for (const id of campaigns) await completeCampaignIn(tx, userId, id);
    return { drift: drift.length, orphans: orphans.length };
  });
}

// System enumeration returns IDs only. Each owner transaction and publication
// is independent, so one broken account cannot stall the remaining owners.
export async function reconcileUsagePage(
  publish: UsagePublisher,
  after?: string,
  now = new Date(),
) {
  const owners = await db.user.findMany({
    where: after ? { id: { gt: after } } : {},
    select: { id: true },
    orderBy: { id: "asc" },
    take: 50,
  });
  let processed = 0,
    failed = 0;
  for (const { id } of owners) {
    try {
      await reconcileUsageOwner(id, now);
      await dispatchUsagePending(id, publish, now);
      processed++;
    } catch {
      failed++;
      warnUsage("REPAIR_FAILED", id);
    }
  }
  return {
    processed,
    failed,
    cursor: owners.length === 50 ? owners.at(-1)!.id : null,
  };
}
export async function reconcileUsageOwners(
  publish: UsagePublisher,
  now = new Date(),
) {
  let cursor: string | undefined,
    processed = 0,
    failed = 0;
  do {
    const page = await reconcileUsagePage(publish, cursor, now);
    processed += page.processed;
    failed += page.failed;
    cursor = page.cursor ?? undefined;
  } while (cursor);
  return { processed, failed };
}

export type AllowanceState = "healthy" | "low" | "empty" | "reserved";

/** Presentation only: the provider remains authoritative for all counts. */
export function getAllowanceState({
  remaining,
  total,
  queued,
}: {
  remaining: number;
  total: number;
  queued: number;
}): AllowanceState {
  if (total <= 0) return "empty";
  if (remaining <= 0) return queued > 0 ? "reserved" : "empty";
  return remaining / total <= 0.2 ? "low" : "healthy";
}

