import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({ auth: vi.fn(), update: vi.fn() }));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/db", () => ({ db: { user: { updateMany: mocks.update } } }));
import { POST } from "@/app/api/account/activity/route";
import { markApplicationActivity } from "@/lib/activity";
describe("navigation activity", () => {
  beforeEach(() => vi.clearAllMocks());
  it("authenticates and enforces same origin", async () => {
    mocks.auth.mockResolvedValue(null);
    expect(
      (
        await POST(
          new Request("http://localhost/api/account/activity", {
            method: "POST",
          }),
        )
      ).status,
    ).toBe(401);
    mocks.auth.mockResolvedValue({ user: { id: "owner" } });
    expect(
      (
        await POST(
          new Request("http://localhost/api/account/activity", {
            method: "POST",
            headers: { origin: "http://attacker" },
          }),
        )
      ).status,
    ).toBe(403);
    expect(mocks.update).not.toHaveBeenCalled();
  });
  it("conditionally updates at most every 15 minutes and excludes deleting accounts", async () => {
    const now = new Date();
    await markApplicationActivity("owner", now);
    expect(mocks.update).toHaveBeenCalledWith({
      where: {
        id: "owner",
        deletionRequestedAt: null,
        OR: [
          { lastActiveAt: null },
          { lastActiveAt: { lte: new Date(+now - 900000) } },
        ],
      },
      data: { lastActiveAt: now },
    });
    mocks.auth.mockResolvedValue({ user: { id: "owner" } });
    expect(
      (
        await POST(
          new Request("http://localhost/api/account/activity", {
            method: "POST",
            headers: { origin: "http://localhost" },
          }),
        )
      ).status,
    ).toBe(200);
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
import { randomUUID } from "node:crypto";
const mocks = vi.hoisted(() => ({
  auth: vi.fn(),
  find: vi.fn(),
  boundary: vi.fn(),
}));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("@/lib/admin/db", () => ({
  adminDb: () => ({
    user: { findUnique: mocks.find },
    $queryRaw: mocks.boundary,
  }),
}));
import { requireAdmin, freshAuthentication } from "@/lib/admin/auth";
const id = randomUUID();
describe("operator authentication", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mocks.boundary.mockResolvedValue([{ restricted: true }]);
    mocks.auth.mockResolvedValue({
      user: { id },
      adminAuthAt: Math.floor(Date.now() / 1000),
      adminAuthUserId: id,
    });
    mocks.find.mockResolvedValue({
      id,
      isAdmin: true,
      isSuspended: false,
      deletionRequestedAt: null,
    });
  });
  it("denies anonymous and nonadmins", async () => {
    mocks.auth.mockResolvedValue(null);
    await expect(requireAdmin()).rejects.toMatchObject({ code: "DENIED" });
    expect(mocks.find).not.toHaveBeenCalled();
    mocks.auth.mockResolvedValue({ user: { id } });
    mocks.find.mockResolvedValue({ id, isAdmin: false });
    await expect(requireAdmin()).rejects.toMatchObject({ code: "DENIED" });
  });
  it.each([
    { isAdmin: false },
    { isSuspended: true },
    { deletionRequestedAt: new Date() },
