          : "SENT",
        ["queued", "failed", "cancelled", "missing"].includes(state)
          ? null
          : sentAt,
        "Personalized infrastructure introduction",
        state === "failed"
          ? "Gmail submission failed. Please try again."
          : null,
      ],
    );
    if (state === "pending")
      await pool.query(
        `INSERT INTO "Send" (id,"campaignId","contactId","recipientName","recipientEmail",status,"deliveryState") VALUES ($1,$2,$3,$4,$5,'FAILED','UNCERTAIN')`,
        [randomUUID(), campaignId, contactId, "Uncertain send", snapshotEmail],
      );
  }
  await page.goto("/history");
  const table = page.getByRole("region", { name: "Delivery history table" });
  const row = (name: string) =>
    table.getByRole("row").filter({
      has: page.getByText(name === "available" ? longName : name, {
        exact: true,
      }),
