  for (const name of ["available", "replied", "removed", "ordinary"]) {
    await expect(
      row(name).getByRole("button", { name: "Add to shortlist", exact: true }),
    ).toBeEnabled();
  }
  for (const name of ["shortlisted", "changed"]) {
    await expect(
      row(name).getByRole("button", { name: "In shortlist", exact: true }),
    ).toBeDisabled();
  }
  for (const name of ["archived", "pending"]) {
    await expect(
      row(name).getByRole("button", { name: /shortlist/ }),
    ).toBeDisabled();
  }
  await expect(
    row("replied").getByRole("button", { name: "Mark replied", exact: true }),
  ).toHaveCount(0);
  await expect(row("ordinary")).not.toContainText("Address suppressed");
  await expect(row("pending").getByRole("cell").nth(4)).toContainText("Sent");
  for (const state of ["queued", "failed", "cancelled"]) {
    await expect(row(state).getByRole("cell").nth(4)).toContainText(
      state.charAt(0).toUpperCase() + state.slice(1),
    );
    await expect(row(state).getByRole("button")).toHaveCount(0);
  }
  for (const [state, explanation] of [
    ["queued", "Waiting for delivery service"],
    ["failed", "Gmail submission failed. Please try again."],
  ]) {
    await row(state).getByRole("cell").nth(4).locator("[tabindex]").focus();
    await expect(page.getByRole("tooltip")).toContainText(explanation);
    await page.keyboard.press("Escape");
  }
  for (const theme of ["light", "dark"] as const) {
    await selectTheme(page, theme);
    const available = row("available");
    for (const width of [1280, 390, 320]) {
      await page.setViewportSize({ width, height: 900 });
      await expect(available).toBeVisible();
      if (width >= 860)
        await expect(table.getByRole("columnheader")).toHaveCount(6);
      else await expect(table.locator("thead")).toBeHidden();
      expect(
        await page.evaluate(() => document.documentElement.scrollWidth),
      ).toBeLessThanOrEqual(width);
      expect(
        await available.evaluate((el) =>
          [...el.querySelectorAll("td")].every(
            (cell) => cell.scrollWidth <= cell.clientWidth + 1,
          ),
        ),
      ).toBe(true);
    }
    const add = available.getByRole("button", {
      name: "Add to shortlist",
      exact: true,
    });
    await add.focus();
    await expect(add).toBeFocused();
    await expect(add).toHaveCSS("outline-style", "solid");
    await expect(page.getByRole("tooltip")).toContainText("Add to shortlist");
    const bounds = (await page.getByRole("tooltip").boundingBox())!;
    expect(bounds.x).toBeGreaterThanOrEqual(0);
    expect(bounds.x + bounds.width).toBeLessThanOrEqual(
      page.viewportSize()!.width,
    );
    await page.keyboard.press("Escape");
    await expect(page.getByRole("tooltip")).toHaveCount(0);
    const unavailable = row("archived").getByRole("button", {
      name: /shortlist/,
    });
    await unavailable.focus();
    await expect(unavailable).toBeDisabled();
    await expect(page.getByRole("tooltip")).toContainText(
      "Contact unavailable",
    );
    await page.keyboard.press("Escape");
    await expect(available.locator("time")).toHaveAttribute("datetime", sentAt);
    expect(
      (await new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa"]).analyze())
        .violations,
    ).toEqual([]);
  }
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const delayAction = async (route: Route) => {
    if (
      route.request().method() === "POST" &&
      route.request().headers()["next-action"]
    )
      await gate;
    await route.continue();
  };
  await page.route("**/history", delayAction);
  await row("replied")
    .getByRole("button", { name: "Add to shortlist", exact: true })
    .focus();
  await page.keyboard.press("Enter");
  try {
    const adding = row("replied").getByRole("button", {
      name: "Adding…",
      exact: true,
    });
    await expect(adding).toBeDisabled();
    await expect(adding).toHaveAttribute("aria-busy", "true");
  } finally {
    release();
  }
  await expect(
    row("replied").getByRole("button", { name: "In shortlist", exact: true }),
  ).toBeDisabled();
  await page.unroute("**/history", delayAction);
  await page.reload();
  await expect(
    row("replied").getByRole("button", { name: "In shortlist", exact: true }),
  ).toBeDisabled();
  const context = await browser.newContext({ timezoneId: "Pacific/Auckland" });
  try {
    await context.addCookies(await page.context().cookies());
    const localPage = await context.newPage();
    const hydrationErrors: string[] = [];
    localPage.on("pageerror", (error) => hydrationErrors.push(error.message));
    localPage.on("console", (message) => {
      if (message.type() === "error" && /hydrat/i.test(message.text()))
        hydrationErrors.push(message.text());
    });
    await localPage.goto(page.url());
    const time = localPage
      .getByRole("region", { name: "Delivery history table" })
      .getByRole("row")
      .filter({ hasText: longEmail })
      .locator("time");
    await expect(time.locator("span").nth(0)).toHaveText("Sep 3, 2026");
    await expect(time.locator("span").nth(1)).toHaveText("11:45 AM");
    expect(hydrationErrors).toEqual([]);
  } finally {
    await context.close();
  }
});

