for (const kind of ["Contact", "Template"] as const) {
  test(`${kind} confirmations: refresh, editing, repeated saves and toast lifetime`, async ({
    page,
    userId,
  }, testInfo) => {
    await pool.query('UPDATE "User" SET "preferredRoles"=$2 WHERE id=$1', [
      userId,
      ["Engineer"],
    ]);
    const route = kind === "Contact" ? "contacts" : "templates";
    await page.goto(`/${route}${kind === "Template" ? "?new=1" : ""}`);
    if (kind === "Contact") {
      await page.getByLabel("Email", { exact: true }).fill("[REDACTED_EMAIL]");
      await page.getByLabel("Name", { exact: true }).fill("Alex");
      await page.getByLabel("Job role", { exact: true }).fill("Engineer");
    } else {
      await page
        .getByLabel("Template name", { exact: true })
        .fill("Introduction");
      await page.getByLabel("Subject", { exact: true }).fill("Hello");
      await page.getByLabel("Message", { exact: true }).fill("Hi {{name}}");
    }
    const save = page.getByRole("button", {
      name: kind === "Contact" ? "Save contact" : "Save template",
      exact: true,
    });
    const toast = page.getByTestId("success-toast");
    const inline =
      kind === "Contact"
        ? page.getByRole("status").filter({ hasText: /^Contact saved ✓$/ })
        : page.getByTestId("success-confirmation");
    await save.click();
    await expect(toast).toContainText(`${kind} saved successfully.`);
    await expect(inline).toHaveText(
      kind === "Contact" ? "Contact saved ✓" : "Template saved.",
    );
    // A refreshed server list proves that the notification survived the refresh.
    const saved = await pool.query(
      `SELECT id FROM "${kind}" WHERE "userId"=$1`,
      [userId],
    );
    const edit = page.locator(`a[href="/${route}?edit=${saved.rows[0].id}"]`);
    if (kind === "Contact") await expect(edit).toBeVisible();
    await expect(toast).toBeVisible();
    await expect(
      page
        .getByRole("status")
        .filter({ hasText: `${kind} saved successfully.` }),
    ).toHaveCount(1);
    if (kind === "Template")
      expect(await inline.getAttribute("aria-live")).toBeNull();
    // Keep the transient toast visible while auditing both themes.
    await toast.hover();
    for (const theme of ["light", "dark"]) {
      await page.evaluate(
        (value) => document.documentElement.setAttribute("data-theme", value),
        theme,
      );
      const audit = new AxeBuilder({ page }).include(
        '[data-testid="success-toast"]',
      );
      if (kind === "Template")
        audit.include('[data-testid="success-confirmation"]');
      expect((await audit.analyze()).violations).toEqual([]);
      const box = await toast.boundingBox();
      expect(box!.x).toBeGreaterThanOrEqual(0);
      expect(box!.y).toBeGreaterThanOrEqual(0);
      expect(box!.x + box!.width).toBeLessThanOrEqual(
        page.viewportSize()!.width,
      );
      expect(box!.y + box!.height).toBeLessThanOrEqual(
        page.viewportSize()!.height,
      );
      await toast.screenshot({
        path: testInfo.outputPath(`success-${theme}.png`),
      });
    }
    await page.getByRole("button", { name: "Dismiss notification" }).focus();
    await page.keyboard.press("Enter");
    await expect(toast).toHaveCount(0);
    if (kind === "Contact") await expect(inline).toHaveCount(0);
    else await expect(inline).toBeVisible();
    await page
      .getByLabel(kind === "Contact" ? "Email" : "Template name", {
        exact: true,
      })
      .fill("draft");
    await expect(inline).toHaveCount(0);
    if (kind === "Contact") {
      await page.getByLabel("Email", { exact: true }).fill("[REDACTED_EMAIL]");
      await page.getByLabel("Name", { exact: true }).fill("   ");
      await page.getByLabel("Job role", { exact: true }).fill("Engineer");
      await save.click();
      await expect(page.getByLabel("Name", { exact: true })).toHaveAttribute(
        "aria-invalid",
        "true",
      );
      await expect(page.locator("#error-name")).not.toBeEmpty();
      await expect(page.getByLabel("Name", { exact: true })).toBeFocused();
      await expect(toast).toHaveCount(0);
      await expect(inline).toHaveCount(0);
    }
    // Discard the new draft and open the saved record.
    page.once("dialog", (dialog) => dialog.accept());
    if (kind === "Template")
      await page
        .getByRole("link", { name: "Back to templates", exact: true })
        .click();
    await edit.click();
    await expect(
      page.getByRole("heading", {
        name: `Edit ${kind.toLowerCase()}`,
        exact: true,
      }),
    ).toBeVisible();
    await page
      .getByLabel(kind === "Contact" ? "Name" : "Template name", {
        exact: true,
      })
      .fill("Updated");
    await page.clock.install();
    await page.clock.pauseAt(await page.evaluate(() => Date.now() + 1000));
    await save.click();
    await expect(toast).toBeVisible();
    if (kind === "Template") {
      await expect(page).toHaveURL(/\/templates$/);
      await expect(inline).toHaveCount(0);
    } else {
      await expect(inline).toBeVisible();
      await expect(save).toBeEnabled();
    }
    expect(
      (
        await pool.query(
          `SELECT name FROM "${kind}" WHERE "userId"=$1 AND id=$2`,
          [userId, saved.rows[0].id],
        )
      ).rows[0].name,
    ).toBe("Updated");
    await page.mouse.move(0, 0);
    await page.clock.runFor(4500);
    if (kind === "Template") await edit.click();
    await save.click();
    if (kind === "Template") await expect(page).toHaveURL(/\/templates$/);
    else await expect(save).toBeEnabled();
    await expect(toast).toBeVisible();
    await page.mouse.move(0, 0);
    await page.clock.runFor(2000);
    await expect(toast).toBeVisible();
    // Hover and keyboard focus independently pause the remaining six seconds.
    await toast.hover();
    await page.clock.runFor(7000);
    await expect(toast).toBeVisible();
    await page.getByRole("button", { name: "Dismiss notification" }).focus();
    await page.mouse.move(0, 0);
    await page.clock.runFor(7000);
    await expect(toast).toBeVisible();
    await (kind === "Template" ? edit : save).focus();
    await page.clock.runFor(6001);
    await expect(toast).toHaveCount(0);
    await expect(inline).toHaveCount(0);
    if (kind === "Contact") {
      await page
        .locator("form")
        .filter({ has: save })
        .getByRole("button", { name: "Engineer", exact: true })
        .click();
    } else {
      await edit.click();
      await page.getByRole("button", { name: "{{name}}", exact: true }).click();
    }
    await expect(inline).toHaveCount(0);
  });
}

