  await email.fill("[REDACTED_EMAIL]");
  await expect(note).toHaveText(
    "You’ve already emailed this address. You can still save this contact and send a follow-up.",
  );
  await expect(form.locator('[data-previously-emailed="true"]')).toHaveCount(1);
  await name.fill("Any name");
