    nodeId: root.nodeId,
    selector: "#contact-email",
  });
  await cdp.send("CSS.forcePseudoState", {
    nodeId,
    forcedPseudoClasses: ["autofill"],
  });
  for (const theme of ["light", "dark"]) {
