    await email.fill("[REDACTED_EMAIL]");
    await expect(note).toBeEmpty();
    await settleTheme(page);
    expect(
      await name.evaluate((el) => getComputedStyle(el).backgroundColor),
    ).toBe(normalNameColor);
    expect(
      await email.evaluate((el) =>
        getComputedStyle(el).getPropertyValue("--contact-input-background"),
      ),
    ).not.toBe(warningColor);
    expect(
      await email.evaluate((el) => getComputedStyle(el).boxShadow),
    ).not.toBe(warningShadow);
    await email.fill("[REDACTED_EMAIL]");
    await expect(note).not.toBeEmpty();
  }
  await cdp.detach();
  await form.getByLabel("Job role", { exact: true }).fill("Engineer");
  await form.getByRole("button", { name: "Save contact", exact: true }).click();
  await expect(email).toHaveValue("");
