test("all 24 permutations, repeat selection, reload and cross-tab", async ({
  page,
  context,
  auditUser,
}, info) => {
  test.skip(info.project.name !== "desktop");
  void auditUser;
  test.setTimeout(180000);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/settings");
  function permutations<T>(items: T[]): T[][] {
    return items.length
      ? items.flatMap((item, i) =>
          permutations(items.filter((_, j) => i !== j)).map((rest) => [
            item,
            ...rest,
          ]),
        )
      : [[]];
  }
  for (const order of permutations([...themes]))
    for (const [label, appearance, mode] of order) {
      await choose(page, label);
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
    }
  await choose(page, themes[3][0]);
  await choose(page, themes[3][0]);
  await page.reload();
  await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
  const other = await context.newPage();
  await other.goto("/settings");
  await choose(other, themes[0][0]);
  await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    "purple",
  );
  await page
    .getByRole("button", { name: "Help with settings", exact: true })
    .click();
  await expect(page.getByRole("dialog")).toBeVisible();
  await choose(other, themes[3][0]);
  await expect(page.locator("html")).toHaveAttribute(
    "data-appearance",
    "vercel",
  );
  await expect(page.getByRole("dialog")).toBeVisible();
  await choose(other, themes[0][0]);
  await page
    .getByRole("button", { name: "Close tutorial", exact: true })
    .click();
  await other.close();
  for (const colorScheme of ["light", "dark"] as const) {
    await page.emulateMedia({ colorScheme });
    await page.reload();
    await expect(page.locator("html")).toHaveAttribute("data-theme", "light");
  }
  await page.emulateMedia({ forcedColors: "active" });
  await page.screenshot({
    path: info.outputPath("forced-colors.png"),
    fullPage: true,
    caret: "initial",
  });
  await page.emulateMedia({ forcedColors: "none", media: "print" });
  await page.pdf({ path: info.outputPath("settings-print.pdf") });
});

