    it.each([false, true])(
      "crosses a renewal boundary, preserves grace usage, and recovers only with settlement (%s)",
      async (recover) => {
        vi.useFakeTimers({ toFake: ["Date"] });
        try {
          vi.setSystemTime(new Date("2026-10-15T00:00:00Z"));
          startsAt = "2026-10-01T00:00:00Z";
          endsAt = "2026-11-01T00:00:00Z";
          provider.previous_billing_date = startsAt;
          provider.next_billing_date = endsAt;
          await settle();
          const template = await db.template.create({
            data: {
              userId,
              name: "Fixture",
              subject: "Fixture",
              body: "Fixture",
            },
          });
          const campaign = await db.campaign.create({
            data: { userId, templateId: template.id, status: "QUEUED" },
          });
          const contact = await db.contact.create({
            data: { userId, name: "Fixture", email: "[REDACTED_EMAIL]" },
          });
          async function acceptedSend() {
            const current = await user();
            const specs = resolveUsagePeriods(current);
            const send = await db.send.create({
              data: {
                campaignId: campaign.id,
                contactId: contact.id,
                status: "SENT",
                deliveryState: "DONE",
                sentAt: new Date(),
                gmailMessageId: randomUUID(),
              },
            });
            await withUsageTransaction(db, userId, (owner) =>
              adoptUsageReservation(owner, {
                sendId: send.id,
                deliveryKey: send.id,
                specs,
                status: "CONFIRMED",
                chargedAt: new Date(),
                confirmedAt: new Date(),
              }),
            );
            return specs.monthly.key;
          }
          const firstKey = await acceptedSend();
          vi.setSystemTime(new Date("2026-11-01T00:00:00Z"));
          await processBillingEvent(
            (await receive("payment.failed", payment("failed"))).id,
          );
          expect(
            resolveUsagePeriods(await user(), new Date("2026-10-31T23:59:59Z"))
              .monthly.key,
          ).toBe(firstKey);
          provider.status = "past_due";
          const deadline = "2026-11-04T00:00:00Z";
          await processBillingEvent(
            (
              await receive("subscription.past_due", {
                ...provider,
                past_due_ends_at: deadline,
              })
            ).id,
          );
          await reconcileBillingSubscription(userId, subscriptionId); // GET lacks the signed deadline
          expect((await user()).gracePeriodEnd).toEqual(new Date(deadline));
          expect(await acceptedSend()).toBe(firstKey);
          const old = await db.usagePeriod.findFirstOrThrow({
            where: { userId, key: firstKey },
          });
          expect(old.sent).toBe(2);
          expect(
            getEffectivePlan(
              await user(),
              new Date(new Date(deadline).getTime() - 1),
            ),
          ).toBe("PAID");
          if (!recover) {
            vi.setSystemTime(new Date(deadline));
            expect(getEffectivePlan(await user())).toBe("FREE");
            const expired = await user();
            expect(resolveUsagePeriods(expired).monthly.limit).toBe(15);
            return;
          }
          vi.setSystemTime(new Date("2026-11-02T00:00:00Z"));
          provider.status = "active";
          provider.previous_billing_date = endsAt;
          provider.next_billing_date = "2026-12-01T00:00:00Z";
          await processBillingEvent(
            (await receive("subscription.active", provider)).id,
          );
          expect((await user()).currentPeriodEnd).toEqual(new Date(endsAt));
          expect((await user()).gracePeriodEnd).toEqual(new Date(deadline));
          await processBillingEvent(
            (
              await receive(
                "payment.succeeded",
                payment("succeeded", endsAt, "2026-12-01T00:00:00Z"),
              )
            ).id,
          );
          const current = await user();
          expect(current.gracePeriodEnd).toBeNull();
          const specs = resolveUsagePeriods(current);
          const buckets = await withUsageTransaction(db, userId, (owner) =>
            ensureUsagePeriods(owner, specs),
          );
          expect(buckets.monthly.key).not.toBe(firstKey);
          expect(buckets.monthly.sent).toBe(1); // grace send falls inside the newly settled period
          expect(buckets.monthly.importedSent).toBe(1);
          expect(
            (
              await db.usagePeriod.findFirstOrThrow({
                where: { userId, key: firstKey },
              })
            ).sent,
          ).toBe(2);
        } finally {
          vi.useRealTimers();
        }
      },
    );

