import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  BILLING_PRICES as PUBLIC_PRICES,
  PRICE_DESCRIPTION,
} from "@/lib/pricing";
import { BILLING_PRICES, billingConfig } from "@/lib/billing/config";
import { billingCheckoutUrl } from "@/lib/billing/dodo";

const env = {
  DODO_PAYMENTS_ENVIRONMENT: "test_mode",
  DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
  DODO_PAYMENTS_WEBHOOK_KEY: "fixture-secret",
  DODO_PAYMENTS_BUSINESS_ID: "bus_fixture",
  DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_fixture",
  AUTH_URL: "http://localhost:3000",
};

describe("billing configuration", () => {
  it("shares exact public prices with server product validation", () => {
    expect(BILLING_PRICES).toBe(PUBLIC_PRICES);
    expect(PUBLIC_PRICES).toEqual({ INR: 29900, USD: 599 });
    expect(PRICE_DESCRIPTION).toBe(
      "₹299/month for India; US$5.99/month globally",
    );
  });
  it("requires an explicit mode and every server-side binding", () => {
    expect(billingConfig(env).environment).toBe("test_mode");
    for (const key of Object.keys(env)) {
      expect(() => billingConfig({ ...env, [key]: "" })).toThrow();
    }
    for (const mode of ["test", undefined])
      expect(() =>
        billingConfig({ ...env, DODO_PAYMENTS_ENVIRONMENT: mode }),
      ).toThrow();
    expect(() =>
      billingConfig({
        ...env,
        DODO_PAYMENTS_BASE_URL: "https://live.dodopayments.com",
      }),
    ).toThrow();
    expect(() =>
      billingConfig({
        ...env,
        DODO_PAYMENTS_CUSTOM_HEADERS: "Authorization: other",
      }),
    ).toThrow();
  });
  it("accepts live mode only with a secure return origin", () => {
    expect(() =>
      billingConfig({ ...env, DODO_PAYMENTS_ENVIRONMENT: "live_mode" }),
    ).toThrow();
    expect(
      billingConfig({
        ...env,
        DODO_PAYMENTS_ENVIRONMENT: "live_mode",
        AUTH_URL: "https://mailloop.in",
      }).environment,
    ).toBe("live_mode");
  });
  it("uses fixed validated origins and refuses unsafe URLs", () => {
    expect(
      billingConfig({ ...env, APP_ORIGIN: "https://billing-test.example.com" })
        .origin,
    ).toBe("https://billing-test.example.com");
    for (const url of [
      "http://example.com",
      "https://u:[REDACTED_EMAIL]",
      "https://example.com/path",
      "https://example.com/?x=1",
      "javascript:alert(1)",
    ])
      expect(() => billingConfig({ ...env, AUTH_URL: url })).toThrow();
  });
  it("allows only the checkout host for the selected mode", () => {
    expect(
      billingCheckoutUrl(
        "https://test.checkout.dodopayments.com/session/cks_fixture",
        "test_mode",
      ),
    ).toContain("/session/");
    expect(
      billingCheckoutUrl(
        "https://checkout.dodopayments.com/session/cks_fixture",
        "live_mode",
      ),
    ).toContain("/session/");
    for (const url of [
      "https://checkout.dodopayments.com/session/x",
      "https://test.checkout.dodopayments.com.evil.com",
      "http://test.checkout.dodopayments.com",
      "https://u:[REDACTED_EMAIL]",
    ])
      expect(() => billingCheckoutUrl(url, "test_mode")).toThrow();
    for (const url of [
      "https://test.checkout.dodopayments.com/session/x",
      "https://checkout.dodopayments.com.evil.com/session/x",
      "http://checkout.dodopayments.com/session/x",
      "https://u:[REDACTED_EMAIL]/session/x",
    ])
      expect(() => billingCheckoutUrl(url, "live_mode")).toThrow();
  });
});

const catalog = vi.hoisted(() => ({ product: vi.fn(), localized: vi.fn() }));
vi.mock("@/lib/billing/dodo", async (original) => ({
  ...(await original<typeof import("@/lib/billing/dodo")>()),
  dodoClient: () => ({
    products: {
      retrieve: catalog.product,
      localizedPrices: { list: catalog.localized },
    },
  }),
}));
import {
  fixtureProduct,
  fixtureLocalizedPrices,
} from "./helpers/dodo-fixtures";
import { verifyBillingProduct } from "@/lib/billing/store";
describe("checkout catalog eligibility", () => {
  beforeEach(() => {
    for (const [key, value] of Object.entries(env)) vi.stubEnv(key, value);
    catalog.product.mockResolvedValue(fixtureProduct());
    catalog.localized.mockResolvedValue(fixtureLocalizedPrices());
  });
  afterEach(() => vi.unstubAllEnvs());
  it("verifies the exact monthly USD base and India country price including tax", async () => {
    await expect(verifyBillingProduct()).resolves.toMatchObject({
      product_id: "pdt_fixture",
    });
    expect(catalog.localized).toHaveBeenCalledWith("pdt_fixture");
  });
  it.each([
    { currency: "INR" },
    { price: 600 },
    { price: 800 }, // Former advertised USD price must fail new checkout validation.
    { tax_inclusive: false },
    { tax_inclusive: undefined },
    { payment_frequency_count: 2 },
    { payment_frequency_interval: "Year" },
    { subscription_period_count: 1 },
    { subscription_period_interval: "Month" },
    { trial_period_days: 3 },
    { trial_amount: 100 },
    { discount: 1 },
    { discount_bps: 1 },
    { purchasing_power_parity: true },
    { type: "usage_based_price" },
  ])("rejects price drift %j", async (change) => {
    const product = fixtureProduct();
    catalog.product.mockResolvedValue({
      ...product,
      price: { ...product.price, ...change },
    });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it.each([
    { business_id: "bus_other" },
    { product_id: "pdt_other" },
    { is_recurring: false },
    { pricing_mode: "by_currency" },
    { addons: ["addon"] },
  ])("rejects product drift %j", async (change) => {
    catalog.product.mockResolvedValue({ ...fixtureProduct(), ...change });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it.each([
    { amount: 29901 },
    { amount: 19900 }, // Former advertised India price must fail new checkout validation.
    { currency: "USD" },
    { country_code: "US" },
    { mode: "by_currency" },
    { product_id: "other" },
  ])("rejects country rule drift %j", async (change) => {
    catalog.localized.mockResolvedValue({
      items: [{ ...fixtureLocalizedPrices().items[0], ...change }],
    });
    await expect(verifyBillingProduct()).rejects.toMatchObject({
      code: "BILLING_PRODUCT_MISMATCH",
    });
  });
  it("rejects missing or additional country rules", async () => {
    for (const items of [
      [],
      [...fixtureLocalizedPrices().items, ...fixtureLocalizedPrices().items],
    ]) {
      catalog.localized.mockResolvedValue({ items });
      await expect(verifyBillingProduct()).rejects.toThrow();
    }
  });
});

import { beforeEach, describe, expect, it, vi } from "vitest";
const mocks = vi.hoisted(() => ({
  subscriptions: vi.fn(),
  attempts: vi.fn(),
  users: vi.fn(),
  inbox: vi.fn(),
  count: vi.fn(),
  current: vi.fn(),
  touch: vi.fn(),
  cleanup: vi.fn(),
  process: vi.fn(),
  reconcile: vi.fn(),
  cancel: vi.fn(),
  checkout: vi.fn(),
  deletion: vi.fn(),
  config: vi.fn(),
}));
vi.mock("@/lib/billing/config", () => ({ billingConfig: mocks.config }));
vi.mock("@/lib/billing/lifecycle", () => ({
  processBillingEvent: mocks.process,
  reconcileBillingSubscription: mocks.reconcile,
}));
vi.mock("@/lib/billing/cancel", () => ({
  recoverBillingCancellation: mocks.cancel,
}));
vi.mock("@/lib/billing/checkout", () => ({
  recoverCheckoutAttempt: mocks.checkout,
}));
vi.mock("@/lib/billing/deletion", () => ({
  stopBillingForDeletion: mocks.deletion,
}));
vi.mock("@/lib/db", () => ({
  db: {
    billingSubscription: {
      findMany: mocks.subscriptions,
      findFirst: mocks.current,
      updateMany: mocks.touch,
    },
    checkoutAttempt: { findMany: mocks.attempts, updateMany: mocks.touch },
    user: { findMany: mocks.users },
    billingWebhookEvent: { findMany: mocks.inbox, count: mocks.count },
    billingRateLimit: { deleteMany: mocks.cleanup },
  },
}));
import {
  reconcileBilling,
  reconcileBillingPage,
  recoverBilling,
  retryBillingInbox,
} from "@/lib/billing/jobs";
beforeEach(() => {
  vi.clearAllMocks();
  mocks.subscriptions.mockResolvedValue([]);
  mocks.attempts.mockResolvedValue([]);
  mocks.users.mockResolvedValue([]);
  mocks.inbox.mockResolvedValue([]);
  mocks.current.mockResolvedValue({
    status: "ACTIVE",
    settledPaymentId: "pay_fixture",
    periodEnd: new Date(Date.now() + 86400_000),
  });
  mocks.count.mockResolvedValue(0);
});
describe("durable billing jobs", () => {
  it("paginates with a stable cutoff, continues failures, and reports missing settlement", async () => {
    const rows = Array.from({ length: 50 }, (_, i) => ({
      id: String(i).padStart(3, "0"),
      userId: "owner",
      dodoSubscriptionId: `sub_${i}`,
    }));
    mocks.subscriptions.mockResolvedValueOnce(rows).mockResolvedValueOnce([]);
    mocks.reconcile.mockRejectedValueOnce(new Error("provider offline"));
    mocks.current.mockResolvedValue({
      status: "ACTIVE",
      settledPaymentId: null,
    });
    const cutoff = new Date().toISOString();
    const first = await reconcileBillingPage(null, cutoff);
    expect(first).toEqual({
      cursor: "049",
      scanned: 50,
      failed: 1,
      missingSettlement: 49,
    });
    expect(await reconcileBillingPage(first.cursor, cutoff)).toEqual({
      cursor: null,
      scanned: 0,
      failed: 0,
      missingSettlement: 0,
    });
    expect(mocks.subscriptions).toHaveBeenLastCalledWith(
      expect.objectContaining({
        take: 50,
        where: expect.objectContaining({
          id: { gt: "049" },
          createdAt: { lte: new Date(cutoff) },
        }),
      }),
    );
  });
  it("keeps processing the inbox after one receipt fails", async () => {
    mocks.inbox.mockResolvedValue([{ id: "failed" }, { id: "succeeded" }]);
    mocks.process.mockRejectedValueOnce(new Error("provider unavailable"));
    expect(await retryBillingInbox()).toEqual({ processed: 1, pending: 1 });
    expect(mocks.process).toHaveBeenCalledTimes(2);
  });
  it("continues checkout and subscription recovery after individual failures", async () => {
    mocks.users.mockResolvedValue([{ id: "deleted" }]);
    mocks.deletion.mockRejectedValueOnce(new Error("unavailable"));
    mocks.attempts.mockResolvedValue([{ userId: "owner", id: "attempt" }]);
    mocks.checkout.mockRejectedValueOnce(new Error("uncertain"));
    mocks.subscriptions.mockResolvedValue([
      { userId: "owner", dodoSubscriptionId: "sub_1" },
      { userId: "owner", dodoSubscriptionId: "sub_2" },
    ]);
    mocks.reconcile.mockRejectedValueOnce(new Error("unavailable"));
    expect(await recoverBilling()).toMatchObject({
      failed: 1,
      subscriptions: 2,
    });
    expect(mocks.touch).toHaveBeenCalledTimes(2);
    expect(mocks.reconcile).toHaveBeenCalledTimes(2);
  });
  it("reports an incomplete nightly run without a job service", async () => {
    mocks.subscriptions.mockResolvedValueOnce([
      { id: "row", userId: "owner", dodoSubscriptionId: "sub" },
    ]);
    mocks.reconcile.mockRejectedValueOnce(new Error("provider offline"));
    const diagnostic = vi.spyOn(console, "info").mockImplementation(() => {});
    try {
      await expect(reconcileBilling()).rejects.toThrow(
        "BILLING_NIGHTLY_INCOMPLETE",
      );
      expect(diagnostic).toHaveBeenCalledWith(
        expect.stringContaining('"event":"nightly"'),
      );
    } finally {
      diagnostic.mockRestore();
    }
  });
  it("completes nightly reconciliation without an event publisher", async () => {
    expect(await reconcileBilling()).toEqual({
      scanned: 0,
      failed: 0,
      missingSettlement: 0,
    });
  });
});

import { randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  createIsolatedDatabase,
  databaseTestsEnabled,
} from "./helpers/foundation-db";

describe.runIf(databaseTestsEnabled)("Dodo test billing migration", () => {
  let fixture: Awaited<ReturnType<typeof createIsolatedDatabase>>;
  beforeAll(async () => {
    fixture = await createIsolatedDatabase();
    try {
      for (const name of fixture.migrations) await fixture.apply(name);
    } catch (error) {
      await fixture.cleanup();
      throw error;
    }
  });
  afterAll(async () => {
    if (fixture) await fixture.cleanup();
  });

  it("preserves existing billing rows during the additive completion migration and disables checkout", async () => {
    const upgrade = await createIsolatedDatabase();
    try {
      const completion = "20261020020000_dodo_billing_completion";
      for (const migration of upgrade.migrations) {
        if (migration === completion) break;
        await upgrade.apply(migration);
      }
      await upgrade.client.query(
        `INSERT INTO "BillingWebhookEvent" (id,"webhookId","eventType","businessId","occurredAt","normalizedData","payloadHash",state) VALUES ('receipt','wh_existing','payment.succeeded','business',now(),'{}',repeat('a',64),'PROCESSED')`,
      );
      await upgrade.client.query(
        `INSERT INTO "BillingSubscription" (id,"dodoSubscriptionId","dodoCustomerId","productId",status,"settledPaymentId","paymentConfirmedAt","periodStart","periodEnd","updatedAt") VALUES ('existing','sub_existing','cus_existing','pdt_existing','ACTIVE','pay_existing',now(),now()-interval '1 day',now()+interval '29 days',now())`,
      );
      const before = (
        await upgrade.client.query(`SELECT * FROM "BillingWebhookEvent"`)
      ).rows;
      await upgrade.apply(completion);
      expect(
        (await upgrade.client.query(`SELECT * FROM "BillingWebhookEvent"`))
          .rows,
      ).toEqual(before);
      expect(
        (
          await upgrade.client.query(
            `SELECT "billingCheckoutEnabled" FROM "SystemControl" WHERE key='global'`,
          )
        ).rows,
      ).toEqual([{ billingCheckoutEnabled: false }]);
      expect(
        (
          await upgrade.client.query(
            `SELECT "settledPaymentId","cancelRequestedAt" FROM "BillingSubscription" WHERE id='existing'`,
          )
        ).rows,
      ).toEqual([
        { settledPaymentId: "pay_existing", cancelRequestedAt: null },
      ]);
    } finally {
      await upgrade.cleanup();
    }
  });
  it("enforces UUID rate-limit IDs, owner and operation identity, and positive minute counts", async () => {
    const userId = randomUUID();
    await fixture.client.query(`INSERT INTO "User" (id,email) VALUES ($1,$2)`, [
      userId,
      userId + "@example.test",
    ]);
    const insert = (id: string, operation = "status", count = 1) =>
      fixture.client.query(
        `INSERT INTO "BillingRateLimit" (id,"userId",operation,"minuteBucket","requestCount") VALUES ($1,$2,$3,date_trunc('minute',now()),$4)`,
        [id, userId, operation, count],
      );
    await expect(insert("not-a-uuid")).rejects.toMatchObject({ code: "22P02" });
    await expect(
      insert(randomUUID(), "foreign-operation"),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(insert(randomUUID(), "status", 0)).rejects.toMatchObject({
      code: "23514",
    });
    await insert(randomUUID());
    await expect(insert(randomUUID())).rejects.toMatchObject({ code: "23505" });
    await fixture.client.query(`DELETE FROM "User" WHERE id=$1`, [userId]);
    expect(
      (
        await fixture.client.query(
          `SELECT * FROM "BillingRateLimit" WHERE "userId"=$1`,
          [userId],
        )
      ).rows,
    ).toEqual([]);
  });

  it("retains subscription and checkout evidence when the owner is deleted", async () => {
    await fixture.client.query(
      `INSERT INTO "User" (id,email) VALUES ('owner','[REDACTED_EMAIL]')`,
    );
    await fixture.client.query(
      `INSERT INTO "BillingSubscription" (id,"userId","ownerIdSnapshot","dodoSubscriptionId","dodoCustomerId","productId",status,"updatedAt") VALUES ('sub','owner','owner','sub_test','cus_test','pdt_test','CANCELLED',now())`,
    );
    await fixture.client.query(
      `INSERT INTO "CheckoutAttempt" (id,"userId","ownerIdSnapshot","idempotencyKey","productId","billingCountry","expiresAt",status) VALUES ('attempt','owner','owner','key','pdt_test','IN',now()+interval '1 day','COMPLETED')`,
    );
    await fixture.client.query(`DELETE FROM "User" WHERE id='owner'`);
    for (const table of ["BillingSubscription", "CheckoutAttempt"]) {
      const result = await fixture.client.query(
        `SELECT "userId","ownerIdSnapshot" FROM "${table}"`,
      );
      expect(result.rows).toEqual([{ userId: null, ownerIdSnapshot: "owner" }]);
    }
  });

  it("enforces one unresolved checkout and paired provider binding", async () => {
    await fixture.client.query(
      `INSERT INTO "User" (id,email) VALUES ('concurrent','[REDACTED_EMAIL]')`,
    );
    const insert = (id: string) =>
      fixture.client.query(
        `INSERT INTO "CheckoutAttempt" (id,"userId","idempotencyKey","productId","billingCountry","expiresAt",status) VALUES ($1,'concurrent',$1,'pdt_test','IN',now()+interval '1 day','UNKNOWN')`,
        [id],
      );
    await insert("first");
    await expect(insert("second")).rejects.toMatchObject({
      code: "23505",
      constraint: "CheckoutAttempt_one_open_per_user",
    });
    await fixture.client.query(
      `UPDATE "SystemControl" SET "dodoEnvironment"='live_mode',"dodoBusinessId"='business' WHERE key='global'`,
    );
    await expect(
      fixture.client.query(
        `UPDATE "SystemControl" SET "dodoEnvironment"='other_mode' WHERE key='global'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await expect(
      fixture.client.query(
        `UPDATE "SystemControl" SET "dodoEnvironment"=NULL,"dodoBusinessId"='business' WHERE key='global'`,
      ),
    ).rejects.toMatchObject({ code: "23514" });
    await fixture.client.query(
      `UPDATE "SystemControl" SET "dodoEnvironment"='test_mode',"dodoBusinessId"='business' WHERE key='global'`,
    );
  });

  it("preserves a pre-existing checkout while allowing country to be collected later", async () => {
    const upgrade = await createIsolatedDatabase();
    try {
      const migration = "20261020010000_hosted_checkout_country";
      for (const name of upgrade.migrations) {
        if (name === migration) break;
        await upgrade.apply(name);
      }
      await upgrade.client.query(
        `INSERT INTO "CheckoutAttempt" (id,"idempotencyKey","productId","billingCountry","expiresAt",status,"dodoSessionId","checkoutUrl") VALUES ('existing','existing','pdt_test','IN',now()+interval '1 day','READY','cks_existing','https://test.checkout.dodopayments.com/session/existing')`,
      );
      const before = await upgrade.client.query(
        `SELECT * FROM "CheckoutAttempt" WHERE id='existing'`,
      );
      await upgrade.apply(migration);
      expect(
        (
          await upgrade.client.query(
            `SELECT * FROM "CheckoutAttempt" WHERE id='existing'`,
          )
        ).rows,
      ).toEqual(before.rows);
      expect(
        (
          await upgrade.client.query(
            `INSERT INTO "CheckoutAttempt" (id,"idempotencyKey","productId","expiresAt") VALUES ('hosted','hosted','pdt_test',now()+interval '1 day') RETURNING "billingCountry"`,
          )
        ).rows,
      ).toEqual([{ billingCountry: null }]);
    } finally {
      await upgrade.cleanup();
    }
  });
});

