    expect(ring).toContain("Finished");
    expect(ring).toContain("with failures");
    expect(ring).not.toContain("ALL SENT");
  });
  it.each([{ draft: true }, { queued: 1 }, { review: 1 }, { sent: 0 }])(
    "does not claim success for %j",
    (props) => {
      expect(renderToStaticMarkup(separate(props))).not.toContain("ALL SENT");
    },
  );
});

import { describe, expect, it } from "vitest";
import {
  getRoleShortcutLimit,
  roleShortcutError,
  normalizeRole,
} from "@/lib/roles";
import { preferredRolesSchema } from "@/lib/validation";

const legacy = Array.from({ length: 20 }, (_, i) => `Role ${i}`);
describe("saved role shortcuts", () => {
  it.each([
    ["FREE", 2],
    ["PAID", 8],
  ] as const)("limits %s to %i arbitrary shortcuts", (plan, limit) => {
    const roles = legacy.slice(0, limit);
    expect(getRoleShortcutLimit(plan)).toBe(limit);
    expect(roleShortcutError(plan, roles, [])).toBeUndefined();
    expect(roleShortcutError(plan, [...roles, "Extra"], [])).toContain(
      `${limit}`,
    );
    expect(roleShortcutError(plan, [], roles)).toBeUndefined();
  });
  it("retains, reorders and removes legacy shortcuts but blocks replacements above the limit", () => {
    for (const plan of ["FREE", "PAID"] as const) {
      expect(roleShortcutError(plan, legacy, legacy)).toBeUndefined();
      expect(
        roleShortcutError(plan, legacy.slice(0, 10).reverse(), legacy),
      ).toBeUndefined();
      expect(
        roleShortcutError(plan, [...legacy.slice(0, 9), "Extra"], legacy),
      ).toBeDefined();
      expect(roleShortcutError(plan, ["New title"], legacy)).toBeUndefined();
    }
  });
  it("normalizes retained shortcuts and rejects duplicate or invalid text", () => {
    expect(normalizeRole("  Product   DESIGNER ")).toBe("product designer");
    expect(
      roleShortcutError(
        "FREE",
        legacy.map((role) => role.toUpperCase()),
        legacy,
      ),
    ).toBeUndefined();
    expect(preferredRolesSchema.parse([])).toEqual([]);
    expect(preferredRolesSchema.parse(["  Researcher  "])).toEqual([
      "Researcher",
    ]);
    for (const roles of [[" "], ["Engineer", " ENGINEER "], ["x".repeat(161)]])
      expect(preferredRolesSchema.safeParse(roles).success).toBe(false);
    expect(preferredRolesSchema.parse(legacy)).toHaveLength(20);
  });
});

import "dotenv/config";
import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { Client } from "pg";
import { describe, expect, it } from "vitest";
const enabled = process.env.MAILLOOP_DB_TESTS === "1";
if (
  enabled &&
  !["localhost", "127.0.0.1"].includes(
    new URL(process.env.DATABASE_URL!).hostname,
  )
)
  throw Error("Local database required");
describe.runIf(enabled)("send-only additive upgrade", () => {
  it("keeps legacy grants unknown, preserves send evidence and removes obsolete suppression storage", async () => {
    const client = new Client({ connectionString: process.env.DATABASE_URL });
    await client.connect();
    try {
      await client.query("BEGIN");
      const schema = `send_only_${randomUUID().replaceAll("-", "")}`;
      await client.query(`CREATE SCHEMA "${schema}"`);
      await client.query(`SET LOCAL search_path TO "${schema}"`);
      await client.query(
        `CREATE TABLE "User" (id text PRIMARY KEY, "gmailAuthorized" boolean); CREATE TABLE "Send" (id text PRIMARY KEY, status text); INSERT INTO "User" VALUES ('owner',true); INSERT INTO "Send" VALUES ('legacy','SENT');`,
      );
      await client.query(
        await readFile(
          "prisma/migrations/20261016000000_send_only_v1/migration.sql",
          "utf8",
        ),
      );
      expect((await client.query('SELECT * FROM "User"')).rows[0]).toEqual({
        id: "owner",
        gmailAuthorized: true,
        gmailScopes: [],
        gmailSendOnlyConsentAt: null,
      });
      expect((await client.query('SELECT * FROM "Send"')).rows[0]).toEqual({
        id: "legacy",
        status: "SENT",
        replyMarkedAt: null,
        bouncedAt: null,
        sentConfirmedManuallyAt: null,
      });
      await client.query(
        `INSERT INTO "RecipientSuppression" (id,"userId",email,reason) VALUES ('suppression','owner','[REDACTED_EMAIL]','DO_NOT_CONTACT')`,
      );
      await client.query(`DELETE FROM "User" WHERE id='owner'`);
      expect(
        (await client.query('SELECT * FROM "RecipientSuppression"')).rows,
      ).toEqual([]);
      await client.query(`
        INSERT INTO "User" (id, "gmailAuthorized") VALUES ('remaining', true);
        INSERT INTO "RecipientSuppression" (id,"userId",email,reason)
        VALUES ('obsolete','remaining','[REDACTED_EMAIL]','MANUAL_BOUNCE');
      `);
      await client.query(
        (
          await readFile(
            "prisma/migrations/20261016020000_remove_recipient_suppression/migration.sql",
            "utf8",
          )
        )
          .replace(/^BEGIN;\s*/m, "")
          .replace(/COMMIT;\s*$/, ""),
      );
      expect(
        (
          await client.query(
            "SELECT to_regclass('\"RecipientSuppression\"') AS table_name, to_regtype('\"SuppressionReason\"') AS enum_name",
          )
        ).rows[0],
      ).toEqual({ table_name: null, enum_name: null });
      expect((await client.query('SELECT * FROM "User"')).rows).toEqual([
        {
          id: "remaining",
          gmailAuthorized: true,
          gmailScopes: [],
          gmailSendOnlyConsentAt: null,
        },
      ]);
      expect(
        (await client.query('SELECT * FROM "Send"')).rows[0],
      ).toMatchObject({
        id: "legacy",
        status: "SENT",
        bouncedAt: null,
      });
    } finally {
      await client.query("ROLLBACK");
      await client.end();
    }
  });
});

