import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { boundary, usageFixture, usageOwner } from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { backfillUsageOwner } from "@/lib/usage-backfill";
import { clearCompletedHistory } from "@/lib/history";

describe.runIf(databaseTestsEnabled)("resumable usage backfill", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
    await boundary.db.systemControl.update({
      where: { key: "global" },
      data: { sendingEnabled: false },
    });
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  async function legacy() {
    const f = await usageOwner(boundary.db, { ready: false });
    const input = await f.input();
    const campaign = await boundary.db.campaign.create({
      data: { userId: f.user.id, templateId: f.template.id, status: "SENDING" },
    });
    const cutover = new Date(Date.now());
    const base = { campaignId: campaign.id, contactId: input.recipientIds[0] };
    const succeeded = await boundary.db.send.create({
      data: {
        ...base,
        status: "SENT",
        deliveryState: "DONE",
        sentAt: new Date(+cutover - 1000),
        attemptedAt: new Date(+cutover - 2000),
      },
    });
    await boundary.db.send.create({
      data: {
        ...base,
        status: "REPLIED",
        deliveryState: "DONE",
        sentAt: new Date(+cutover - 3000),
      },
    });
    const queued = await boundary.db.send.create({ data: base });
    const uncertain = await boundary.db.send.create({
      data: {
        ...base,
        status: "FAILED",
        deliveryState: "UNCERTAIN",
        attemptedAt: new Date(+cutover - 86400001),
      },
    });
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: f.user.id,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: cutover,
        sentAt: new Date(+cutover - 4000),
      },
    });
    return { ...f, succeeded, queued, uncertain, cutover };
  }
  it("rolls back a full dry run without checkpoints or queue changes", async () => {
    const f = await legacy();
    expect((await backfillUsageOwner(f.user.id, f.cutover)).ready).toBe(true);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(0);
    expect(
      await boundary.db.usageImportEvidence.count({
        where: { userId: f.user.id },
      }),
    ).toBe(0);
    expect(
      await boundary.db.user.findUnique({ where: { id: f.user.id } }),
    ).toMatchObject({ usageBackfillVersion: 0, usageCutoverAt: null });
    expect(
      await boundary.db.send.findFirst({
        where: { id: f.queued.id, campaign: { userId: f.user.id } },
      }),
    ).toMatchObject({ queueExpiresAt: null });
  });
  it("backfills twice identically, preserves fallback provenance, and never extends original expiry", async () => {
    const f = await legacy();
    await backfillUsageOwner(f.user.id, f.cutover, true);
    const read = async () => ({
      periods: await boundary.db.usagePeriod.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
      evidence: await boundary.db.usageImportEvidence.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
      reservations: await boundary.db.usageReservation.findMany({
        where: { userId: f.user.id },
        orderBy: { id: "asc" },
      }),
    });
    const first = await read();
    await backfillUsageOwner(f.user.id, new Date(+f.cutover + 600000), true);
    expect(await read()).toEqual(first);
    expect(first.evidence.map((e) => e.timestampSource).sort()).toEqual([
      "attemptedAt",
      "sentAt",
      "sentAt",
    ]);
    expect(
      await boundary.db.send.findFirst({
        where: { id: f.queued.id, campaign: { userId: f.user.id } },
      }),
    ).toMatchObject({ queueExpiresAt: new Date(+f.cutover + 86400000) });
    expect(
      first.reservations.find((r) => r.sendId === f.uncertain.id),
    ).toMatchObject({
      chargedAt: f.uncertain.attemptedAt,
      status: "UNCERTAIN",
    });
    await clearCompletedHistory(f.user.id);
    await backfillUsageOwner(f.user.id, f.cutover, true);
    expect((await read()).evidence).toEqual(first.evidence);
  });
  it("commits owner checkpoints independently so an interrupted run can resume", async () => {
    const a = await legacy(),
      b = await legacy();
    await backfillUsageOwner(a.user.id, a.cutover, true);
    // Resume after a hypothetical process exit between owner transactions.
    await backfillUsageOwner(a.user.id, a.cutover, true);
    await backfillUsageOwner(b.user.id, a.cutover, true);
    for (const f of [a, b])
      expect(
        await boundary.db.user.findUnique({ where: { id: f.user.id } }),
      ).toMatchObject({ usageBackfillVersion: 1, usageCutoverAt: a.cutover });
  });
});

import { randomUUID } from "node:crypto";
import { PLANS } from "@/lib/plans";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { createCampaign } from "@/lib/campaigns";
import { importUsageEvidence, withUsageTransaction } from "@/lib/usage-ledger";

describe.runIf(databaseTestsEnabled)("campaign quota reservations", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
    await setGating(fixture.db, true);
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  it("replays one campaign without reserving again and rolls back an oversized batch", async () => {
    const f = await usageOwner(boundary.db),
      input = await f.input(2);
    const a = await createCampaign(f.user.id, input),
      b = await createCampaign(f.user.id, input);
    expect(a.id).toBe(b.id);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(2);
    await expect(
      createCampaign(f.user.id, await f.input(2)),
    ).rejects.toMatchObject({ allowance: "DAILY", remaining: 1 });
    expect(
      await boundary.db.campaign.count({ where: { userId: f.user.id } }),
    ).toBe(1);
    const sends = await boundary.db.send.findMany({
      where: { campaign: { userId: f.user.id } },
    });
    expect(
      sends.every(
        (s) =>
          +s.queueExpiresAt! - +s.createdAt <= 86400000 &&
          +s.queueExpiresAt! - +s.createdAt > 86399000,
      ),
    ).toBe(true);
  });
  for (const allowance of ["DAILY", "MONTHLY"] as const)
    it(`lets exactly one of 20 campaigns take the final ${allowance} slot`, async () => {
      const f = await usageOwner(boundary.db);
      if (allowance === "DAILY")
        await createCampaign(f.user.id, await f.input(2));
      else
        await withUsageTransaction(boundary.db, f.user.id, async (owner) => {
          const at = new Date();
          at.setUTCDate(1);
          at.setUTCHours(0, 0, 0, 0);
          for (let i = 0; i < 14; i++)
            await importUsageEvidence(owner, {
              sourceKey: `old:${i}`,
              deliveryKey: null,
              chargedAt: at,
              timestampSource: "sentAt",
            });
        });
      const inputs = [];
      for (let i = 0; i < 20; i++) inputs.push(await f.input());
      const results = await Promise.allSettled(
        inputs.map((input) => createCampaign(f.user.id, input)),
      );
      expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
      for (const r of results)
        if (r.status === "rejected")
          expect(r.reason).toMatchObject({ allowance, remaining: 0 });
      expect(
        await boundary.db.campaign.count({ where: { userId: f.user.id } }),
      ).toBe(allowance === "DAILY" ? 2 : 1);
    });
  describe.each([false, true])("repeat quotas (paid=%s)", (paid) => {
    async function priorDelivery(userId: string, email: string) {
      const deliveryKey = randomUUID();
      const sentAt = new Date("2025-01-01T00:00:00Z");
      await withUsageTransaction(boundary.db, userId, (owner) =>
        importUsageEvidence(owner, {
          sourceKey: deliveryKey,
          deliveryKey,
          chargedAt: sentAt,
          timestampSource: "sentAt",
        }),
      );
      await boundary.db.deliveryReceipt.create({
        data: {
          userId,
          deliveryKey,
          recipientEmail: email,
          createdAt: sentAt,
          sentAt,
        },
      });
    }
    for (const allowance of ["DAILY", "MONTHLY"] as const)
      it(`counts repeat sends toward the ${allowance} allowance`, async () => {
        const f = await usageOwner(boundary.db, { paid });
        const periods = resolveUsagePeriods(f.user);
        const input = await f.input();
        const contact = await boundary.db.contact.findFirstOrThrow({
          where: { id: input.recipientIds[0], userId: f.user.id },
        });
        await priorDelivery(f.user.id, contact.email);
        const period = allowance === "DAILY" ? periods.daily : periods.monthly;
        // One remaining slot accepts a repeat; the next repeat must fail.
        await withUsageTransaction(boundary.db, f.user.id, async (owner) => {
          for (let i = 0; i < period.limit - 1; i++)
            await importUsageEvidence(owner, {
              sourceKey: `repeat-quota:${i}`,
              deliveryKey: null,
              chargedAt: period.startsAt,
              timestampSource: "sentAt",
            });
        });
        const repeated = { ...input, resendIds: input.recipientIds };
        const campaign = await createCampaign(f.user.id, repeated);
        expect(campaign.count).toBe(1);
        expect((await createCampaign(f.user.id, repeated)).id).toBe(
          campaign.id,
        );
        const next = await f.input();
        const nextContact = await boundary.db.contact.findFirstOrThrow({
          where: { id: next.recipientIds[0], userId: f.user.id },
        });
        await priorDelivery(f.user.id, nextContact.email);
        await expect(
          createCampaign(f.user.id, { ...next, resendIds: next.recipientIds }),
        ).rejects.toMatchObject({ allowance, remaining: 0 });
        expect(
          await boundary.db.usageReservation.count({
            where: { userId: f.user.id, status: "RESERVED" },
          }),
        ).toBe(1);
      });
    it.each(["QUEUED", "ATTEMPTING", "UNCERTAIN"] as const)(
      "blocks an explicit repeat while delivery is %s",
      async (state) => {
        const f = await usageOwner(boundary.db, { paid });
        const input = await f.input();
        const campaign = await createCampaign(f.user.id, input);
        if (state !== "QUEUED")
          await boundary.db.send.updateMany({
            where: { campaignId: campaign.id, campaign: { userId: f.user.id } },
            data: {
              deliveryState: state,
              ...(state === "UNCERTAIN" ? { status: "FAILED" as const } : {}),
            },
          });
        await expect(
          createCampaign(f.user.id, {
            ...input,
            idempotencyKey: randomUUID(),
            resendIds: input.recipientIds,
          }),
        ).rejects.toThrow("All selected contacts were skipped");
        expect(
          await boundary.db.campaign.count({ where: { userId: f.user.id } }),
        ).toBe(1);
      },
    );
    it("applies the campaign recipient cap to repeat sends", async () => {
      const f = await usageOwner(boundary.db, { paid });
      const cap = PLANS[paid ? "PAID" : "FREE"].campaignRecipients;
      const input = await f.input(cap + 1);
      await expect(
        createCampaign(f.user.id, { ...input, resendIds: input.recipientIds }),
      ).rejects.toMatchObject(
        paid ? { name: "ZodError" } : { code: "CAMPAIGN_RECIPIENT_LIMIT" },
      );
      expect(
        await boundary.db.campaign.count({ where: { userId: f.user.id } }),
      ).toBe(0);
    });
  });
  it("fails closed for historical owners without a checkpoint and initializes a genuinely new owner", async () => {
    const old = await usageOwner(boundary.db, { ready: false });
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: old.user.id,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: new Date(),
        sentAt: new Date(),
      },
    });
    await expect(
      createCampaign(old.user.id, await old.input()),
    ).rejects.toMatchObject({ code: "USAGE_NOT_READY" });
    const fresh = await usageOwner(boundary.db, { ready: false });
    await createCampaign(fresh.user.id, await fresh.input());
    expect(
      await boundary.db.user.findUnique({ where: { id: fresh.user.id } }),
    ).toMatchObject({ usageBackfillVersion: 1 });
  });
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { saveContact } from "@/lib/actions";
import { readShortlist } from "@/lib/shortlist";

function form(email: string, id?: string) {
  const data = new FormData();
  data.set("email", email);
  data.set("name", "Updated person");
  data.set("jobRole", "Software Engineer Intern");
  if (id) data.set("id", id);
  return data;
}

describe.runIf(databaseTestsEnabled).each([false, true])(
  "repeat contact saves (paid=%s)",
  (paid) => {
    let fixture: Awaited<ReturnType<typeof usageFixture>>;
    beforeAll(async () => {
      fixture = await usageFixture();
      await setGating(boundary.db, true);
    });
    afterAll(async () => {
      if (fixture) await fixture.close();
    });

    async function owner() {
      const f = await usageOwner(boundary.db, { paid });
      boundary.user.mockResolvedValue({ id: f.user.id });
      return f;
    }
    async function receipt(userId: string, email: string) {
      await boundary.db.deliveryReceipt.create({
        data: {
          userId,
          recipientEmail: email,
          createdAt: new Date(),
          sentAt: new Date(),
        },
      });
    }

    it.each(["SENT", "REPLIED"] as const)(
      "restores re-additions after %s without duplicating the archived contact",
      async (status) => {
        const f = await owner();
        const contact = await boundary.db.contact.create({
          data: {
            userId: f.user.id,
            name: "Original",
            email: "[REDACTED_EMAIL]",
            archivedAt: new Date(),
            shortlistRemovedAt: new Date(),
          },
        });
        await boundary.db.campaign.create({
          data: {
            userId: f.user.id,
            templateId: f.template.id,
            status: "COMPLETED",
            sends: {
              create: {
                contactId: contact.id,
                recipientEmail: contact.email,
                status,
                deliveryState: "DONE",
                sentAt: new Date(),
              },
            },
          },
        });
        expect(await saveContact(form("  [REDACTED_EMAIL]  "))).toMatchObject({
          ok: true,
        });
        expect(await saveContact(form(contact.email))).toMatchObject({
          ok: true,
        });
        expect(
          await boundary.db.contact.findFirst({
            where: { id: contact.id, userId: f.user.id },
          }),
        ).toMatchObject({
          name: "Updated person",
          archivedAt: null,
          shortlistRemovedAt: null,
          followUpRequestedAt: expect.any(Date),
        });
        expect(
          await boundary.db.contact.count({
            where: { userId: f.user.id, email: contact.email },
          }),
        ).toBe(1);
        expect((await readShortlist(f.user.id)).contacts).toHaveLength(1);
        expect(
          await boundary.db.send.count({
            where: { campaign: { userId: f.user.id } },
          }),
        ).toBe(1);
      },
    );

    it("allows receipt-only addresses, including changes to an existing contact email", async () => {
      const f = await owner();
      await receipt(f.user.id, "[REDACTED_EMAIL]");
      const contact = await boundary.db.contact.create({
        data: {
          userId: f.user.id,
          name: "Original",
          email: "[REDACTED_EMAIL]",
        },
      });
      expect(
        await saveContact(form("[REDACTED_EMAIL]", contact.id)),
      ).toMatchObject({ ok: true });
      expect(await saveContact(form("[REDACTED_EMAIL]"))).toMatchObject({
        ok: true,
      });
      expect(
        await boundary.db.contact.count({ where: { userId: f.user.id } }),
      ).toBe(1);
      expect((await readShortlist(f.user.id)).contacts[0]).toMatchObject({
        id: contact.id,
        previouslySent: true,
        followUp: true,
      });
      expect(
        await boundary.db.send.count({
          where: { campaign: { userId: f.user.id } },
        }),
      ).toBe(0);
    });

